window.__D("text/torat-chaim/c011",{"p":[[2300680427,"יודע בשרש ומקור של החכ' ושכל הנברר באותיות הללו ע\"כ יכולים לדרוש על כל אות כו' ונק' ג\"כ סופר שסופר כל האותיות כמ\"ש אי' סופר כו' שהן חכמי תושבע\"פ שסופרי' כל האותיות כו' ונק' דברי סופרים כו' שלמע' מבחי' ספר דתושב\"כ שהרי יכול להוסיף ולגרוע ודורשי' על כל קוץ תלי תלי כו' (כמשי\"ת) וד\"ל. וזהו מה גדלו מעשיך ה' כו' פי' מעוצם כח גדולת מעשי ה' שהוא בא בכח העצמי' דא\"ס הנמשך ומתפשט עד למטה מעילה לעילה עד שיוכל להיות בחי' נאצל ונברא כנ\"ל (כמו ענין מהלך ת\"ק שנה מרקיע לארץ כנ\"ל) וכך ידוע שכל עילה המשפיע לעלול אינו משפיע רק מחלק העשירי שבו שהוא בחי' האותיות שבו לבד שהוא בחי' מל' שבו והט' חלקים הראשוני' מכתר וחו\"ב עד בחי' מל' נשאר בהעלם עצמות המשפיע רק שמכחם הוא יורד ונמשך בעצמו בצמצומי' כו' כמו מרצון לשכל ומשכל למדות עד שנברר אופן השפע להמקבל שזהו באותיות שבו לבד וכמו ממזלות הרוחני' לד\"י עד חלק הדומם ומשמרי האופנים למזלות וכך עד רום המעלות גבוה מעל כו' שבכלל כללות העולמות דבי\"ע נק' עלול והמשפיע הוא בחי' כלים דמל' דאצי' שהן בחי' האותיות וצרופי' שבאים במדה ושיעור כמ\"ש המוציא במספר כו' וט' ספירות דמל' הוא בבחי' האצי' ממש עד אור העצמי' דמאצי' נשאר הכל בהעלם דעצמי' גם שיורד מכח העצמי' עד שעלה ברצונו להאצי' היינו רק מבחי' האותיות דבחי' מל' דא\"ס בקו\"ח שנק' קו המדה בכלל כידוע אבל זהו בחי' בירור ההשפעה שבאה אחר העומק דחכ' בהעלם העצמי' תחלה כנ\"ל בענין סופר וספר כו' כי בבחי' אותיות הללו הרי הן באים במספר מכוון וההתכללות ע\"פ עומק החכ' הנעלמה בעצמות ממש וד\"ל) והנה בזה ניכר גודל עומק מחשבתו כי מסוף מעשה הבאה בגילוי לא נודע תחלת עומק המח' רק שכבר באה מן המח' מן ההעלם לגילוי שהוא מה שהוברר מכל העומק כו' אבל בגדולת מעשיו שהן ריבוי הצמצומי' והעלמות להיות עולמות הנעלמים בתחלה עד שבא בגילוי כו' מזה ניכר בעוצם הפלאת ערך עומק המח' וחכ' הנעלמים דאם במעשה הוא גדול כך כ\"ש בעומק המח' שקדם לבחי' המעשה כו' וד\"ל. והיינו בחי' נפלאותיך ומח' דפנימי' ח\"ע הקדומה שהן בהעלם דעצמי' א\"ס ונק' אמון מוצנע ומופלא כמו אומן הבונה עפ\"י הלוח שבידו שיודע השורש ומקור דחכ' זו שמצויר כך וכך דוקא ע\"כ נק' אמון מוצנע ומופלא דוקא כמ\"ש בסופר וסיפור דבחי' סופר הוא בחי' שכל הנעלם שבעומק המח' דח\"ע העצמי' שלתבונתו אין מספר כלל שמשם נברר האופן דציור האותיות הללו כנ\"ל שנמשך ויורד למטה בקו\"ח להאציל כו' שנק' קו המדה בכלל (וז\"ש דגליף גליפו בטה\"ע ששיער בעצמו בכח מה שעתיד כו' ושיעור זה בא במדה במספר אותיות שהן כמו בחי' ס\"ר אותיות דתושב\"כ כמ\"ש אז ראה כו') וכ\"ז העומק דמח' הנ\"ל שבא בגילוי אינו רק מה ששייך לאופן בנין העולמות לבד כמו הציור בלוח הבונים (שז\"ש ברא בספר דאסתכל באורייתא וברא כו') שיש בזה ב' מדריגות דסופר וספר הנ\"ל ואין זה ערך כלל לגבי מהו\"ע דח\"ע העצמי' שבא\"ס ממש"],[2300680430,"שהוא עצם האור דתוה\"ק שהי' שעשועי' אצלו כו' רק שירד להיות בבחי' אמון להיות מקור לחכ' שבבנין כל העולמות כמ\"ש ואהי' אצלו אמון וכתי' בה ה' קנני כו' (וז\"ש מה רבו כו' כולם בחכ' דתו' עשית בקו המדה כנ\"ל מלאה הארץ קניניך דתוה\"ק דכתי' ה' קנני כו') וזהו לפני א' דע\"ס במקורם בקו\"ח מה אתה סופר ועכ\"ז יש שם בחי' ספר וסופר והוא בחי' האותיות דתוש\"מ שלמעלה מהיות מקור לחכ' דמע\"ב בציור הלוח כו' שהוא בבחי' מקיף על כל ההשתלשלות דקו\"ח שלא יוכל להתצמצם אף בהעלם דמח' ורצון דמל' דא\"ס בקו\"ח כו' וזהו מאד עמקו מח' העצמי' שזהו בבחי' סופר דסה\"ח דתוש\"מ העצמי' כו' והיינו ג\"כ בחי' נפלאותיך ומחשבותיך אלינו דגם שא' מאד עמקו כו' עכ\"ז בבחי' אותיות התו' הנגלית נתלבש בה מבחי' נפלאותיך דחכ\"ע העצמי' להיותה בבחי' הבירור הנברר מכל העומק דח\"ע העצמי' כמו ששואב בכד כו' שכל העצמי' דח\"ע ופנימי' העונג ורצה\"ע מלובש בה כמו הסופר שאחר העיון הרי כל בחי' העומק דחכ' הלביש באותיות הללו דוקא וד\"ל:\n(יג) <b>והנה</b> מבואר למעלה דמדריגה הג' בחי' סיפור הוא במדריגה דסופר מצד כח הסיפור לפרש ולבאר האותיות וצירופי' כו' והוא בחי' ח\"ת תושבע\"פ מל' קרינן לה שמבאר ומפרש לאותיות וצירופי' דתושב\"כ כנ\"ל דיש בינה יתירה באשה כו' שעולה במקור ושרש דח\"ע הנעלמה הנ\"ל וזהו שיודעים למה נברר כך וכך לכך יכולים להוסיף ולגרוע כו' וכמו ר\"ע דרש על כל קוץ כו' בתוס' מרובה על העיקר וכמ\"ש במ\"א ע\"פ ס' המה מלכות כו' ועלמות אין מספר שהן הלכות דתושבע\"פ שנק' עלמות שאין להם מספר כלל וכלל וכמו שאנו רואים בחידושי הדינין בתושבע\"פ שמחדשים חכמי ישראל בכל דור ודור עד אין שיעור כלל והיינו ע\"י פלפולים רבים ושוני' כו' שזהו בחי' הבירורי' דרפ\"ח ניצוצי' דתוהו שנפלו בק\"נ בעה\"ד טו\"ר למטה וכמו בטו\"ט שמבדיל בין טמא גמור לטהור ובין כשר לפסול כו' ואע\"פ שכבר נא' בתושב\"כ הבדלה זו בכלל כמ\"ש להבדיל כו' אבל בחי' פרטים שבהל' טו\"ט ואו\"ה כו\"פ ה\"ז נמשך מכח המקור דח\"ע דתושב\"כ שנק' נפלאותיך כו' למטה בח\"ת בחכמי תושבע\"פ דוקא וכמו הסופר שיודע איך לכתוב הספר לכך נק' סופרים שסופרים כל האותיות דתור' כמ\"ש אי' סופר ואי' שוקל ששוקלי' כו' בגזירות וסייגים דד\"ס שע\"ז א' לא תסור כו' ואם לא הבירור דסופרים בפרטי ההלכות והדינין של כל מצוה לא היו יודעין גילוי רצה\"ע שבמצו' כלל כמו בכל מ\"ע כציצית ותפילין לא נודע כלל איך לעשותם בפרט רק ע\"י הדינין והלכות הפרטי' דהל' צו\"ת וכה\"ג בכל המצות וכן בדקדוקי סופרים בכל פרט ופרט גם בגזירות וסייגים שלהם כו' וע\"כ אין להלכות המחודשים מספר כלל וכמ\"ש במ\"א ע\"פ סלסלה ותרוממך שההלכות נק' נימין ושערות כמו כל שערה ושערה יש לה גומא בפ\"ע שמשם יונקת מן המוח שבראש כך כל הלכה והלכה יש לה שרש המשכה ויניקה מפנימי' החכ\"ע שבראש (שלמעלה מגוף המוחין דחו\"ב שבראש מאחר שיוצאין השערות בדרך בקיעה מצד בחי' המותרי מוחין"],[2300680433,"שלא יוכלו להתיישב במוח כו') וכל שערה צומח מצד תוס' מרובה שבחכ' על העיקר וראי' מזקן שקנה חכ' ממקורה כו' וע\"כ פרטי ההלכות אין להם מספר כמו שאין מספר לשערות והיינו ענין הסלסול בשערות שמפרידם זו מזו להיות כ\"א על מקומו כו' ולזאת ודאי בהכרח שיחודש דינין והלכות ע\"י הפלפול שהוא הקושי' ותירוצ' לאין מספר כמו שיהי' עולה אחר רב הפלפול כמה דינים הלכות חדשים שיהי' בזה האופן והענין הדין כך וכך ובזה האופן ובזה הענין יהי' הדין כך וכך שזהו כל עיקר ענין התירוצי' לקושי' בפלפול כמו ל\"ק כאן כו' וכמ\"כ בחידושי הדרשות על כל קוץ וקוץ תלי תלי' של הלכות כמ\"ש בר\"ע ע\"פ קווצותיו תלתלי' כו' (וא' בזוהר באד\"ר שכל ההלכות שהן בחי' הנימין ושערות שלמעלה כל נימא ונימא להיט לעלמין סתימין כו') והנימין הן באין מבירורי' דרפ\"ח מלמטה למעלה דוקא שהוא בירור דח\"ת דתושבע\"פ דוקא כמו ע\"י הפלפול שא' במחשכי' הושיבני זהו תלמוד בבלי כו' להיותם בבחי' הבירורי' להפוך חושך לאור דהיינו שמבחי' ההעלם ומקור דחכמה יבא לגילוי אור בתוס' מרובה על העיקר האור דחכ' כמו הקושי' שהן בבחי' ההעלם וההסתר להעלים אור האמת והתירוץ הוא להאיר החשך הזה שזהו בא בהכרח מבחי' העלם דפלאות חכ' כו' כמ\"ש במ\"א וע\"כ נמשלו ההלכות לשערות שבוקעים מהעלם אור המקיף דחכ' כנ\"ל וד\"ל. ושרש הענין הוא כידוע שבתו' יש ב' מדריגות ח\"ע וח\"ת כמ\"ש חכמות בחוץ כו' והיינו בחי' סו\"ג כמ\"ש הנסתרות כו' והנגלות כו' והענין הוא כנ\"ל דבחי' סתים דתורה הוא ח\"ע שבתוה\"ק שנק' ספר שבא באותיות כמו בכ\"ד ספרים כו' ואע\"פ שלתבונתו העצמי' אין מספר כלל אבל צמצם והלביש כל פנימי' ועצמי' דחכ' ש\"מ במספר זה שנק' סה\"ח (שהוא בחי' עה\"ח) (וכמ\"ש משה מחני נא מספרך אשר כתבת) וכמו שמלבישים לשכל עמוק מאד בדברי משל כשלמה שא' ג\"א משל כו' ויהי שירו כו' (כך התוה\"ק נק' משל הקדמוני) וכמו הסופ' שמביא כל העומק דחכ' באותיות בספר כנ\"ל ומספר זה הוא שנמשך להיות אופן החכ' ורצון דמע\"ב כמ\"ש ואהי' אצלו אמון כו' כלוח הבוני' כו'. והנה קודם מ\"ת טרם שירד אור דחכ\"ע דתוה\"ק בגילוי ביוה\"ד הי' כל העולמות העליוני' בעולם האצי' ובי\"ע עד עוה\"ז השפל מכולם ניזוני' ומקבלי' אור שפע חיותם רק מחסדו של עצמו' א\"ס ב\"ה כי חפץ חסד הי' בתחלת הרצון להאציל ולברוא כו' כידוע שמה שעלה ברצה\"פ כו' הי' בחי' אתעדל\"ע מצד עצמו בבחי' חסד וטוב העצמי שמטבע הטוב להיטיב כמ\"ש בע\"ח ואמנם בחי' חפץ לחסד זה הי' ראשית מקורו בבחי' הח\"ע דתוה\"ק שנק' תורת חסד ג\"כ להיותה באה מלמע' למטה מצד עצמי' החכ' בבחי' או\"י וכמ\"ש פיה פתחה כו' ותורת חסד על לשונה (וזהו שנק' לחם מן השמים כמו שהתו' מן השמים ניתנה וזהו כמו מזון המן שלא הי' בו פסולת כלל וכלחם פנג ולחם הפנים שכולו פנים וטוב שהוא בחי' עה\"ח יבא בעדן עצמו כו') (וזהו כי אמרתי עולם חסד יבנה אמרתי בספה\"ח דתוה\"ק בחסד דח\"ע שנק' תורת חסד דוקא מטעם הנ\"ל) אבל אחר מ\"ת שירדה התו\"מ בגילוי"],[2300680436,"לברר בעה\"ד טו\"ר כידוע שז\"ש דאורייתא מח\"ע נפקת לברר במדות שבחכ' להבדיל בין כו' אז נמשך מקור השפע ומזון וחיות של כל העולמות ע\"י התורה שלמטה דוקא והוא ע\"י מעה\"ת שעושי' הבירור בין טו\"ר בחכ' דתו\"מ שלמטה דוקא (וכמ\"ש בע\"ח דבתחלת ההשתלשלות הי' בבחי' חפץ חסד בלבד ואח\"כ תלוי הכל במעה\"ת כו') והענין הוא שזהו בחי' ומדריגה הב' דתו' שנק' ח\"ת (שזהו כאשר ירדה התו' למטה בארץ דוקא כמו הארץ האירה מכבודו ואין כבוד כו' וכמ\"ש לא בשמים הוא כו' כי קרוב אליך דוקא כו' וכן א' לעשות חסד ומשפט כו' בארץ דוקא כי באלה חפצתי שזהו שלימות דחפץ ורצה\"ע שבח\"ע דתוה\"ק (כמשי\"ת) והוא ע\"י הבירור דעה\"ד טו\"ר בחכ' דתו' שבחכ' אתברירו רפ\"ח כו' (והוא שנק' לחם מן הארץ כמ\"ש לכו לחמו בלחמי דלחם מן השמים דתוה\"ק נמשך בלחמה ש\"ת שלמטה דוקא כמ\"ש חכמות בחוץ כו' דח\"ע הוא דאתמשך בח\"ת דתושמ\"ע הוא שנותן כח ועוז לח\"ת בתו' שלמטה לברר לעה\"ד כו'). וזהו ארץ ממנה יצא לחם לחמ' דתו' כו') וכמשל הארץ הזאת הגשמי' שיש בה כח הצומח להצמיח כל צמח עשב וכל עץ עושה פרי טוב כו' וכל תבואות הארץ שיש בהן מזון וחיות רב לכל הברואים שבארץ מאדם עד בהמה כו' שמזה ניזונין הכל להתקיים בחיותם ומציאותם תמיד וכמו גם האדם שמאכלו בשר החי לבד הרי עיקר גידול של החי כבהמה הוא ממה שאוכלת העשב מן הארץ ונמצא כל מזון וחיות האדם הכל מן הארץ וגם כל מיני תענוג מצמיח מן הארץ דוקא וכטעמי' הטובי' בארץ בפירות כו' וכל עיקר ענין הצמיחה הזאת מן הארץ בא ע\"י בחי' הבירור דוקא שזהו מה שנברר חלק הטוב הגנוז בארץ מן בחי' הרע שבו אחר הזריעה וחרישה כו' (שנק' טובה דגניז בגווה כמ\"ש בזוהר) ואמנם הנה זאת מעלה יתירה יש בארץ שכח הצומח שבעפר הארץ יכול להצמיח עד אין שיעור כלל וכמו עשב הארץ צומח בלי שיעור גם שקוצרים השחת חוזר וצומח מחדש והוא מפני שיש כח בצומח שבארץ לחדש תולדות מאין ליש בלי שיעור וגבול כלל בחידוש מעיקרו דוקא שהרי גם בדבר הזרוע בארץ מצמיח בתוס' מרובה על העיקר בכפלי כפליי' כמו חטה הזרוע בארץ שתצמיח בריבוי כי יש בארץ דוקא כח החידוש יש מאין ממש והטעם ידוע לפי שנתב\"ס דוקא והארץ הוא בחי' דומם סוף הכל ע\"כ נעוץ בה מבחי' תחלת הכל כו' וע\"כ הכל הי' מן העפר אפי' האדם בחי' מדבר שהרי ארץ מגדלת חכמי' וגופו של אדה\"ר מן העפר הי' כלי לאור הנשמה העליונה דפרח' מחה\"ע כו' וכמ\"ש במ\"א וד\"ל. ומכ\"ז יובן ג\"כ בענין לחם מן הארץ שמוסיף כח בחכ' שבאדם (דלחם גי' מזלא) היינו לחמו דתושמ\"ט הנגלי' לנו (שבאה בהתלבשות בעה\"ד טו\"ר בארץ לברר בין טו\"ר כו') וזהו כמו הזריעה שבארץ שמצמיח רב תבואות וכל מיני עונג בחידוש מאין ליש לאין שיעור כך הלכות דתושבע\"פ דוקא שהן בחי' צומח כשערות כנ\"ל שענין צמיחתן הוא בא בחידוש מאין ליש מח\"ת דכנ\"י בכל דור בלי שיעור וגבול כלל שהרי מתחדשים הלכות ודינין רבי' לאין שיעור מן הפלפול דחכמי תושבע\"פ יותר מגופו של ח\"ע דתושב\"כ והוא"],[2300680439,"בחי' או\"ח מלמטה למעלה שעולה מבירור דרפ\"ח כו' שמצד שנעוץ סוף בתחלת הכל מגיע זה בשרש ומקור דח\"ע הקדומה להיות תוס' אור מבחי' התעה\"פ העצמי שנק' שעשועי המלך בעצמו' ממש (שהוא בחי' עדן דעוה\"ב) שמאיר באור התענוג ושעשועי' שבתוה\"ק בתוס' מרובה על עיקר העונג ושעשועי' להיות משתעשע בתוה\"ק בתחלה משום דבחי' או\"ח עולה לקדמות העצמי' ממש ולזאת בחי' סיפור דתושבע\"פ עולה למעלה גם מבחי' סופר הנ\"ל אחר תשלום הבירורי' דח\"ת דוקא בהלכות הבירורין שע\"י הפלפול שיש בזה יתרון אור מן החושך וההעלם שלמעלה מאור קדמאה דח\"ע הקדומה כו' (ולזה א' דכל השונה הלכות בכל יום שהן הלכות הבירורים בטעמיהן מובטח לו שהוא בן עוה\"ב שנק' עולם הבירור כידוע) כי בחי' סופר הנ\"ל הוא המגביל לעומק ח\"ע שלתבונתו אין מספר במספר קצוב בספה\"ח הנ\"ל (וכמו בכ\"ד ספרים כו') אבל בחי' סיפור דח\"ת בחידושי' דהלכות שעולי' מן הפלפול הרי הן בלי מספר וגבול כלל והן בחי' יש מאין המוחלט שזהו כמו שהוא באין האמיתי דעצמות ח\"ע שבא\"ס ב\"ה עצמו ממש קודם שנמשך במספר אותיות דספר העליון כו' והוא בחי' שעשועי' העצמיי' שבח\"ע העצמי' ממש שלמעלה מבחי' השעשועי' שלו שנמשך אפס קצהו בחכ' דתוה\"ק כנ\"ל וזהו מאד עמקו מחשבותיך מאד בלי שיעור ומספר כלל וכן מ\"ש נפלאותיך ומח' כו' ומה שמשעשועי' הללו נמשך גם אלינו בסה\"ח כמו גם באותיות הנגלי' לנו בתושב\"כ אין ערוך אליך ממש וזהו אגידה ואדברה באותיות דתושב\"כ שנק' ספר שמגביל בחי' הפנימי' ועצמי' דח\"ע שנק' נפלאות כו' אבל מ\"מ עצמו מספר והוא בסיפור דתושבע\"פ שהן ההלכות שאין להם מספר כלל וכמ\"ש ועלמות אין מספר כלל משום דשרשו מגיע בתבונתו העצמי' שאין לו מספר כו' וזהו שהלכ\"ה אותיות הכל\"ה כו' ור\"ת הלכ\"ה הריעו לה' כל הארץ כו' שעולה באו\"ח מן הארץ כיתרון האור מן החושך כנ\"ל בצומח דתבואות הארץ שמצמיח לאין שיעור כנ\"ל וזהו עצמו מספר לפי שהוא למעלה מבחי' סופר כנ\"ל ועכ\"ז נק' תושבע\"פ סיפור ונק' סופרים דוקא שסופרים כל אותיות דתושב\"כ דוקא שנק' ספר כנ\"ל (כמשי\"ת):\n(יד) <b>והנה</b> כמו שמבואר למעלה בלחם מן הארץ הגשמי' ממנו מזון האדם וחיותו וקיומו כך הוא למע' ממש דבחי' לחמה ש\"ת שלמטה שנק' לחם מן הארץ הוא דוקא נעשה בחי' מזון וחיות להוסיף מוחין חדשים בחכ' אדה\"ע דאצי' (כמו שבאדם למטה נמשך תוס' מוחין בנשמה האלקי' מלחמה דתו' הנגלית כמו ותורתך בתוך מעי כו') וגם האור והשפע הנמשך לכל העולמות כמרכבה דפני ארי' ופני שור כו' ושרפי' וחיות ואופני' עד המזלות שברקיע וכל צבא השמים והארץ וכל אשר בה מקבלים כולם שפע האלקי' הרוחני' מלחמה דתו' הנגלית לנו שבעוה\"ז השפל דוקא וכמ\"ש אם לא בריתי יומם ולילה (שהוא מצות ת\"ת בוקר וערב) חוקות שמים וארץ לא שמתי חוקות לשון מזון כו' וכן חוקות ענין חקיקה שהן אותיות שנבראו בהן כל העולמות שנמשך מאותיו' התו' דוקא כידוע שאין העולם מתקיים אלא בהבל תינוקות של בית"],[2300680441,"רבן כו' וכמו ואשים דברי בפיך כו' לנטוע שמים וליסוד ארץ (והיינו כל הדינין והלכות דתושבע\"פ שמדברים באו\"ה טו\"ט כו\"פ כו' שזהו בכל חלקי דצח\"מ דעוה\"ז זהו עצמו שרש שפע חיותם האלקי' למעלה) וכמו שהחי ניזון מן הצומח והאדם מן החי וצומח שבארץ לאחר שנברר הטוב מן הרע שזהו בחי' הטוב הגנוז בארץ שממנו מזון כל חי והאדם ממש כך הוא ממש מזון דחכמה דתושבע\"פ שנברר מן הארץ בחי' הטוב הגנוז שיש בלחם זה שמן הארץ כמו ע\"י הפלפול דוקא הוא שממשיך מזון העליון לכל העולמות העליוני' דאבי\"ע וגם לפני האצי' (וכמו דקוב\"ה משתעשע בקלא דאורייתא שלומדי' בג\"ע ובעוה\"ז בטו\"ט ואו\"ה דוקא כמו היושבת בגנים חברים כו' וכן השמיעני כו' כי קולך ערב והוא ד\"ס שערבי' יותר מיינה ש\"ת מטעם הנ\"ל) וע\"כ נק' ת\"ח בוניך שעוסקים בבנינו ש\"ע שזהו מ\"ש לנטוע שמים כו' להיותם בבחי' סופר שסופרים כל האותיות שבתורה שהוא עיקר שם מ\"ה דתיקון שבחכ' יבנה בית בכל אופן ציורי הפרטי' (ולזה א' מאן מלכי רבנן ומתניתא מלכתא כמלך שגוזר כו') ומבוא' למעלה בשרש ההלכות שמתחדשי' למטה ששרשם מגיע בתעה\"פ שבעצמי' א\"ס שלמע' מעונג דח\"ע דתוה\"ק הנק' ספר משום דנתב\"ס דוקא כו' (והוא מ\"ש בזוהר עמ\"ש בעדן עין לא ראתה (אפי' משה בתושב\"כ) כ\"א יעשה למחכה לו למאן דדייק מילין דחכמתא שהוא החידושי' דהלכות שע\"י עיון הפלפול כו' (שאין עונג יותר מהתרת הספיקות שהוא יותר עונג רב מעצם העונג שבפנימי' החכ' שבראש) (וכמו שרואים בחוש שמתענג אדם בעונג נפלא מאד בחידוש שכל וסברא ודין חדש שממציא מכח שכלו אחר העיון הטוב ביגיעת המוח מאד מלמטה למעלה (שדוחק כלי המוח ובוקע ועולה לכח המשכיל ההיולי להשכיל שכל חדש) הרבה יותר מהשכלת והשגת שכל שנופל לו מלמעלה מן השכל מאין ליש בלא יגיעה כמו שמקבל מרבו וכמ\"ש מתלמידי יותר מכולם כו' שז\"ש למאן דדייק דווקא שזה למחכ\"ה לו כמו איוב חכה לו כמ\"ש במ\"א). וא\"כ מובן מזה שכל מקור החיות ושפע כל העולמות שמקבלי' מח\"ע שבראש שא' כולם בחכ' עשית כלא ממש חשיבא לגבי מה שנמשך האור מפרט הלכה ודין א' דתושבע\"פ שהוא כמו שערה א' בלבד כנ\"ל במ\"ש סלסלה ותרוממך כו' לפי שאור רצה\"ע ותעה\"פ ועצמי שבהלכה זו היא למעלה הרבה מהתפשטות הרצון וחכ' שבאו בגילוי בכח כבר שנעשה לצורך בנין העולמות שאינו רק אפס קצהו בלבד וז\"ש מה גדלו מעשיך ה' במה שנמשך כבר לצורך התהוות העולמות מחכ\"ע שבא בסה\"ח העליון כנ\"ל אבל מאד עמקו מחשבותיך נמשך בצמצום ודילוג השפע בבחי' נימין ושערות בלבד והיינו פי' הלכות לשון הילוך כמו הליכות עולם לו הליכות אלי כו' וז\"ש באד\"ר דכל הלכה שנק' נימין להיט לעלמין סתימין דוקא שהן בבחי' המקיפים שבלתי מתיישבים בכלי' כלל כו' והיינו בחי' נפלאותיך ומח' העמוקות כמ\"ש מאד עמקו כו' דכתי' בה מגלה עמוקות מני חושך והיינו ע\"י הפלפול דוקא כנ\"ל) (ועכ\"ז הרי חכמי תושבע\"פ נקרא סופרי' שסופרי' כל האותיות ונק' סיפור שמספרים בדיבור"],[2300680443,"בפה עכ\"פ וע\"כ נק' תושבע\"פ דוקא כמו תורה צוה לנו משה כו' והוא שנק' משה מחוקק כו' מפני שבהם וע\"י נחקק כל חוקה והוא פרטי אופן המעשה של כל מצוה בדקדוקי' ושיעורי' דוקא והוא מה שמדקדקי' באותיות התושב\"כ שנק' דקדוקי סופרי' כו' ששרשם בזה למעלה הרי הוא בבחי' סופר ממש וז\"ש איה סופר בבחי' אי\"ה (כמ\"ש במ\"א) ומכ\"ז יתבונן האדם יקר מעלות התורה שלנו הנגלי' דוקא שנק' ספר והוא תושב\"כ כמ\"ש לא ימוש ספר כו' והגית כו' וביותר בתושבע\"פ (כמ\"ש העוסק במקרא מדה כו' עד התלמוד אין לך מדה גדולה כו') להיות נפשו חשקה בתו' בכל לב ונפש ויותר מחיי נפשו ממש וע\"כ ישמח וישיש בעסקו בתו' בעונג ושעשועי' נפלא למעלה מכל התענוגי' כמ\"ש דוד שש אנכי על אמרתך כו' בעדותיך ששתי כו' כמו שאנו אומרים ונשמח כו' וכן א' אני תורתך שעשעתי כו' והיינו שא' יקרה היא כו' כל חפצי' לא ישוו בה אפי' חפצי שמים לכאורה זה פלא גדול איך יהי' התור' יקרה יותר מחפצי שמים כו' שהן המצות שנק' חפץ ורצה\"ע שעיקר התו' הוא לקיום המצות ולא המדרש עיקר אלא המעשה כידוע אך הנה א' כ\"א בתורת ה' חפצו ובתורתו יהגה יומם כו' ומשמע ממ\"ש כ\"א לשלול גם חפצי שמים רק חפצו יהי' בתו' לבד והרי א' האומר אין לי אלא תו' אפי' תורה אין לו כו' אלא הענין הוא דמ\"ש בתורת הוי' חפצו זהו תושב\"כ שנק' ספר כמ\"ש לא ימוש כו' שזהו מצות ת\"ת בדיבור וכמ\"ש ודברת בם כו' ומ\"ש ובתורתו יהגה יומם ולילה זהו במצות עיון בתושבע\"פ שנק' הגיון במח' עמוקה ביותר שהוא כמו מאן דדייק מילי דחכ' שהן ההלכות שמתחדשים מפלפול בתלמוד וכה\"ג כנ\"ל וזהו שנק' תורתו ממש שהוא המחדש אותה כו'. והענין הוא כמבואר למעלה בענין שרש תושב\"כ ותושבע\"פ למעלה דאותיות תושב\"כ נק' ספר הוא בחי' הספר החיי' העליון כמ\"ש אז ראה ויספרה כו' שממנה נמצא מקור חיי כל העולמות דהיינו להיות לו רצון ותענוג להאציל ולברוא כו' שזהו עיקר ומקור קיום בנין העולמות דאבי\"ע שנבנה בחסד דכתי' תורת חסד כנ\"ל ומאחר שכן ודאי שכלא חשיב כל חפץ ורצה\"ע במע\"ב כמו בחכ' יבנה בית וברצון שבחכ' זו וגם בהתנהגות העולמות שנמשך מרצון וחכ' דתוה\"ק כמ\"ש כל אשר חפץ הוי' עשה בשמי' כו' שהכל במשפט התו' העליונה דוקא שנק' ג\"כ חפצי שמים העליוני' עז\"א כל חפצי' לא ישוו בה שכלא חשיב לגבי חפץ העצמי' שבתו' שהוא עצמי' דחכ\"ע ע\"כ א' כל חפצי' לא ישוו בה בערך כלל שגם האדם למטה כל חפצי' כמו בגילוי רצה\"ע וחכ' ומדות בנשמתו כמו בעת התפלה וק\"ש בהתפעלות אהוי\"ר והשגה האלקי' באה\"ר בתענוגי' שמעורר למעלה כמהפא\"פ אה\"ר העליונה להיות חפץ ה' בנשמתו כמו שחפץ לדבקה בו ית' גם בזה אף שנק' חפצי שמים לא ישוו בה בערך החפץ שבתו' וז\"ש כ\"א בתורת ה' חפצו אחר הרצוא שבתפלה שזהו עיקר החפץ ורצה\"ע בעצמות א\"ס ב\"ה ממש להיות שהתו' כלולה ומתאחדת במהו\"ע שלמעלה מגילוי רצונו וחכ' ומדותיו שמאירים למטה בע\"ס דאצי' כו' וז\"ש מי לי בשמים העליוני' שנק' חפצי שמים ועמך"],[2300680445,"לא חפצתי בארץ כו' ובאמת גם המצות שנק' חפצי שמים ממש כי הן בחי' פנימי' רצה\"ע שהוא ופנימי' רצונו א' ממש וע\"כ או' אשרי האיש כו' במצותיו חפץ מאד כו' ובשכר המצו' הוא העוה\"ב שנק' חיי עולם כו' וע\"כ צ\"ל עבודת המצות בשמחה וטוב לבב ונק' שש\"מ עכ\"ז א' גם ע\"ז כל חפצי' לא ישוו בה בערך חפץ התו' עצמ' וז\"ש באהבתה ישגה תמיד בלי הפסק כלל וישגה הוא למעלה מן הכלי כו'. והענין הוא מטעם הנ\"ל בשרש השעשועי' שבתו' ש\"מ כמ\"ש ואהי' אצלו שעשועי' שהוא בחי' שעשועי' העצמיי' שמשתעשע בח\"ע העצמי' שלתבונתו אין מספר כלל וכאשר בא האור בהגבלת האותיות בספר שנק' סה\"ח כנ\"ל (שזהו מקור העוה\"ב) זהו כמשל חכם גדול שא' דבר חכמה עמוקה ביותר ומלבישה במשל וסיפור שמשתעשע בחכ' זו שהובררה אצלו בשעשועי' העצמיי' שלו יותר מכל הון ביתו ויקרה היא בעיניו מכל חפצו יקר שלו וגם מחפצו ורצונו הפנימי' העולה מן החכ' הזאת הנפלאה דהיינו לעשות כך וכך כו' דמה שמתגלה מאור חכ' העמוקה ונפלאה בגילוי רצון העולה ממנה למעשה אין לו ערך לגבי גוף אור החכ' שכלולה בעצם כח חכמתו ממש שעונג העצמי' ממש מלובש בה בתכלית היחוד כו'. וכך יובן למעלה בשעשועי' דתוש\"מ שנק' סה\"ח שהוא למעלה ג\"כ מעונג ורצה\"ע שבמצו' שעולה ע\"פ העצמות דח\"ע הנפלאות שנק' נפלאותיך ומחשבותיך שכלולי' בעונג העצמי' ממש שלא יוכל לבא בגילוי והתלבשות בכל עלמין אפי' עלמין הסתימין ואפי' בעוה\"ב שאינו אלא מבחי' עונג ורצה\"ע שבמצו' וז\"ש כ\"א בתורת ה' חפצו לבד שלמעלה גם מחפצי שמים דמצו' בעוה\"ב שנק' פר\"ס (אותיות ספר) וד\"ל ומ\"ש עוד ובתורתו יהגה בעיון המח' העמוקה שהוא ההגיון כו' כנ\"ל וזהו בשרש מעלת העונג ושעשועי' שבהלכות שמתחדשי' מן הפלפול ביתרון האור מן החושך שהוא ההעלם העמוק ביותר שז\"ש מאד עמקו מחשבותיך כו' שמזה נמשך רק בבחי' נימין ושערות בבחי' צמיחה והצמיחה מחודש מאין המוחלט ולאין שיעור כלל כנ\"ל שזהו למעלה גם מבחי' סה\"ח דתושב\"כ כנ\"ל והוא מ\"ש למחכה לו למאן דדייק כו' והוא למעלה הרבה מן העונג דעדן בעוה\"ב בשכר התו\"מ בעוה\"ז וכמ\"ש וחד חרוב כו' והוא מ\"ש דת\"ח אין להם מנוחה אפי' בעוה\"ב שנא' ילכו מחיל כו' שאין לו שיעור למע' בעצמות השעשועי' שלמעלה משעשועי' שבתוה\"ק הגם שכבר הובררה בכח החכ' העצמי' כנ\"ל לפי ששלימות בירור זה הוא בח\"ת שמברר כו' בחידושי הלכות מתוך הפלפול דוקא (כמו אין חכם כבעל הניסיון) מטעם הנ\"ל וזהו ובתורתו ממש יהגה יומם ולילה שנק' תורתו שהוא למעלה מתורת הוי' דתושב\"כ וזהו שנק' תו\"א כמ\"ש ואהי' אצלו אמון מופלא דוקא מבחינת פלאות דח\"ע שלא יאיר רק בבחינת מקיף בלבד כנ\"ל וזהו שנק' עוסק בתו' לשמה לשם התורה עצמה שהוא תושמ\"ע לחברה בשעשועי' העצמיי' שנק' שעשועי המלך בעצמו' (וכמ\"ש בס' הבהיר דדוד הי' מחבר תוש\"מ בהקב\"ה בעצמו כו' כנ\"ל כמו אני תורתך שעשעתי כו' ובמה הי' לו כח לחברה ה\"ז בתושבע\"פ דוקא שנק' תורתו שמחדש מאין כו' בבחי' או\"ח"],[2300680447,"מלמטה למע' כנ\"ל) וזהו והי' כעץ שתול על פלגי מים כו' שיצמיח לעשות פרי למעלה ולמטה בלי הפסק כלל וז\"ש ע\"פ זה כ\"א בתו' ה' חפצו מעיקרא אדעתי' דנפשי' עביד להאיר נשמתו באור הוי' שבאותיות התושב\"כ כמ\"ש כי אמרתך חייתני כו' ואח\"כ ובתורתו יהגה לשם התו' עצמה כנ\"ל וד\"ל. (וזהו ה' חפץ למען צדקו יגדיל תו' ויאדיר פי' ה' חפץ בחפץ ה' וברצונו הפשוט הפנימי' ועצמי' ממש שלמעלה מחפצי שמים גם במצו' שבתוש\"מ רק למען צדקו העצמי' ופשוט שנק' צדקו ממש כו' שלמעלה מצדקה וחסד שבתו\"מ ש\"מ שנק' תורת חסד כנ\"ל והוא מה שיגדיל תו' ויאדיר שזהו בירידות אור דתוש\"מ למטה ממש לברר לעה\"ד טו\"ר להיות יתרון האור מן החושך דק\"נ ע\"י חידושי הלכות כנ\"ל שזהו בחינת הגדלה וריבוי דתו' עצמה שמגיע למעלה משעשועי' העליוני' שהי' בתוש\"מ תחלה מטעם הנ\"ל וזהו יגדיל ביו\"ד דחכ' שבסוף שמוסיף אור גדול בחכ' שבראש כמו גידול דצומח מן הארץ בתוס' וריבוי גדול כנ\"ל וגם פי' יגדיל שיגדיל לע\"ל בימוהמ\"ש שיהי' תשלום הבירורי' דרפ\"ח כו' שעי\"ז יבא כל העלם דפלאות ח\"ע לגילוי יותר מכמו שהי' כמ\"ש במשיח הנה ישכיל עבדי ישכיל עד אין שיעור למעלה ברזי' וסודות התוה\"ק ונק' פלא יועץ חכם חרשים כו' ומלאה הארץ דיעה כו' ויאדיר בעוה\"ב שהוא העדן שיתגלה מעצמות התעה\"פ שנק' שעשועי המלך בעצמו' באור דתו' בעליות עד אין שיעור למעלה כמ\"ש ילכו מחיל אל חיל כו' וד\"ל וז\"ש רז\"ל רצה הקב\"ה לזכות את ישראל בזכות וחסד העצמו' לפיכך הרבה להם תו\"מ שנא' ה' חפץ כו' פי' הרבה להם זהו בבחי' ריבוי והגדלה דאור דתו\"מ למטה דוקא לפי שכל חפצי' לא ישוו בה אפי' חפצי שמים העליונים כו' ומטעם הנ\"ל וד\"ל). ובזה יובן גודל מעלת ענין מס\"נ של יו\"ד הרוגי מלוכה על התו' עצמה ועל תושבע\"פ דוקא כר\"ע וחביריו שמעלי' מ\"נ עד ימוהמ\"ש (כמ\"ש בע\"ח):\n(טו) <b>והנה</b> אחר כל הנ\"ל יובן מה שא' דוד זמירות היו לי חוקיך בבית מגורי וא' שנענש דוד ע\"ז כנ\"ל דהנה דוד כל חפצו הי' רק בתו' ה' וכמ\"ש כ\"א בתו' ה' חפצו ובתורתו כו' וע\"כ היה שש ושמח מאד בעסקו בתו' כי כל חפצי' לא ישוו בה כלל כנ\"ל עד שא' זמירות היו לי חוקיך שהי' לו כמו זמירות ושירים נפלאים וערבים לנפש שמתענג אדם בהם לפקח נפשו בהתענגו בהם להסיר מלבו כל יגון ואנחה השוברת גופו ונפשו כמו בעוצם הפחד ורעדה ואימת מות ממגוריו שיגור מאויביו שרודפי' אחריו להרגו וחייו תלויי' לו מנגד ממש כו' עכ\"ז בתענוג הנפלא הזה שמזמר ומשורר שירות וזמירות הנפלאים וערבים לנפש ישיבו את רוחו ונפשו אליו ויסיר מלבו היגון והפחד כמו יושבי אניות בלב ימים כשהם בסכנה גדולה ישירו ויזמרו בזמירות הנעימי' להשיב רוחם וידעו להציל נפשם וכן אסירי ברזל יפקחו עוני נפשם בזה וגם המלך המרומם בהיותו ביגון ואנחה בעומק הנוגע לנקודה יזמרו לפניו ויערב להסיר מלבו הרוח רעה המבעתו וכמו שהי' בשאול כאשר הי' דוד מנגן לפניו כו' וכמו הזמר בכלי כך הוא השירה והזמרה בפה ממש כידוע"],[2300680449,"הרי יש כח גדול בזמר ושיר בהפלאת העונג ושעשועי' לדחות כל צער ויגון גם היותר קשה וכך א' דוד זמירות הי' לי חוקיך לפי שהי' משתעשע בהם בהפלאת העונג מאד מאד ע\"כ הי' לו כזמירות הערבים מאד לנפש להסיר מלבו אימת מות כו' והוא בהיותו ביגון וצער גדול מפחד אויביו הקמים עליו שהשיבו רוחו ונפשו כי כ\"כ גדלה הפלאת העונג בזמירות דתו' עד שנדחה מלבו כל פחד ואימת מות כו' ובזה עצמו נמתקו כל הדינין קשין שהן מתבטלי' למעלה ממציאותם לגמרי בהיות גילוי אור העונג ושעשועי' דעצמי' אוא\"ס שבתו' בזמירות שהוא רננא דאורייתא שאפס קצה מזה נמשך מקור כל חיות ושפע העולמות בפנימי' וחיצוני' כנ\"ל והוא שא' בבית מגורי דוקא בשעה שהי' יגור מאויביו הועילו לו זמירות דתו' להמתיק הדין הקשה ואין הדין נמתק אלא בשרשו והוא בבחי' גבו' הטובו' ומתיקו' דקדושה האלקי' והוא בחי' רשפי אש התענוג ושעשועים העליוני' שיש בתו' למעלה ולמטה הוא מה שהי' לו בזמירות בעריבות ועונג נפלא ברשפי אש התענוג (כמו ב\"ע הי' שונה ואש מלהטת סביבו אש דאור תוה\"ק בהיות נפשו חשקה בתו' עד שבאהבתה ישגה תמיד כנ\"ל) ועכ\"ז נענש דוד על שקראם זמירות בלבד אע\"פ שנק' רננא דאורייתא והן כמו נגינות וטעמים דתושב\"כ כנ\"ל שנק' שירים כו' וד\"ל וצ\"ל בעונג ושעשועי' גדולים אלא לפי שהשפיל מעלת יקר ערך דעונג ושעשועי' העצמיי' שבתו' הנ\"ל שהוא באמת למעלה מעלה מכל עיקר ומקור העונג ורצון שנמשך לבנין כל העולמות כמו ברצון ועונג להאצי' ולברוא כו' וכמ\"ש ואהי' אצלו אמון אמון מוצנע ומופלא דהיינו שגם מה שבחכ' דתוה\"ק יבנה בית (דבראשית ברא כו') זהו רק אפס קצה הארה בעלמ' מאור העצמי' דשעשועי' דתוה\"ק ולכך נק' אמון מופלא שהוא מבחי' פלא העליון והוא ענין נפלאותיך כו' והן בחי' סופר וספר וסיפור דתושב\"כ ושבע\"פ למעלה ולמטה שע\"ז א' ואהי' אצלו אמון כו' (וכולל ב' מדריגות דסה\"ח בשורש דתושב\"כ למעלה ושרש בחי' תושבע\"פ למטה שזהו כמו מי שתו\"א לחדש מאין המוחלט לאין שיעור כלל בהלכות שבתלמוד כו' שז\"ש ובתורתו יהגה כו' שנק' סיפור) ואח\"כ ואהי' שעשועי' יום יום שהן ג\"כ תושב\"כ ושבע\"פ כו' והן ב' אלפי' שנה שקדמו לעולם והוא העונג העצמי' שנק' שעשועי המלך בעצמו שמאיר בחו\"ב ש\"מ ממש העצמיי' שהן שרשי' לתושב\"כ ושבע\"פ (וכענין נובלות חש\"מ תו' (ונובלות בינה ש\"מ שכינה כו') והוא מ\"ש אאלפך חכ' כו' ואח\"כ נמשך למטה באבי\"ע ונק' קנה חכ' קנה בינה ב\"פ קנה גי' ש\"י חצי הכתר דתר\"ך כו' והן מזל ונוצר ונקה כו' כמ\"ש במ\"א בענין ונוצר ועושה כו') וזהו ב' מדריגות הנ\"ל בנפלאותיך ומח' אלינו (וקאי לע\"ל ואהי' אמון בימוהמ\"ש שישכיל עבדי כו' ע\"י הבירורים דרפ\"ח כו' ואהי' הב' בעוה\"ב אנא זמין לאתגלאה למעלה מן הבירורים בעליות ושעשועי' העצמיי' ממש) וא\"כ הרי שרש התו' למעלה באין ערוך למקור העולמות (וכמו שעשועי' של הקב\"ה בעצמו ובכבודו כנ\"ל במשל המלך החכ' שאו' דבר חכ' יקרה ונפלאה מאד משתעשע בחכ' העצמי' ממש שבלתי יכול להתלבש בעלמין כלל אפי'"],[2300680451,"בעוה\"ב כנ\"ל) וזהו שנענש דוד על שקראם זמירות שהשפיל לבחי' העונג ושעשועי' העצמיי' שבתו' להיות לו לעונג ושעשועי' להשיב נפשו לפי שעה הצריך לו בבית מגורו שהי' יגור מאויביו כדי להמתיק הדינין בשרשן כנ\"ל שזהו רק בשרש התהוות העולמות שנמשך מחיצוני' העונג ושעשועי' דתוה\"ק שנתצמצם בעונג ורצון וחכ' בהשתלשלות שאין לזה ערך כלל וכלל לגבי בחי' שעשועי' העצמיי' שבתו' ש\"מ ומטה שלמעלה מעלה מכל עיקר ומקור ההשתלשלות מטעם הנ\"ל וד\"ל. אך דוד עשה בחכ' להציל נפשו מן הקטרוגים הקשי' שא\"א להמתיק רק בבחי' עונג העצמי' ממש כמו בזמירות דתו' ויש בזה ב' מדריגות א' הטעמי' ונגינות דתושב\"כ (שלמע' מדרשות והלכות דתושבע\"פ שהרי אין שום דרש נדרש מן הטעמים ונגינות כלל להיותו בבחי' מקיף דעונג בעיגול שזהו שירו כו' וד\"ל). והב' רננא דתושבע\"פ דוקא כמ\"ש חכמות בחוץ דוקא דהיינו כשמתברר מן החושך דק\"נ כנ\"ל אז תרונה שהרינה באה מלמטה למעלה בבחי' או\"ח דוקא וכמ\"ש ובלילה שיר\"ה עמי בה\"א בחי' נוק' וכל העוסק בתו' בלילה דוקא עי\"ז דוקא חוט של חסד נמשך עליו ביום כו' וזהו נק' ג\"כ זמירות כמו מכנף הארץ זמירות שמענו צבי לצדיק כו' מכנף הארץ דוקא שזהו תושבע\"פ שנברר מן הארץ כהלכות המחודשים בפלפול שעולה ברינה כמו בא יבא ברינה כו' בהגדלה וריבוי מופלג כנ\"ל וז\"ש זמירות היו לי חוקיך כו' דקאי בתושבע\"פ דוקא שהי' מתענג ביותר במה שמחדש דין והלכה ברורה מאין המוחלט והי' שמח בחלקו אשר הוא ממשיך בתו\"א מבחינת אמון מופלא ושעשועי המלך בעצמו ממש (שלמע' גם מעוה\"ב כנ\"ל) שכאשר אור גדול ויקר כזה נמשך לקיום העולמות עי\"ז נמתק כל דין ורוגז אשר בקו השמאל אף במקור הרצון וחכ' כו' עד גם בחיצוני' הכלי' דמל' דעשי' עד עוה\"ז השפל שממילא יתפרדו כל פועלי און וכהמס דונג כו' (וכמו ברבה ב\"נ דלא פסיק פומי' כו' לא יכול מה\"מ לגשת אליו) לפי שמתבטלי' ממציאות' לגמרי בהגיע גם אליהם האור הגדול שלמעלה מכל ההשתלשלות וכמ\"ש תפול עליהם אימתה ופחד כו' (וכמו ואתה מרום לעולם במרום דשעשועי' העצמיי' דתוה\"ק למעלה מעלה אז אויביך יאבדו כו') וכמו בחזקי' שהפיל ה' למחנה סנחריב רק במה שהשמיע ה' להם את הוד קולו דתוה\"ק הנ\"ל וד\"ל:\n(טז) <b>וזהו</b> העצה היעוצה שיעצו חז\"ל בא' השכם והערב עליהם לבהמ\"ד והן כלין מאליהן ולכאו' א\"ז מובן מ\"ש השכם והערב כו' הלא מצו' ת\"ת היא בתמידות יום ולילה כמ\"ש והגית בה כו' וכן א' ודברת בם כו' בשכבך ובקומך כו' ומהו שא' השכם דמשמע קודם אור היום והערב לערב בתוך הלילה כו' וגם מ\"ש עליהן דוקא דמשמע על המקטרגי' הקמי' עלי' שישכים ויעריב עליהן והן כלין כו' (והנה יש נוסחא השכם והערב עליהן לבהכ\"נ להתפלל כו' ולא מדבר בת\"ת כלל כי קאי אדסמיך לי' מ\"ש תחלה בפי' הב' דום לה' והתחולל לו דום לה' והוא יפיל לפניו חללי' חללי' ואח\"כ א' עוד השכם והערב עליהן כו' שהוא להרבות"],[2300680453,"בתפלה בוקר וערב פי' והתחולל לשון תפלה כמו ויחל משה אוחילה פניו והיינו מ\"ש השכם דהיינו משום דמצוה להתפלל עם יציאת השמש דהיינו עם דמדומי חמה שזהו פי' דו\"ם כפי' התוס' וכן הערב עליהם בעת ביאת השמש לערב שנק' דמדומי חמה וזה הפי' דחוק בלשון דום שהוא לשון שתיקה כמו שמש בגבעון דום וכן וידום אהרן (וע' במהרש\"א שא' דהשתא ניחא שיהא דום כמשמעו כמו וידום ואיך הוא ענין שתיקה אם מיירי בתפלה לפי' הב' בוהתחולל ולפי הנראה שאינו רוצה לפרש כפי' התוס' בדום כמו ענין דמדומי חמה אלא פי' כפי' והתחולל דתחלה דרש ענין חללים ואח\"כ דרש ענין תפלה כמו ויחל כו' ובתוס' שם א' השכם עליהם לבהמ\"ד קא' לעסוק בתו'). אך הנה יובן כ\"ז בהקדם ענין א' המבואר במ\"א ע\"פ הקל קול יעקב דקל קדמאה חסר וי\"ו וקול בתראה מלא בוי\"ו כמ\"ש בזוהר שזהו בחי' קלא פנימאה דלא משתמע כלל בדיבור חסר וי\"ו וקלא דמשתמע בדיבור מלא וי\"ו והיינו ב' מדריגות דקול תפלה וקול תו' דקלא דצלותא הוא בלחש ובחשאי דוקא זהו קל חסר וי\"ו וקלא דאורייתא שבא בדיבור דוקא הוא קול יעקב כו' ועל שניהם א' הקל כו' והידים ידי עשו שמתמיה בזה אם הקל קול יעקב האיך יוכל להיות הידים ידי עשו שבודאי אין לעשו שליטה כלל על יעקב כשקול יעקב בתפלה ובתו' ואפי' בא' מהן בלבד כו'. והענין הוא דבקול תפלה הוא ב' מדריגות א' בענין צעקה בקול דוקא כמו ויצעקו אל ה' כו' וכן ויזעקו בקול גדול וכמו בעת צרה דכתיב ותעל שועתם אל האלקי' ונק' שועה או שאגה כמו שאגתי מנהמת לבי כו'. והב' הוא קול דממה דקה שהוא בלחש ובחשאי מאד כמו בתפלת חנה דכתי' מדברת על לבה וקולה לא ישמע כלל וע\"כ א' כל המשמיע קולו בתפלתו ה\"ז מקטני אמנה כידוע. ושרש הענין הוא כידוע שעיקר התפלה הוא בבחי' שפיכות נפש שתשתפך לגמרי ותתבטל ממציאותה מכל וכל כמו ההשתחוואה בארץ בביטול המציאות לגמרי כאבן דומם עד שאין בו כח לדבר ולא להתפעל ברצון ולחשוב שום מחשבה והשגה כלל וכלל אלא כדומם ממש בלא הרגשת חיות כלל וכלל כידוע (ושפיכת נפשו זהו שנתבטל מציאו' נפש אדם כמו השכל והרצון ומדו' ומח' ודיבור לגמרי מכל וכל ובהעדר הכלי לגמרי הוא שעולה לקבל ג\"כ למע' מבחי' אדם והוא מעצמו' א\"ס דלמכא\"מ כלל אף לא מדות וחכ' ורצון דתו\"מ כידוע שזהו למע' מיחוד משפיע ומקבל פב\"פ בבחי' אדם פנימי וחיצוני דתו\"מ כמו במ\"ת וראי' ממשה שידעו ה' פב\"פ כאשר ידבר כו' ובתפלה שלו הי' מתנפל לארץ בהשתחוואה בביטול המציאות דאדם לגמרי דוקא וד\"ל) ואמנם שפיכה זאת דנפש האדם יכול להיות גם בצעקה מקירות הלב בקול גדול שנק' שועה עד שתצא נפשו מעומק הבכי' והצעקה כו' למעלה מן הרצון ושכל בלא דיבור כלל רק בחי' קול פשוט דוקא כמו מן המיצר כו' וזהו הקל קול יעקב קול בתראה בוי\"ו שהוא בחי' המדות וחכ' שבתו' ביחוד פב\"פ בבחי' אדם וקל קדמאה בלא וי\"ו שהוא ב' מיני קול דתפלה הנ\"ל שלמעלה מבחי' נר\"נ דאדם שנק' שפיכת נפש אדם ובחינת קול דצעקה ג\"כ בלא וי\"ו דהיינו"],[2300680455,"למעלה מן המדות ושכל ורצון שנק' קול פשוט ועצמי וזהו קל חסר וי\"ו וכש\"כ קול בלחש ובחשאי מאד מצד העדר הכלי כדומם ממש עד שא\"י לדבר כלל מכח עצמו כמו וקולה לא ישמע ונק' קלא פנימאה דלא משתמע בדיבור רק אד' שפתי תפתח כו' כי אין מלה בלשוני כו' וזהו קל חסר וי\"ו ממש אבל קלא בתראה מלא בוי\"ו שהוא בחי' קול הדיבור שבתו' שמקשר השכל ומדות ורצון בחכ' ומדות ורצה\"ע הפנימי ביחוד פב\"פ שבזה נמשך אור ושפע הפנימי' דעונג ורצה\"ע שבתו\"מ ש\"מ שקדמה לעולם שא' ואהי' אצלו שעשועי' יום יום כנ\"ל שהוא למעלה ממקור חיות כל העולמות כנ\"ל שעי\"ז ממילא אין לק\"נ יניקה ושרש רק מחיצוני' דחיצוני' הכלי' שניתן להם בקצבה וגבול לבד וא\"כ לא יוכלו לקבל שפע יותר ממדתם וזה מתמיה אם הקל קול יעקב בא' מהקולות אם בקול דתפלה בב' אופנים הנ\"ל שאין לחיצוני' יניקה שם כלל מאחר שהוא למע' מהגבלת האורות בכלי' בנר\"נ דאדם לגמרי כנ\"ל או גם בקול דתו' ביחו\"ע דפנימי' הרצון וחכ' ומדות דתו\"מ שאז הכל מאיר מבחי' הפנימי' ועצמי' דא\"ס בחכ' ומדות כמו יאר הוי' פניו אליך כו' (כמו שהי' במ\"ת) שאז אין לחיצוני' שליטה כלל רק כפי מדתם לבד א\"כ איך הידים כו' וד\"ל. אך הנה יש מדריגה במצות ת\"ת ג\"כ כמו בחי' קול דתפלה בלחש כמו ענין שפיכות הנפש הנ\"ל ממש והוא במצו' העיון והגיון דתושבע\"פ דוקא והוא היגיעה העצומה בכל כלי מוחו לעמוד על אמיתית הדין וההלכה עד שיתבלבל הכלי שלו כי עמוק ממנו ונעשה כמו בחי' דומם ממש כמו אשתומם כשעה חדא והוא בחי' השתיקה שהוא סייג לחכ' שעולה בכח המשכיל ההיולי להמשיך המשכות שכל עמוק יותר מכפי הכלי שלו והוא חידוש ההלכות לאין שיעור ע\"י הפלפול בקושי' ותירוצי' כנ\"ל שזהו ככח הצומח שבארץ כו' כנ\"ל הרי זהו שנתבטל מבחי' מוחין דאדם למעלה מבחי' אדם כשפיכות נפש בתפלה הנ\"ל ממש וזהו שמחמת עומקו שמתבטל מכל עצמו ואינו מרגיש א\"ע כלל אז הוא מרחש בשפתיו בלחש כתפלה בלחש שאין זה דיבור של עצמו' בבחי' רצון ושכל כלל רק שעולה ונגרר אחר עומק השכל שזהו כמו אד' שפתי כו' שזהו עולה למעלה מבחינת פנימי' המוחין ורצון ומדות דחכ' דתו' שבקריאה בדיבור שנק' אדם עכ\"פ כנ\"ל וד\"ל. ובכ\"ז יובן המא' הנ\"ל בעצה שיעצו השכם והערב עליהן כו' שיש בזה ב' אופנים א' להתפלל בבהכ\"נ בב' מיני קול הנ\"ל דנקודת הלב הפשוט שלמעלה מבחי' אדם וזהו דום לה' בקול דממה דקה שבצלותא בלחש כדומם ממש כנ\"ל וכן בקול צעקה מקירות הלב שנק' ג\"כ שפיכות נפש לגמרי והתחולל לו בחלל ריקן מכל וכל וע\"כ יפול לפניך חללי' שיתרוקן כל אור וחיות דקליפות המקטרגי' העומדי' על נפשו כמ\"ש יהיו כאין ויאבדו אנשי ריבך כאין ממש אין להם שרש יניקה שם כלל מטעם הנ\"ל וד\"ל והב' השכם והערב עליהן לבהמ\"ד ללמוד תו' בקריאה בדיבור כמ\"ש השמיעני כו' כי קולך ערב קלא דאורייתא שמשתעשע בפנימי' החכ' ומדות כנ\"ל וזהו עליהן למעלה ממדתן הקצובה רק מחיצוני' דחיצוני' הכלי' וזהו עליהן הגבה למעלה מהן כי פנימי' העונג ושעשועי' שבתו' למעלה הרבה משרש העולמות"],[2300680457,"כנ\"ל ואז הם כלים מאליהם כשיכלה קיצם ממילא כאשר נפרד הטוב מן הרע בתכלית שזהו בבחי' הפנימי' דתו' שנבדל ונברר הטוב מן הרע בחיצוני' דעה\"ד כו' אך יותר טוב הוא עסק תושבע\"פ שז\"ש ובלילה שיר\"ה עמי כל העוסק כו' שנק' לחם מן הארץ שמחדש הלכות בעיון ויגיעות המוח שזהו בלילה דוקא שעולה למעלה יותר מבחי' פנימי' אדם דתו' כנ\"ל וכמו שנברר הטוב מן הרע ע\"י כח הצומח שבארץ כך עיקר הבירור השלם הוא בכו\"פ טו\"ט שבתושבע\"פ שעולה מלמטה למעלה שאז הטמא טמא יקרא ואין לו חיות כלל וכלל מן הטוב יותר מע\"י תושב\"כ שיש לו יניקה מחיצוני' הכלי' עכ\"פ. וזהו יאבדו ויהיו כאין ממש אנשי ריבך כי אין להם חיות כלל וכלל מב' טעמי' הללו וד\"ל. וזהו השכם בבוקר קודם היום והערב בלילה בבחי' שפלות כעפר לידום ולסבול כעפר לכל שיצא ממנה לחם שזה בכלות כל השפעות מלמטה למעלה שאז ממילא חוט של חסד העצמות ממש נמשך עליהם ביום שיאבדו כל אויביו וכמ\"ש והן כלי' מאליהם וד\"ל. והנה מובן מכל הנ\"ל שע\"י בחי' השמחה והתענוג האלקי' בעסק התו' כאשר יהי' בתו' ה' חפצו בחפץ ובחשק נפלא בתמידות וישמח בד\"ת כמו שמחה ועונג העליון שבעצמו' א\"ס ב\"ה בתו' שלמעלה ותו' שלנו כמ\"ש ואהי' אצלו שעשועי' כו' כנ\"ל אז עי\"ז יסיר מעליו כל קטרוג רע למעלה ולמטה ולא יהי' שום מניעה מבית ומבחוץ בלי שום דבר חוצץ כלל כי יהי' כאין ממש אנשי ריבו כנ\"ל בענין השכם והערב עליהם כו' ויש בזה ב' מדריגות א' בענין שמחה ושעשועי' דעצמו' א\"ס ב\"ה בתו' שלמעלה מלמעלה למטה בבחי' או\"י שנק' שירו לשון דכר כמו בטעמי' ונגינות דתושב\"כ שנק' ספר והב' ברינה ש\"ת שבאה מלמטה למע' מתושבע\"פ בבחי' או\"ח למעלה משלימות הבירור דחדושים בחידושי הלכות לאין שיעור כנ\"ל (שנק' סופר) ובב' מדריגות הללו אין שום יניקה כלל לרע דק\"נ כי בבחי' עונג העצמי' שבח\"ע דתו' שלמעלה אע\"פ שירד למטה באותיות ובטעמי' כו' הרי זהו מבחי' עה\"ח שכולו טוב ולא רע כלל ועז\"א דאין רע יורד מלמעלה כלל ואע\"פ שמלובש בעה\"ד טו\"ר שהרי מבדיל בין טו\"ר כמ\"ש להבדיל כו' וע\"כ נק' תו' לשון הוראה כו' עכ\"ז בעצם אור דתושב\"כ (שנק' סה\"ח) הוא מבחינת עה\"ח שלמעלה מעה\"ד טו\"ר שאין שום צד אחיזה כלל לרע (כמו במשה שא' כי טוב בטי\"ת רבתי כו' וע\"כ א' יבא טוב זה משה וקבל טוב זו תו' מטוב כו' שנק' לקח טוב כו') (וע\"כ ת\"ח אין אור של גיהנם שולט בהם כו' ועוד ראי' ממה שד\"ת אין מקבלין טומאה וממה שבע\"ק מותר בד\"ת וממה שעבירה מכבה מצוה ואין מכבה אור דתו' כלל כמ\"ש במ\"א וד\"ל) והיינו מבחי' התענוג ושעשועי' העצמיי' שבתושמ\"ע שנק' שירו כו' שאין לו שיעור למעלה ולמטה כלל ולכך גם חושך גס דק\"נ לא יחשיך אור זה כלל ונהפך גם הוא לאור וראי' ממ\"ש ויורהו ה' עץ שהוא בחי' עה\"ח דתוש\"מ כמ\"ש כי עץ חיים היא כו' שבכחו להמתיק למים המרים דק\"נ שיהי' גם הם טובים ומתוקי' וז\"ש שם שם לו חוק ומשפט דתוש\"מ שיהי' בכחו לברר גם בעה\"ד טו\"ר כו' (כמ\"ש במ\"א) וכמו ותו' שם בישראל ונא' אם שמוע כו' כל המחלה כו' שהן"],[2300680459,"דינין קשי' שנאחזים במ\"ת שנפלו שנק' מיין מרירין כו' כי אין רע יורד מלמע' וגם למטה מבררו ונמתק לטוב וכ\"ז מצד בחי' או\"י דעונג העליון שהולך ואור באור דתוש\"מ עד למטה בתו' הנגלית שבאה באותיות בשפע והתלבשות בעה\"ד כו' (וכמו נשמת משה שירדה ממ\"ע לתקן ולברר לישראל בתו\"מ כו' לפי שהי' בעצמו מבחי' התיקון דשם מ\"ה דח\"ע הקדומה ע\"כ הי' בכחו ליתן תו' לישראל לתקן אותם) (וז\"ש ה' חפץ למען צדקו באו\"י מלמעלה למטה שנק' תו' חסד יגדיל תו' בהתלבשותן למטה בעה\"ד כו') וכמו\"כ במדריגה הב' דתושבע\"פ שנק' מזון ולחם מן הארץ דוקא כנ\"ל וכמו ותורתך בתוך מעי כו' שהוא העולה מבחי' הבירורי' דרפ\"ח כו' ביתרון האור מן החושך בחידוש מאין ממש כנ\"ל שיש בזה ג\"כ בחי' העלאת העונג ושעשועי' שנק' שיר\"ה בה\"א כו' כמ\"ש חכ' בחוץ דוקא תרונה מלמטה למע' שזהו שלימות הבירור והבדלה בין טו\"ר בתכלית הרי אין מקום ושרש כלל לרע גם למטה מטה מאחר שנבדל בתכלית הקצה מן הטוב בבירור הלכות בכשר ופסול טו\"ט וכה\"ג וגם אין לעונג זה שבבירור וחידוש ההלכות שעלו למעלה בשעשועי' העצמיי' יותר מגופו ש\"ת שלמעלה שקדמה במע\"ב הנ\"ל וז\"ש ואהי' אצלו אמון אומן בתושבע\"פ שתו\"א לתקן דבר המקולקל ביותר מבחי' התיקון משרש החכ' שבאה באו\"י (משום דבינה יתירה ניתנה באשה כו') וזהו יום יום תושב\"כ ותושבע\"פ בשרשן שעז\"א יחיינו מיומים והן ב' אלפי' שנה שקדמה לעולם כו' (ובאמת הן ב' אלפי' שנה שקדמה למ\"ת דמ\"ת הי' בתחלת אלף השלישי שז\"ש ביום השלישי יקימנו שהוא בבחי' הת\"ת כו' ומ\"ש ונחי' לפניו דמשמע חיי עולם זהו בעוה\"ב דוקא):\n(יז) <b>אך</b> הנה כ\"ז דוקא כאשר אין שיעור ומדה להארת אור התעה\"פ ושעשועי' העצמיי' במקור התושב\"כ ושבע\"פ למעלה ע\"י אתעדל\"ת בלימוד התורה בשמחה ותענוג אלקי בלי גבול כלל כנ\"ל. אבל אם אין עסק התו' למטה בבחי' שמחה ותענוג האלקי בשעשועי' גדולי' רק כפי המדה שמוגבל בנפש להתענג בעונג העליון בחכ' דתו' שנק' שיר\"ו ושיר\"ה שזהו בתושב\"כ ושבע\"פ כנ\"ל אז נאמר ויהי מקץ שנתיים ימים שנעשה בחי' קץ וגבול ומדה בעונג ושעשועי' העליונים שבתו' שלמעלה ג\"כ עד שכל האור ועונג העצמי' שהי' לו בתו' נסתלקו למעלה בעצמותו ממש והיינו דוקא בכלות הזמן דשנתיים ימים שבחי' שנתיים ימים הללו הן ב' אלפי' שנה שהי' בהן אור השעשועי' העליונים בחו\"ב וכאשר הי' קץ וגבול לשנתיים ימים הללו הי' קץ וגבול לאור התענוג ושעשועי' בתו' ש\"מ ותושמ\"ט כו' וד\"ל (והיינו לפי שבחי' שעשועי המלך בעצמו ממש נבדל בערך לגמרי גם מעונג ושעשועי' בח\"ע עצמה דתו' ש\"מ רק שהושפל וירד מעצמות השעשועי' להשתעשע בעונג זה דח\"ע שזה בא במדה וגבול כחכ' דתושב\"כ שבא במספר אותיות (גם בטעמי' שהן הנגינות שנק' שירו כו' שהן בבחי' מקיף מ\"מ בחי' מקיף זה הוא רק ע\"ג האותיות הבאים במספר וצמצום והמשכה"],[2300680461,"מוגבלת כו') וכמו\"כ בעונג העליון שמחמת הבירורי' דתורה שבע\"פ אע\"פ שמצמיח מלמטה למעלה לאין שיעור מ\"מ נק' סופרים שסופרים כל האותיות כו' ואין לזה ערך לגבי שעשועי' העצמיי' ממש שלמע' גם מחכ\"ע העצמיי' והוא העוה\"ב שנק' עדן הנעלם כו' בבחי' ההעלם דעצמי' התעה\"פ ממש שלמעלה מעונג דחכ' לגמרי כו' ולכך בכלות הזמן דשנתיים ימים שהן ב' אלפי' שנה דבחי' ימי קדם שהן בחי' התענוג שברצון ותענוג המורכב בחכ' עכ\"פ שיש בהן מדה וגבול גם לעונג העצמי' שבהן אע\"פ שאין שיעור כלל לתעה\"פ מ\"מ בחו\"ב מוגבל במדה (מאחר שנק' ספר וסיפור כנ\"ל) וכעונג הנשמות בהשגות ורזין דאורייתא שמוגבל בכאו\"א וכן גם לעוה\"ב שמאיר מעצמו' התענוג מוגבל ונמשך בכל נשמה כמו ש\"י עולמות (שהן ב\"פ קנ\"ה שהוא קנ\"ה חכ' קנ\"ה בינה ב' תו' שבכתב ושבע\"פ כו' וגם במשיח שאמר בו ישכיל עבדי כו' וגבה מאד יש בזה מדה כו') אך באמת הגם שבא העונג העצמי' בחו\"ג העליונים במדה מ\"מ מדה זו היא בחי' כלי להכיל לכל בחי' פנימי' ועצמי' השעשועי' שאין לו שיעור למעלה לפי שהלביש הכל במדה זו דוקא כי כל יכול הוא כו' וכנ\"ל (וכמו פנימי' התו' שארוכה מארץ מדה כו' הרי צמצם אורה במדה ושיעור דנגלה דתו' כמו במ\"ת ביוה\"ד דסתים נתצמצם בגלי' כמו כד הנשאב מן המוברר שבמי' עליונים כו' וכך כ\"ד ספרים כו' כנ\"ל) (וכמו בעוה\"ב שא' להנחיל אוהבי יש האמיתי כו' הגם שיבא במורגש בכאו\"א לפי קבלתו ועכ\"ז נק' חיי עולם הא\"ס ונק' יום שכולו ארוך כו') ולפי\"ז לא הי' בחי' קץ וגבול כלל לבחי' שנתיים ימים הללו שהן ב' מדריגות דחו\"ג דתושב\"כ ושבע\"פ בשרשן למעלה כי הי' אור העונג העצמי שבלתי מוגבל בעצם מאיר בהן בלי קץ וגבול כלל (כמו שיהי' בעוה\"ב) אך הסיבה לזה שהי' קץ וגבול לבחי' שנתיים הללו שקדמו לעולם כו' הוא לפי שלא זכר שר המשקי' דתושמ\"ע את יוסף צ\"ע וישכחהו כו' דקאי אדסמיך לי' במה שסיים בסמוך לזה (כמ\"ש למעל') דבחי' יוסף צ\"ע הוא מבחי' השעשועי' העצמיי' דא\"ס ב\"ה שהוא עצמו משתעשע בתו' כו' שיוסיף תענוג העליון לאין שיעור למעל' ולמטה וע\"כ נק' יוסף לשון תוס' וריבוי בלי גבול כלל וכן נק' בן פור\"ת יוסף שמפרה ומרבה אור העונג בחכ' לאין שיעור מאין המוחלט (והן ב' מדריגות העונג דח\"ע וח\"ת מבחי' או\"י ואו\"ח דתושב\"כ ושבע\"פ וע\"כ א' ב\"פ בן פור\"ת כו' והיינו יוסיף דעת כמ\"ש ה' חפץ למען צדקו דוקא שזהו בחי' צ\"ע שהוא טבע הטוב להיטיב בלי שיעור כלל וכלל ע\"כ מגדיל תו' דתושמ\"ע בבחי' או\"י מלמעל' למטה ויאדיר בתו' שלמט' כנ\"ל וזה שה' חפץ למען צדקו ע\"כ נעשה גידול וריבוי אור בב' תורות הנ\"ל שזהו הכל מבחי' יוסף צ\"ע וד\"ל (ופי' יגדיל שתמיד מגדיל בלי שיעור וכן ויאדיר וקאי לעוה\"ב שיגדיל אור דתו' מעדן הפשוט ויאדיר למעלה מעלה יותר כנ\"ל בת\"ח שאין להם מנוחה אפי' בעוה\"ב כו' או יגדיל במשיח כמ\"ש בו וגבה מאד ויאדיר בעוה\"ב) וכמ\"ש צדיק כתמר יפרח"],[2300680463,"כארז בלבנון ישגה כתמר יפרח במשיח שהוא בחי' מלך הח' בחי' יוסף ג\"כ והן גילוי סודות התו' וז\"ש מכנף הארץ כו' צבי לצ\"ע רזי לי רזי לי וכארז בלבנון ישגה בעוה\"ב כו'). אך הנה בחי' שר המשקים דתו' לא זכר את יוסף בחי' צ\"ע הנ\"ל והענין הוא דבחי' שר המשקי' דתו' הוא בחי' מקור הממשיך לחכ\"ע מעצמות א\"ס ב\"ה שנק' קנ\"ה כמו קנה חכ' קנה בינה וכמו הקנה שהוא המחבר המוח ללב ממנו נמשך מקור השכל שבמוח שהוא בחי' לחלוחי' דיסוד המי' שבמוח החכ' שהוא קר ולח ששם הוא בחי' העונג רוחני שמצמיח לכח השכל כו' וכן במוח בינה שזהו קנה חו\"ב כו' והוא חיצוני' התו' שנק' מים ופנימי' התו' שנק' יין גי' סו\"ד להביא ולהמשיך כל סוד ה' שבתורה לגילוי וכמו ויין מלכות רב כו' וכאשר בחי' החכ' דתוה\"ק נק' מ\"ע או ים הקדמוני זהו מה שנתפשט מאור דחכ\"ע העצמי' שנכלל בעצמי' ממש כידוע (והיינו ענין יום יום בשעשועי' העליונים בתורה שקדמה לעולם כו' שהן ב' ימים הראשונים בששת י\"ב יום א' יהי אור אור קדמאה דאור תושמ\"ע שא' בו כי טוב וטוב לגנוז בכלים דוקא שהן אותיות דתו' דוקא ובטעמים כו' וגנזו לצדיקים לעוה\"ב שנק' יום שכולו טוב להיותו בבחי' עה\"ח כו' וביום הב' יהי רקיע זהו בחי' התפשטות דחכ\"ע בבינה שנק' מים ורקיע המבדיל בין מ\"ע למ\"ת שזהו ענין ירידה וצמצום השפע מחכ\"ע לחכ\"ת שנק' מ\"ת והוא חכ' דתו' שמתלבש בעה\"ד טו\"ר כו' וביום הג' א' יקוו המים ותראה היבשה כו' ותדשא הארץ שזהו ח\"ת שבארץ לחדש השפע מאין ליש מלמטה למעלה בלי שיעור כלל והוא כמו בירור ההלכות דתושבע\"פ שבא מכח הצומח שבארץ שנק' לחם מן הארץ כו' והמים מצמיחים שיש בזה בחי' התכללות מאש ומים ורוח דתו' שנמשך מלמעלה למטה וזהו יחיינו מיומים ביום הג' כו') ומבואר למעלה בבחי' פרעה העליון דקדושה שזהו בחי' הפנימי' שבמל' דקדושה שמתגלה בחי' הפנימי' בחיצוני' דוקא וענין שרי פרעה הן בחי' קנה וושט קנה הוא בחי' החסדים דתושמ\"ע שיורד מגבוה לנמוך בנסתר ונגלה שהן מים ויין שז\"ש ובגפן ג' שריגים שהן כח\"ב או חג\"ת דכתר כו' (אמנם שר האופים הוא בבחי' הוושט שאוכל המאכל דלחם מן הארץ שהוא ח\"ת דתושבע\"פ שמלובש בעה\"ד טו\"ר שם יש יניקה ושרש לרע דק\"נ גם בתוש\"מ כענין התו' חוגרת שק דק\"נ כמו מי שלומד של\"ש כלל שא' ולמשמאילים בה סמא דמותא ממש כמזון שיש בו טו\"ר ובחי' הרע כאשר לא נברר מן הטוב יזיק לו גם בחי' הטוב עבור הרע המעורב בו כך א' ותורתך בתוך מעי ולרשע שמתגבר בו חלק הרע שבו נהפך לו לסם המות להמית נפשו ולהוריד לשאול לעומק רע דק\"נ יותר לפי שמוסיף כח בקליפות (ע\"כ גם בתושב\"כ א' ולרשע מה לך לספר חוקי כו' אבל אינו מזיק להיות לו לסם המות כי אין ד\"ת מקבלי' טומאה להיותו מבחי' עה\"ח שמהפך הרע לטוב כענין לעולם יעסוק אדם בתו\"מ של\"ש שמתוך של\"ש כו' כי בחי' המאור שבה שמאיר מעה\"ח שלמעלה מעה\"ד יחזירנו למוטב כו' כמ\"ש במ\"א) וזהו שפתר לשר"],[2300680465,"האופים לרעה להיותו בבחי' גבו' קשות דאש התאווה שבאש התאווה שבוושט גם בעסק התו' של\"ש ממש כמו גם שאין כוונתו רק להתגדל ולקנות שם או קרדום כו' משא\"כ בחי' שר המשקי' דיין ומים דתו' שא\"צ בירור כלל אינו מזיק כלל כי אין בו שליטה למות ורע גמור דק\"נ כו') וזהו לא זכר שר המשקים דתו' לבחי' יוסף צ\"ע שהוא להוסיף תענוג ושעשועי' העצמיי' שבעצמו' א\"ס ב\"ה שזהו הנק' עוסק בתו' לשמה לשם התו' עצמה להוסיף בה אור העצמי' דא\"ס כו' אלא בחי' העונג ושעשועי' שיש בנפשו בתו' שלומד הוא רק לעדן ולהתענג בעצמו להחיות נפשו ולפקחה מצד עצם החכ' דתו' לבד כמו שארי חכמות שיש בהם עונג לנפש עד שמחי' נפשו בעונג נפלא שבעומק חכ' וכאו' אין לי אלא תו' לבד כו' אז אפי' תו' אין לו שעי\"ז מסתלק אור דתו' עצמה ממנו כי יכלה אור העונג העליון שבח\"ע דתו' מאחר שאינו לומד בכוונה לעשות נח\"ר ליוצרו שמשתעשע בתו' זו שלומד רק להחיות נפשו לבד (אע\"פ שכוונתו להחיות נשמתו כמו כי אמרתך חייתני וכמו ר\"ש שא' חדאי נפשאי כו' לך קראי אדעתי' דנפשי' לתקן נשמתו לבד דמ\"מ נפסק אור השעשועים העצמיי' שבתו' למעלה ולמטה ואז ממילא יש קץ וגבול לחו\"ב דתו' כנ\"ל) וזהו מפני שלא זכר שר המשקים דתו' למעל' ולמטה בחי' יוסף צ\"ע להוסיף אור התענוג העצמיי' לבד ולא לעצמו ע\"כ הי' קץ וגבול לבחי' שנתיים ימים דחו\"ב דתוש\"מ שקדמה לעולם לפי שנסתלק מהם אור העצמי' השעשועים העליונים כו' וד\"ל:\n(יח) <b>וזהו</b> ויהי מקץ שנתים ימים ופרעה חולם כו'. דהנה כאשר בתו' ה' חפצו של אדם בשמחה ותענוג האלקי רק לעשות נח\"ר ליוצרו לבד שישתעשע באור תורתו ויוסיף בה אור כו' שאז נמשך בחי' פנימי' העונג העליון בחו\"ב בתושב\"כ ושבע\"פ שנק' ספר וסיפור בתוס' וריבוי לאין שיעור וגבול כלל שאז ממילא אין מקום ושרש להיות יניקה לרע כלל כי אין שרש להם רק בחיצוני' דחיצוני' לבד אבל כאשר מתגלה כל בחי' הפנימי' דעונג וח\"ע למטה גם בחיצוני' הכלי אז אין לרע יניקה כלל מבחי' הטוב משום צד ופינה כנ\"ל (כמו במ\"ת שהי' פב\"פ בחי' פנימי' העונג דעצמות בחכ' שהאיר פניו לבניו שיקבלו גם הם בבחי' הפנימי' שלהם כו' שאז נפסק מהם זוהמ' של נחה\"ק כידוע והי' חירות ממות כו') וזהו ענין בחי' פרעה דקדושה דאתפריעו ואתגלו בה כל בחי' נהורין עילאין דוקא דהיינו שנתגלה כל בחי' הפנימי' דוקא בלי מסתיר כלל כנ\"ל באורך אבל כשאינו עוסק בתו' בבחי' המשכת שעשועים העליונים לעשות נח\"ר ותענוג למעלה בלבד כו' אלא להנאת עצמו בלבד כו' או שלומד בקרירות ועצלות שאינו שמח בד\"ת כלל רק לצאת י\"ח בשיעור שקצב לו מידי יום לקבוע עתים ללמוד תו' שלומד מן השפה לחוץ ואז א' ויהי מקץ שנתיים ימים שנעשה בחי' קץ וגבול בשנתיים ימים דתו' שקדמה לעולם שזהו מצד הפסקות האור דעונג העליון שבחו\"ב דתו' שהן ב' ימים כמ\"ש ואהי' אצלו שעשועי' יום יום והוא מ\"ש יחיינו מיומיים"],[2300680467,"ואין בהם גידול וריבוי כלל אלא הן בבחי' קץ ותכלית מטעם הנ\"ל ואז א' ופרעה חולם שגם בבחי' מל' שהוא ענין התפלה שמתפללי' בנ\"י הגם שאז הוא שעת הכושר ועת רצון למע' להיות בחי' גילוי אלקות בנש\"י באוי\"ר פנימי' שבלב בכלל ובפרט אבל אין גילוי אור הפנימי בחיצוני' כלל בעצם דאור המל' הגם שנק' פרעה ע\"ש בחי' התגלות ופריעה דכל נהורין כו' דהיינו שאין התפעלות אלקות בנש\"י באוי\"ר פנימי' שבלב ומוח כלל רק בבחי' החיצוני' דחיצוני' לבד והוא בבחי' חלום שהוא בבחי' הדמיון במח' בבחי' הקטנות והוא רק חיצוני' ההשגה הנגלה במוח שנק' הודאה מרחוק לבד כמו מרחוק הוי' נראה לי כו' ואין אור אלקי נכנס בתוך תוכו כלל וכלל והאות לזה הוא מה שאין לו טעם ועונג ושעשועי' כלל בהתפעלות האהבה אלקי' שבאה מכח ההשגה כי גם בהשגה זו עצמה הוא רק במח' בעלמא בלא עונג ושמחה כלל (שנק' טויט און קאלט בלא חיות קיין לעבעדיקייט כו') כמו החולם חלום שהוא במעבר בעלמא ומיד חולפת ומתבטלת ההשגה וההתפעלות לגמרי והי' כלא הי' ממש (והיינו כמו מי שעוסק בתו' בלא שמחה ועונג כלל רק מדבר ד\"ת מן השפה ולחוץ לצאת י\"ח בלבד כך בתפלה ג\"כ הוא מדבר מן השפה ולחוץ וכתי' יען ניגש העם הזה אלי בפיו ושפתיו כבדוני ולבם רחוק ממני כו' אז ואבדה חכמת חכמים ובינת נבוני' תסתר שזהו בחי' קץ וכיליון במקור החו\"ב דתו' ש\"מ שנק' חכמת חכמים מקור החכ' כו' לפי שכלה כח העונג העליון שבחו\"ב שמשם מקור מוצא החו\"ב מאין ליש כידוע וד\"ל) וזהו ויהי מקץ כו' ופרעה חלם כו' דאע\"פ שיש גילוי אור ה' בנש\"י בק\"ש ותפלה שזהו בחי' פרעה דקדושה כנ\"ל אבל אינו בא ומאיר בבחי' פנימי' העונג ושעשועים כמו בשיר וזמרה (כעונג ושעשועי' שבתו' הנ\"ל) שאין בו בחי' טעם בלא אור וחיות כלל וזהו כמו הנקודה דחולם שהוא ע\"ג אתוון מלמעלה בלבד בבחי' נקודה בעלמא מרחוק בהעלם כו' וכך הנה\"א שהיא מלאה אותיו' בעצמה וגם ברצון ושכל ומדות כמו אותיות השכל שבא בבחי' חיצוני' לבד וכן אוי\"ר בחיצוני' וגם הרצון הוא רק בחי' חיצוני' שברצון שהוא רק בחי' האותיות שבה לבד וכך גם בבחי' אותיות שבנפש עצמה אינו רק בחי' חיצוני' שלה ומתגלה ע\"י באור וחיות החיצוני' לבד שמסתיר על בחי' הפנימי' שבה כנ\"ל וגם על בחי' חיצוני' דבחי' אותיו' שבה אין אור ה' מאיר בה בתוך תוכן ממש רק ברישי אתוון נקודה דחולם שע\"ג האותיות כנ\"ל כך אור ה' שמאיר בנשמ' האלקי' הוא רק בהתנוצצות אור המבהיק רק בבחי' נקודה בעלמא בראשם (כמו בהילו נרו עלי ראשי בבחי' מקיף בהעלם מלמעלה בלבד משא\"כ כשאור הוי' מאיר בנשמה בתוך תוכה ופנימיותה גם בחו\"ב ומדות ורצון כו' שז\"ש כי אתה תאיר נרי או כי אתה נרי הוי' ונק' נר הוי' ממש שמאיר אור הוי' בגילוי גמור בפנימי' שבה דוקא כמו לך א' לבי בקשו פני את פניך ה' אבקש בבחי' פב\"פ כמו שהי' במ\"ת שהאיר ה' פניו אליהם עד שעל כ\"ד פרחה כו' וכך יש עכשיו בכל מי שאו' דבר ה' זו מקרא ומשנה בגילוי אור"],[2300680469,"הוי' בפנימי' כנ\"ל) וז\"ש רואים שיוכל כל איש ואיש להתפעל בהשג' אלקי' אבל א\"ז רק מרחוק לבד שמתנוצץ בשכלו והשגתו הארה והמשכה האלקי' אבל אינו מאיר ומלובש בתוך תוכו כלל רק בבחי' מקיף בהעלם עליו כו' וכמו עכשיו בזה\"ג שא' כנ\"י אני ישינה בבחי' שינה שהוא רק כמו בחי' הדמיון שבמח' גם בהשגת אלקות בהתפעלות אהוי\"ר (כנ\"ל באריכות) שזהו בבחי' או\"ח שהתחתון מלביש ומכסה לעליון היפוך בחי' או\"י שבחי' פנימי' דעליון מאיר גם בחיצוני' הכלי בלי מסתיר כלל כמו שהי' במ\"ת וכמו בעוה\"ב כו' ולזאת צ\"ל בחי' הגניזה דאור בכלי דוקא שהוא בחי' התיקון כנ\"ל אבל בבחי' שינה בחלום זהו בחי' התוהו שלמעלה מהגבלת האורות בכלי' כידוע וע\"כ יכול להיות ב' הפכי' כא' כנ\"ל וזהו ויהי מקץ שנתיים ימי' לפי שלא הי' האורות גנוזי' בכלי' דבחי' התיקון לפי שלא זכר שר המשקי' את יוסף מקור בחי' התיקון שנק' בן פור\"ת להרבות האורות בכלי' וד\"ל:\n(יט) <b>וזהו</b> והנה עומד על היאור כו'. דהנה היאור הזה הוא נהר נילוס שהוא הנהר הראשון בד' נהרות שיוצאין מנהר שיוצא מעדן להשקות הגן והוא מ\"ש ומשם יפרד והי' לארבעה ראשים שם הא' פישון כו' שנהר זה עדיין הי' כלול ומתאחד בנהר שיוצא מעדן ממש שהוא למעלה מעה\"ח שבתוך הגן כמ\"ש ויטע ה' גן בעדן מקדם כו' ויצמח ה' כל עץ נחמד כו' וטוב להשכיל ועה\"ח בתוך הגן ועה\"ד טו\"ר ונהר יוצא מעדן להשקות את הגן הרי פשט הכתובי' הללו משמע דנהר זה שיוצא מעדן הי' משקה לכל עץ נחמד כו' הנטוע בגן הזה וגם לעה\"ח שבתוך הגן וגם לעה\"ד טו\"ר כו' וע\"כ בנהר זה בהכרח שיש בו כח המצמיח כל בחי' עונג העליון הטוב בעצם כמו כל עץ נחמד וטוב וגם הי' משקה לעה\"ח ועה\"ד כו' רק שבהפרד הנהר חוץ לג\"ע לד' ראשים ויצא ראשון נהר פישון שהוא נילוס נמשך בו מבחי' עה\"ד טו\"ר בתערובות אחר החטא דאדה\"ר בעה\"ד כשאכל ממנו כו' (ובחי' ס\"ר ניצוצות דקדושה שיצאו ממצרים היו משוקעים בנהר נילוס כו' שהן ז' מדות דקדושה דע' נפש דיעקב איש תם כו'. וזהו ענין ז' פרות הטובות שעולות מן היאור הזה ואחריהן ז' פרות רעות שהן ז' מדות דע\"ס דק\"נ דכתי' בהנחל עליון כו' בהפרידו בנ\"א כו' יצב כו' ותאכלנה ז' פרות רעות כו' שהוא מה שנבלע ישראל בגלות בע\"ש כו' כמ\"ש למעלה). והנה מבואר למעלה שבחי' העדן הרי הוא בחי' שעשועי' העצמיי' שבח\"ע דתו' הקדומה והוא שנמשך בנהר שיוצא מעדן להשקות את הגן שהוא ג\"ן סדרי' דאורייתא כו' והוא משקה גם לבחי' עה\"ח שכולו טוב בעצם עד בחי' המדות שמתגלים למטה בעה\"ד טו\"ר ואמנם בעה\"ד עצמו הרי הן יוצאין מפורדי' זה מזה שאין הרע מעורב עם הטוב כלל ואין הטוב מתערב ברע כלל רק ע\"י חטא אדה\"ר נתערבו טו\"ר יחד (כמ\"ש למעלה באריכות) וזהו שהי' בחי' החלום הזה דפרעה העליון דקדושה שהוא בחי' המל' שנק' סודכ\"ד בחי' ההתגלות של המוחין ומדות ורצון ותענוג כו' שהוא עומד על היאור למעלה מבחי' הנהר שיצא מעדן עצמו שהוא בבחי' אור העונג ורצה\"ע"],[2300680471,"העצמי שבחו\"ב שממנו נמשך גם לעה\"ח שהוא מדות דבינה עילאה שהוא בחי' צומח שבבחי' חיים עליוני' דחו\"ב ע\"כ נק' עה\"ח כו' שנמצא בחי' סוף דמל' עומדת למעלה על בחי' ראש דג\"ר דכח\"ב כו' והיינו לפי שזהו בחי' החלום כח הדמיון דבחי' מקיף דתוהו שיכול להיות התחתון עליון והעליון תחתון וב' הפכים כא' וד\"ל. וזהו שראה בחלום והנה מן היאור עולות ז' פרות יפו\"מ ובריאות בשר דהיינו מה שגם מבחי' אור העליון דנהר ראשון שיוצא מעדן להשקות את הגן יוצאי' ונמשכי' תולדות ז' מדות טובות הטבעי' העצמיי' כמו שהן בעצם הטוב שברצון ועונג העצמי בעצמו' הנפש ממש כמו בק\"ש ואהבת בכל לבבך ממש כו' גם במדות הטבעי' בלב בשר וז\"ש יפו\"מ ובריאות בשר בחומר כמו בצורה (כעצם הטוב דנשמת משה שמן המ\"ע דיאור הנ\"ל משיתיהו כנ\"ל). אך אחר התפלה יוצאי' ונמשכי' ועולי' מן היאור הזה עצמו להשקות את עה\"ד טו\"ר שהן ז' מדות הרעות אה' רעה טבעי' ועצמי' ג\"כ כי משם יפרד בעולם הפירוד ונעשה בחי' רע גמור בתאוות חומרי' המטמאי' לנפש עד שמשכחות את מדות הטובות שהי' בלבו באהוי\"ר האלקי' גם בטבעי' בעת התפלה כאלו לא הי' בלבו שום התפעלות אלקות ולא יעשה רושם כלל להחליש לכח המדות רעות החומרי' דתאוות גשמי' אפי' כמלא נימא וז\"ש ותאכלנה כו' ולא נודע כו' ומראיהן רע כאשר בתחלה כו' (לפי שאין לרע חיבור וקשר כלל עם הטוב שהן מפורדין זמ\"ז כנ\"ל) וכמו כנ\"י בגלות שהן בבחי' חלום בשינה כמ\"ש אני ישינה שכל חכמתם האלקי' תתבלע בטרדת הפרנסה וכה\"ג כו' והי' כלא הי' כו' וכך הוא ג\"כ בעסק התו' דגם ששרשו בעה\"ח שכולו טוב בעצם ומדות דחכ' דתו' הן דרכי החיים העליוני' שכולו טוב והי' ראוי להיות שיוכל אור הטוב דתו' להפוך לז\"מ רעות דק\"נ החומרי' כטמא ופסול כו' כמו שהי' בעץ שהשליך למים המרים דמרה שנמתקו המים כו' אבל בחלום דפרעה (שבבחי' או\"ח דתוהו שיוכל להיות העליון תחתון בעולם הפוך כו') הי' להיפוך שהמדות רעות דז\"פ רעות אכלו לז\"פ טובות ולא נודע כו' והיינו כמו שנראה לעין בעוסקי התו' של\"ש שמרגיש א\"ע ביותר שזהו מבחי' עה\"ד טו\"ר שמרגיש הטו\"ר כו' שמזה נמשך כל תאוות חומריות ולגרמי' דוקא ושיהי' בעצמו יש ודבר דוקא היפוך בחי' הביטול לאין האלקי' דבחי' מ\"ה דחכ' דתו' כו' ע\"כ עושה א\"ע יש ודבר בעסק התו' לומר אין לי אלא תו' בבחי' נפרד מאלקו' ומרחיב דעתו עלי' בגסות כו' ורק לגרמי' להתגדל בה או לפרנסתו וכה\"ג שזהו היפוך גמור מבחי' ביטול דכח מ\"ה דחכ' ולזאת הגם ששרש התורה עצמה מעה\"ח נהפך סם חיים לסם המות להשחית נפשו ממש כמ\"ש למשמאילים בה כו' כמו שז\"פ רעות אכלו לז\"פ טובות ומראיהן רע כבתחלה ממש כך בחי' הרע דז\"מ רעות שבלעו לז\"מ טובות דחכ' שהוא לכל בחי' הטוב"],[2300680472,"הגנוז בחכ' דתו' שלמד של\"ש באופן שלא עשה בנפשו שום רושם טוב אף להרהר בתשובה לפרקי' או להתעורר באהוי\"ר וקבעומ\"ש כו' אלא מראיהן רע ממש כבתחלה כו' והי' ראוי להיות להיפוך שמאור שבה יחזירנו למוטב להפוך הרע לטוב כו'. וכ\"ז לפי שפרעה חולם בקטנו' דמח' בהשגות אלקי' מרחוק בתפלה (עד שנדמה לו שעומד למעלה מן היאור כו') (שזהו רק חיצוני' דאותיות המח' שמלביש לפנימי' העונג ורצון וגילוי האור האלקי רק כנקודה דחולם ע\"ג אותיות ולא בבחי' פנימי' כלל כנ\"ל). וכמו\"כ חלום הב' בז' שיבלי' כו' שזהו בבחינת תושבע\"פ שנק' לחם מן הארץ שצומח מלמטה למעלה בבחי' או\"ח כנ\"ל כשעוסק בפלפול של הנ\"ל שמצמיח שיבלים רקים שדופות קדים כו' כמ\"ש לא בשמים היא כו' ולא בים כו' לא תמצאנה בגסה\"ר כו' אדרבה א' אין התו' מתקיימת אלא במי שממית עצמו עליה שממית כל בחי' עצמו' שאינו מחזיק טובה לעצמו כלל כמו רב עולא דגריס כו' רק לעשות נח\"ר ליוצרו לבד שיומשך אור השעשועי' העצמיי' בתוש\"מ ותושמ\"ט כנ\"ל שזהו בחי' השיר בנגינות וטעמי' שנק' שירו כו' וזהו במקרא דתושב\"כ שנמשך בה מעונג ושעשועי' העליוני' בגילוי הפנימי' גם בחיצוני' דוקא כנ\"ל (או לגנוז האור בכלי' בבחי' הביטול דיש לאין דוקא היפוך גסות והרגשת עצמו הנ\"ל) וכמו\"כ בעסק בתושבע\"פ שזהו ומ\"ש ובלילה שיר\"ה עמי בה\"א שהוא ענין היגיעה בעומק העיון מאד בביטול כל העצמי' (בבחי' או\"ח לקדמותו ממש שמגיע בשעשועי' עצמיי' ממש כנ\"ל) שעז\"א כל העוסק בתו' בלילה חוט של חסד נמשך עליו ביום שנא' יומם יצוה ה' חסדו לפי שבלילה שיר\"ה עמי ובחי' חוט של חסד היינו בחי' הפנימי' דעונג העצמי דא\"ס באה\"ר העליונה שנק' אה\"ר בתענוגי' כמ\"ש מה יפית כו' שנמשך על העוסק בתושבע\"פ בלילה דוקא שהוא הנק' חוט של חסד דהיינו אה\"ר העצמי' מחדש בבחי' מקיף למעלה מכפי מדת הטוב בעצם של הנשמה האלקי' לדבקה בו ית' בהתקשרות עצמי' באה\"ר בתענוגי' שיומשך גם בחיצוני' דנה\"ט להפוך גם הרע לטוב כו' ולפי שהעלאה זו ביגיעת המוח והרצון כמ\"ש למחכה לו למאן דדייק מילין דחכ' כו' ממשיך מעצמי' התענוג העליון בנשמתו כו' וכאשר בחי' הפנימי' מאיר בחיצוני' זהו היפוך בחי' החלום דקדושה ברישי אתוון הנ\"ל ואז נהפוך הוא שאין בחי' פרעה שהוא בחי' המל' סודכד\"ר עומד על היאור העליון הנ\"ל שהוא נהר שיוצא מעדן אלא בחי' היאור עומד על פרעה שהוא החולם שממשיך עליו מבחי' פנימי' העונג דעצמי' באה\"ר עצומה בתעה\"פ ועצמי עד שיהי' כולו רק טוב ולא יהי' פרות הרעות כלל כי אין רע יורד מלמעלה מעה\"ד כו' כנ\"ל או שיהופך גם הרע לטוב כמו העץ שהמתיק למים המרים וכענין מאור שבה מחזירו למוטב כנ\"ל וד\"ל:"],[2300680036,"(א) <b>ויגש</b> אליו יהודה. כתיב קורות בתים ארזים וקאי בבהמ\"ק דשלמה כידוע. ומשמע ששיבח בזה לבנין זה דשלמה ביתרון מעלה על משכן שילה וגם על משכן דמשה שלא היה בהן ארזים. וי\"ל דהלא ידוע שהיו דפני המשכן דמשה מעצי שטים שהוא מן המשובח שבארזים ובהמ\"ק דשלמה לא הי' רק הקורות ארזים לבד כי הדפנות היו מאבנים כידוע וא\"כ נהפוך הוא שיש יתרון מעלה במשכן דמשה שהיו הדפנות כולם מעצי שטים ואם שלא הי' שם קורות ארזים כמו בבנין דשלמה הרי היו שם היריעות תחשים כו' ובבנין דשלמה היה מקורה בקור' להחזיק המעזיבה בלבד שהוא מעפר דומם. אך הנה יש להקדים ענין אחד והוא מחלוקת רז\"ל אם ארץ קדמה לשמים או שמים קדמו לארץ (ומ\"ד שמים קדמו לארץ כמ\"ש בראשית כו' את השמי' ואח\"כ את הארץ ומ\"ד ארץ קדמה ממ\"ש ביום עשות ה' כו' ארץ ושמים כו'). וי\"ל טעם מחלקותן ואיך שניהם אמת. דהנה ידוע בע\"ח שיש ב' מדריגות אור ישר ואור חוזר ויש שני אופנים באו\"ח. א' שבא אחר או\"י והוא מ\"ש נעוץ תחלתן בסופן שזהו בחי' או\"י ואח\"כ נעוץ סופן בתחילתן שזהו בחי' או\"ח וכמ\"ש בפרד\"ס הרי ודאי דאו\"ח זה אין לו יתרון מעלה על האו\"י מאחר שמכח התחלה בא הסוף אינו חוזר רק לתחלתו כמשל הכאת החום בארץ או כאור הנופל במראה או כמעין שחוזרין למקום נביעתן בתחלה לבד ולא למעלה משם כידוע. והב' הוא בחי' או\"ח שקודם לאו\"י דע\"ז אמר ארץ קדמה לשמים קדמה ממש. וכך ענין סומעבמ\"ת אין הכוונה שעלה רק לתחלת המח' לבד שזהו כמו נסוב\"ת לבד שהוא או\"ח שאחר או\"י כנ\"ל אלא הכוונה שעלה במח' תחלה וקודם לתחלת המח' והוא או\"ח שקדם לאו\"י ולכך לא אמר סוף מח' עלה אלא סוף מעשה דוקא דסופא דמח' אינו עולה רק לתחלת המח' לבד אבל סוף מעשה שזהו לאחר הגמר המעשה הוא שעלה כבר לפני תחלת המח'. וזהו ההפרש בין עולה לעלה דעולה הוא או\"ח שעולה אחר או\"י ועלה הוא שעלה כבר קודם לתחלת המח' דאו\"י. ופי' סוף מעשה דוקא דתחלת המעשה הגם שנק' סוף בכלל ע\"ז אמר נעוץ סוב\"ת לבד ולא לפני תחלתן וד\"ל. ומ\"ד שמים קדמו לארץ היינו בבחי' או\"י שקדם לאו\"ח כמ\"ש בראשית ברא כו' כלומר בתחלת המח' ונק' תחלתן וכתרגומו בקדמין כו' אבל מ\"ד ארץ קדמה היינו ממ\"ש ביום עשות כו' שזהו לאחר גמר וסוף המעשה דוקא שזהו שעלה כבר במח' שלפני התחלה כנ\"ל וד\"ל ונמצא דשניהם אמת:\n(ב) <b>ולהבין</b> ביאור הדברים הללו יש להקדים לזה משל מהשפעה גשמית למטה שאדם משפיע דבר מה כמו השפעת חסד וטוב הנה כלולה שפע זו מרוחניות וגשמיות דהיינו תחלת התעוררות החסד שבמוחא ולבא לעשות טוב וחסד לעני בפו\"מ הנה במוחו השרש הראשון ברוחניות השפע הוא הטעם לרצון של חסד מפני התעוררות הרחמנו' העצמי כו' ויורד למח' ומן המח' ללב בהתעוררות המדות ומשם לדבור עד המעשה בפו\"מ שהוא החסד הגשמי וא\"כ ודאי כל הילוך השפע ברוחניות מרצון עד המעשה עיקר"],[2300680052,"המכוון ברוחניות השפע הזאת אינו אלא סוף הדבר דהיינו המעשה בפו\"מ דוקא ואין עיקר הכוונה בשפע זו הרוחניות הבאה ונמשכת ברצון ושכל ומדות ומח' ודבור בלבד שהרי אם ישאר השפע במח' ודבור ולא יקיים בפו\"מ לא נק' חסד כלל וכלל והיינו נעוץ תחב\"ס דוקא שלצורך הסוף שהוא עצם המעשה נמשך התחלה שהוא הרצון ושכל כו' ואם לאו הסוף לא היה התחלה וכן להיפוך נסוב\"ת דהיינו שאין הכח ועוז בסוף בפו\"מ רק מכח התחלה שהוא התחלת התעוררות הרצון והשכל כו' שאם נפסק התעוררות הרחמים ברצון ושכל כו' יופסק כח המעשה בפו\"מ ונמצא שפע הרוחנית שרש החיות לגשמית והא בהא תליא והיו לאחדים וזהו כדמיון המים שנמשכים מגבוה לנמוך שחוזרים ועולים למקורם לבד ולא למעלה מתחלתן כנ\"ל בבחי' או\"י ואו\"ח וכמו\"כ בשפע רוחניות בהשפעת שכל וחכ' לתלמיד המקבל לפי\"ע שנק' קבלת התלמיד גשמית השפע וסוף לגבי תחלת אור רוחנית השפעת המשפיע שאין בסוף רק במה שבתחלה לבד ולא למעלה ממנו שהרי לא קאים אינש אדעתיה דרבי' כו' ועיקר הכוונה הוא בכלות השפע ובקבלת התלמיד שלזה יצא האור בתחלה ואם לא יתקבל השפע במקבל לא נק' שפע כנ\"ל וד\"ל שזהו נתב\"ס כו' וד\"ל. והנמשל מזה יובן למעלה במ\"ש עולם חסד יבנה הרי בראשית ברא כו' בחכ' או ברצון שנק' תחלה בכלל ויורד ונמשך חסד זה שברצון וחכ' למדות חג\"ת דאצי' ומשם למח' ודבור העליון עד שנתהווה הבריאה יש מאין בפו\"מ שזהו הסוף שבודאי סוף דבר ההשפעה הזאת בפו\"מ הוא היה עיקר הכונה בראשית התעוררות החסד במאציל ברצונו וחכ' כו' ונעוץ תחב\"ס כנ\"ל. וכמו\"כ להיפוך נעוץ סופן דמעשה בתחלתן שכל הכח ועוז אלקות בבחי' המעשה חוזר לתחלת התעוררות החסד ברצה\"ע ולא למעלה הימנו כו' וד\"ל. וזהו מ\"ד שמים קדמו לארץ כמ\"ש בראשית ברא כו' השמים כו' כמו שהמח' קודמת למעשה בירידת השפע מתחלתן לסופן כנ\"ל. וכידוע דארץ נק' הסוף כמו הארץ הדום רגלי והכל הי' מן העפר בפו\"מ כמו תוצא הארץ הגם שעיקר הכוונה דתחלת הרצון שהוא הכתר הוא רק בשביל סופן כו' וכמ\"ש אפיק' יו\"ד תיקונין כו' רק לאחזאה כו' (דמצד עצמות המאציל לאו מכל אינון מדות כלל) כמובן ממשל הנ\"ל בשפע של שכל וחסד שהרוחני' דרצון כו' רק בשביל הגשמית דפו\"מ במקבל ואם לאו לא הי' משפיע מ\"מ הרי להיפוך ג\"כ דנעוץ סופן בתחלתן דוקא שאין עיקר ומקור הכח ועוז דסופן רק מתחלתן לבד כנ\"ל כמו כל קשר הגשם ברוחני וכך הוא בכללות ההשתלשלות דאבי\"ע ע\"ס דאצי' בכלל הוא בחי' רוחנית השפע שהוא כמו הרצון ושכל ומדות כו' ומל' דאצי' בבי\"ע שנק' מעשה הוא בבחי' גשמית השפע שבא מאין ליש ממש כו' וד\"ל. והנה בזה יובן עכ\"פ שאין יתרון מעלה לסוף על התחלה ולא לתחלה על הסוף שאעפ\"י שעיקר התחלה הוא בשביל הסוף אין להכריח משום זה שיש יתרון מעלה לסוף על התחלה כלל וכן להיפוך ממה שעיקר הכח ועוז מתחלה לסוף אין להכריח שיש יתרון מעלה להתחלה על הסוף כלל אלא שניהם שקולין"],[2300680068,"כאחד ממש. ויובן זה ממה שאנו רואים ברצונו של אדם שעיקר שלימותו אינו אלא כשבא למעשה בפו\"מ דוקא הרי מעשה משלים לרצון וכן להיפוך עיקר המעשה הוא הרצון שהרי המעשה בלא רצון אינו כלום כמו גזירת מלך שעיקר המעשה הרי הוא רק לעשות נח\"ר שאמר ונעשה רצונו שזהו רק מה שעושין רצונו דוקא ולא המעשה עיקר אלא הרצון דוקא ובאמת אי אפשר לומר שיש יתרון מעלה למעשה על הרצון ממה שעיקר שלימות הרצון הוא מעשה מאחר שאין מעשה בלא רצון וכמו\"כ אי אפשר לומר שיש יתרון מעלה לרצון על המעשה משום זה מאחר שעיקר הרצון הוא במעשה דוקא אלא צ\"ל משום דשניהם כאחד באו לכך אין שלימות לאחד בלא זולתו כנ\"ל מאחר דרצון בלא מעשה ומעשה בלא רצון אינו כלום וזהו דנעוץ תחב\"ס וסופן כו' דר\"ל שאינם שני דברי' מחולקים כלל אלא כמו שהתחלה שלימותו בסוף כך הסוף שלימותו בתחלתו ודוקא באמצעות חיבורם יחד הוא בא במציאות דבר מה עד שכל א' נק' משפיע לזולתו ומקבל מזולתו כי הרצון שנשלם ע\"י המעשה הרי היא מקבל ממנו אעפ\"י שבאמת הוא עיקר המשפיע למעשה כנ\"ל וכמו\"כ המעשה שנשלמת ע\"י הרצון ומקבלת ממנו הרי היא בחי' משפיע לרצון מאחר שהרצון נשלם על ידה דוקא כנ\"ל. וזהו מבלי שימצא ראש וסוף דסוף נעשה ראש להשפיע לתחלה וראש נעשה סוף לקבל מסופו מטעם הנ\"ל בענין נעוץ כו' וכמו הראש והרגל שהרגל מקבל ההילוך מרצון שבראש ושלימות הרצון בראש נעשה ע\"י הרגל ואעפ\"כ נק' ראש ורגל וכך הוא ענין נעוץ תחלתן כו' שנק' עכ\"פ תחלתן וסופן אעפ\"י שבאמת מבלי שימצא בהן ראש וסוף מטעם הנ\"ל וד\"ל. והנה לפי\"ז יקשה מאד על ענין מחלקותם דמ\"ד שמים קדמו ומ\"ד ארץ קדמה דלכאורה אין בזה מחלוקת כלל לפי הנ\"ל דודאי שמים קדמו מטעם דברוחניות הרצון קודם למעשה והוא בחי' משפיע למעשה והוא ענין נעוץ סוב\"ת וגם זה אמת דארץ קדמה משום דנעוץ תחב\"ס שהרצון נשלם ע\"י המעשה (ולפי' זה בנעוץ כו' נתהפך מאו\"י לאו\"ח דלא כדלעיל דנעוץ תחלתן כו' בחי' או\"י והכל ענין אחד). ואמנם מאחר שבאמת מבלי שימצא בהן ראש וסוף מטעם הנ\"ל הרי הדיעה הג' אמיתית יותר והוא מ\"ד הג' דשמים וארץ כאחד ממש נבראו שנאמר קורא אני אליהם יעמדו יחדי כו' שהתחלה והסוף כאחד באו ממש ע\"כ אין שלימות זה בלא זה רק באמצעות שניהם יחד כו' וד\"ל. אך באמת א\"א לפרש ענין ארץ קדמה כו' מטעם שהעיקר הוא בסוף מעשה השפע בגשמית דמ\"מ איך קדמה ארץ מאחר שהמעשה בא אחר המח' דוקא דלעולם אי אפשר שיהי' קדימה למעשה על המח' דא\"א למעשה בלי קדימת מח' אליה שזהו טעם מ\"ד שמים קדמו לארץ כמו המח' ורצון שקדמה למעשה כנ\"ל אלא צ\"ל דמ\"ד ארץ קדמה היינו בעצמות המשפיע טרם שיתחיל להשפיע הוא שעלה במח\"ת וקודם לשמים שהוא תחלת המח' ורצון כו' כנ\"ל וכפי' ענין סוף מעשה עלה במח' תחלה שהוא לפני תחלת המח' כו'. ולפי\"ז מ\"ד שמים קדמו שהוא בתחלת המח' של ההשפעה וגמרה"],[2300680084,"הוא הארץ אינו חולק כלל על ענין ארץ קדמה לפני תחלת המח' והפשט משמע דחולק על מ\"ד ארץ קדמה וסובר שמים קדמו לפני תחלת המח' וראיה ממ\"ד הג' דשמים וארץ כאחד נבראו שהוא לא כזה ולא כזה שאין קדימה לאחד מהן על זולתו דזהו ודאי לפני תחלה וסוף דההשפעה שכוללם בסקירה אחת כענין מח' אחת שצופה ומביט בה מראש לסוף כאחד מבלי קדימה לאחד על זולתו אלא בבת אחת נסקרים כמו עיגול הכדורי' אשר נתפס במח' שנק' מח' עגולי' כו' וכמ\"ש במ\"א. וא\"כ י\"ל מעתה שרש ענין ג' דיעות הללו החלוקים במקום אחד דוקא וד\"ל:\n(ג) <b>והנה</b> יש להקדים תחלה שהשמים נקרא משפיע בכלל והארץ נק' מקבל בכלל כמו אני אענה את השמים והם יענו את הארץ כו' (שהוא בחי' סובב וממלא בכלל) וא\"כ ודאי א\"א לומר שהמקבל יקדים למשפיע אלא המשפיע קודם ואיך יחלקו בזה דודאי שמים קדמו כו' אלא עיקר מחלקותם בשרש של המשפיע והמקבל מי קדם למי דמ\"ד שמים קדמו שרש של המשפיע קדם בעצמות ומ\"ד ארץ קדמה שרש של המקבל קדם כו' וכמו ענין אור וכלי למעלה דיש שרש לכלי קודם לשרש של האור דשרש האור מהקו\"ח ושרש הכלי מבחי' הרשימו כו' כמ\"ש במ\"א. וזהו מ\"ד ארץ קדמה ומ\"ד שמים קדמו משום דשרש הקו\"ח מאור הפנימית והעצמיי' שלפני הצמצום דרשימו שזהו בחי' טהירו עילאה שנק' שמים בכלל כידוע וד\"ל. ומ\"ד שניהם כאחד כו' כמ\"ש השמים ושמי השמים כו' דקאי בטה\"ע וטה\"ת לא יכלכלוך בבחי' כלי לכלי כי השמים כסאי והארץ כו' זהו סובב וממלא בכלל ושמי השמים מקיף למקיף הכללי הוא עצמות אא\"ס שלפני הצמצום ועכ\"ז מאחר שנק' שמי השמים בכלל מקור השפעה הוא ואינו בחי' העצמות ממש והוא כמו ששיער בעצמו בכח כו' ולכך לא יכלכלוך אפי' כלי לכלי בהיכל ובית החיצוני' כמ\"ש איזה בית כו' כידוע דממקיף למקיף נעשה בחינת היכל ובית כו' ומהמקיף עצמו שרש הכלים כו' ומ\"ד דשמים וארץ כאחד היינו ב' השרשים דאורות וכלים שהן מקיפים ופנימים כאחד באו מן העצמות ששניהם שקולים כאחד ממש (כמו ששקולים או\"י ואו\"ח דתחלה וסוף הנ\"ל לגבי עצמות המשפיע טרם שמשפיע כנ\"ל וד\"ל). ובאמת מפני ששרש הכלים מבחי' המקיפים דוקא שנק' שמים והוא הנק' ארץ בחי' מקבל ע\"כ אמר דשמים וארץ כאחד נבראו דהיינו הך וד\"ל. ויובן זה עד\"מ שפע גשמית למטה דהנה אנו רואים שיש תענוג גדול בכל שפע הנמשך ממשפיע למקבל כמ\"ש יותר משהעגל כו' הפרה רוצה להניק כו' וכטבע הטוב להטיב שיש לו תענוג גדול בזה ואם לא התענוג הזה להשפיע טוב לא היה משפיע כלל וכלל כידוע ונמצא ודאי שיש שרש ומקור לתענוג זה בעצמות נפש המשפיע וזהו תענוג של ההשפעה מצד עצם ההשפעה שהוא תענוג גדול למשפיע. ואמנם הנה אנו רואים שעיקר קבלת התענוג של המשפיע בהשפעתו אינו רק מקבלת המקבל דוקא ואם אין מקבל לקבל השפע אינו חפץ ומתעורר להשפיע כמו טבע הטוב למי שצריך הטובה שאינו מתעורר"],[2300680100,"ואינו מתענג להשפיע הטוב רק למי שצריך לטובה זו ולזולתו שאינו צריך לטובה זו אינו חפץ להטיב לו כלל ואם הי' העיקר של התענוג רק מצד עצם ההשפעה לבד גם למי שאינו צריך היה משפיע ואדרבה אנו רואים שהמקבל דוקא מעורר הטוב והחסד לפ\"ע קבלתו לבד אם רב או מעט כו' דהיינו אם המקבל כלי הגון וראוי לקבל הרבה טוב או בפנימית הטוב יותר אז יתעורר במשפיע פנימית טובו וחסדו להשפיע או ריבוי הטוב כו' ואם כלי המקבל מעט ובלתי ראוי לקבלה כ\"כ לא יעורר במשפיע רק מעט ובחיצוניות הטוב שבו ועד\"ז בדרך פרט השפע אם מזון או לבוש או ממון או חסד בגופו או חסד בשפע שכל ברוחניות הכל רק לפי העלאת כלי המקבל שעולה במשפיע ומעורר בו החפץ והרצון ותענוג להשפיע לו לפי אופן מדת כלי המקבל ונמצא שתענוג זה במשפיע אל המקבל דוקא הוא בא ראשון ושרש למה שבא התענוג אח\"כ בגילוי אור ושפע שלו שהוא התענוג בהשפעה עצמה הנ\"ל עד דמה שמתענג בהשפעתו בגילוי גם הוא רק מפני שיורד השפע ומתקבל למקבל ואם אינו מתקבל נפסק התענוג באמצע השפע לגמרי כמו החסדן בטבעו שרואה איש עני ומדוכה צועק ומבקש טרף חיותו ברוח נשברה יעורר בלבו מיד רב חסד וטוב להשפיעו ומתענג ביותר בעת השפעתו לו המזון והמחיה ואמנם אין זה התענוג רק כשרואה שיחיה ממש בזה השפע לעני זה במזון ומחיה זו שנתקבלה השפע בכלי טוב (עס איז זייער אן גלייגט) אך כשרואה שאין השפע מתקבל בכי טוב לעני זה אם מפני גסותו או רשעותו למאוס בטוב ההוא כו' חוזר ומתהפך במשפיע מעונג לצער וגרעון השפע להפסיק ולצמצם לגמרי ואינו חפץ בה כלל וכך הוא בשפע הרוחנית כמו שפע שכל לתינוק ותלמיד וכה\"ג שעיקר השלימו' של התענוג בשפע זו הוא דוקא כשרואה שנתקבל בכי טוב בכלי התינוק והתלמיד אז יגבר אור התענוג בשפע זו (כמו דוגמא שאמר רב המנונא סבא על רשב\"י זכאה מאן דמליל על אודנין דשמעין כו') וע\"ז אמר יותר משהעגל רוצה לינק כו' יותר מתענוג ותשוקה בעגל המקבל לקבל יש בפרה המשפיע הרבה תענוג ביותר להניק ולהשפיע אבל דוקא להניק שמתקבל ההנקה (והוא לתלמיד הגון שמקבל בכי טוב כמו אודנין דשמעין כו') (בל\"א ער נעמט צו זייער גוט) ונמצ' שהמקבל עשה לתחלת התעוררות התענוג במשפיע שיחפוץ ויתענג בזו השפע כנ\"ל וגם בכללות השפע עיקר השלימות של תענוג הראשון בא מצד קבלת המקבל בכי טוב דוקא כו'. אך א\"כ הרי אין תענוג כלל במשפיע מצד עצם השפעתו בלתי מקבל וזה אינו דודאי אנו רואים בחוש שמתענג כל משפיע בעת השפעתו הטוב עד שמחיה א\"ע באור וחיות ותענוג יתירה במה שהטיב מטובו יותר מכל תענוגי חיי עצמו במזונו וכספו כו' שהרי יוכל ליתן כל אשר לו ולא ישאר לעצמו כלום כמו שידוע בבחי' חסד דאברהם שהי' משפיע כל אשר לו כו' כמ\"ש וכל אשר לאיש יתן בעד נפשו שהוא בשביל המקבל הנק' נפשו ולא נשאר לעצמו כלום כ\"א גוויתו כו' א\"כ ודאי כלא חשיב חיי תענוגי עצמו בכל אשר לו נגד התענוג בזה"],[2300680116,"שמשפיע כל אשר לו כו' וזהו רק מצד עצם טבע הטוב (בל\"א גוטער) שיתן כל עצמותו והיינו שזה כל תענוגיו הפנימים ביותר מכל חיי עצמו כו' והרי באיש שאינו עצם הטוב כ\"כ גם שיראה כלי המקבל טוב לקבל לא יתעורר כ\"כ ליתן משלו כי אוהב א\"ע ביותר כו' ולפי\"ז אין המקבל עושה כל עיקר התענוג שבמשפיע כנ\"ל שהרי כבר ישנו בטבעו הטוב בעצם אך שהמקבל מביאו מהעלמו לגילוי ביותר והוא מפני ששלימות של עצם הטוב להטיב אינו בא כ\"א כאשר יש מקבל הטוב ההוא דוקא כנ\"ל שעולה אופן כלי קבלת המקבל דוקא בבחי' שרש ומקור לתענוג השפע לבא בגילוי וכן בסוף השפע אבל לא שעושה לעיקר עצם טבע התענוג הפנימי שכבר מוטבע בו בטבע תולדתו ונמצא דשניהם אמת ואין זה בלא זה כו' וד\"ל):\n(ד) <b>והדוגמא</b> מכל זה יובן למעלה בענין מחלוקת דלעיל אם שמים קדמו או ארץ קדמה כו'. דהנה כתיב וירא את כל אשר עשה לאחר גמר השפע והנה טוב מאד שזהו עד\"מ התענוג של המשפיע הנשלם בגמר קבלת השפע במקבל בכי טוב דוקא כנ\"ל. וכך כל אשר עשה ה' בחכ' ומדות להשפיע בדבור ומעשה הכל נעשה ונתקבל בכי טוב מאד הרי זה היה עיקר הכוונה בתחלת התענוג להשפיע חכמה ומדות כו' וכנ\"ל דאם לא נתקבל בטוב נפסק תחלת התענוג וכאשר יתקבל ונעשה בטוב יתחזק תחלת התענוג לחזור ולהשפיע כו' וכך כל אשר עשה שנעשה בטוב מחזק לתחלת תענוג מחדש לחדש מע\"ב בעונג שבחכ' כו' והוא ביום השבת דכתיב וקראת לשבת עונג כידוע וזהו מ\"ד ארץ קדמה דהיינו אופן טוב כלי הקבלה דמקבל כנ\"ל שהוא לאחר שתוצא הארץ הכל היה מן כו' בכי טוב הוא שעלה תחלה וממנו שרש הראשון לגילוי שפע דעונג בחכ' עד היו\"ד מאמרות אח\"כ כנ\"ל במשל דהתענוג של המשפיע בתחלה נעשה מהמקבל דוקא (ואע\"פ שאמר וירא את כל אשר עשה שזהו בגמר המעשה בפו\"מ דוקא. אך זה עלה במח' תחלה וזהו ארץ קדמה שנאמר ביום עשות ה' אלקים שנתקבל בכלי דשם אלקים הוא שעלה במח' תחלה וית' בסמוך שגמר המעשה ממש מדריגה בפ\"ע העולה על כולנה. וז\"ש וירא את כל אשר עשה כו'). ומ\"ד שמים קדמו היינו כמו עד\"מ תחלת עצם הטוב להטיב שכבר מוטבע בו בעצם וקדם הרבה לבחי' גילוי שלו בבחי' התעוררות שלו למקבל הטוב כנ\"ל וכך ידוע למעלה שמוטבע בכל עילה להתענג מאד בשפעו לעלול הימנו ואם לא היה מוטבע בעצם בכל עילה תענוג עצמי זה להשפיע לשלמטה הימנו הנק' עלול לא היה מתחבר שום אור עליון בתחתון כלל כו' וא\"כ ודאי מובן שבתחלת שרש הכל כמו כאשר עלה ברצונו וחכ' כו' הרי נמשך זה הרצון ע\"י בחי' תענוג עצמי שיש בעצמו' לשפע זו של הרצון וכן מרצון לחכ' כו' עד התענוג שבדבור להשפיע במעשה סוף הכל כו' ונמצא שקדם בעצמות המאציל תענוג מוטבע כטבע תענוג הטוב בעצם להטיב שמחמתו נמשך הרצון להטיב כו' ומה שע\"י מקבל הטוב נשלם עיקר התענוג הזה הוא בא אח\"כ בגמר השפע אבל תענוג העצם שבטוב קדם בעצמו בודאי תחלה וקודם גם לשלימות שפעו במקבל"],[2300680132,"כמובן ממשל הנ\"ל. ומ\"ד ארץ קדמה דעתו שקדם בעצמו' שרש לתענוג זה שיתקבל שפע הטוב במקבל גם לעצם תענוג הטוב להשפיע מטובו כו' מאחר שאנו רואים בגילוי השפע שעיקר הכוונה בשביל המקבל ואם לאו נפסק לגמרי כו' מוכרח שזה היה בשרש בעצמו' תחלה וקודם לשרש של תענוג של טוב העצמי שבו (וכמו האור המאיר שאלו אין כלי אין מציאות האור כלל נמצא שהכלי קדם לאור אחר שבעבורו ירד במציאות כו'). וטעם מ\"ד שניהם כאחד נבראו כו' משום דבאמת הרי אין שלימות לזה בלא זה כלל דודאי כל גילוי אור תחלה וסוף שבא בתענוג משפיע השפע למקבל לא נגמר שלימותו בשום צד ואופן באחד מהן בלא זולתו דהיינו כמו שאם אין מקבל אין משפיע וכך אם אין משפיע אין מקבל וכמו ששלימות המשפיע מן המקבל בא כנ\"ל כך ודאי שלימות המקבל מן המשפיע וזה בלא זה אינו נק' מציאות שלם ובאמצעות חיבורם יחד נק' מציאות אחד וכמ\"ש והיו לבשר אחד וכידוע דכללא דדכר ונוק' נק' אדם אעפ\"י שזה משפיע וזה מקבל אין לומר מפני שהמקבל לית לי' מגרמיה כלום רק מה שמקבל מהמשפיע שמפני זה המשפיע עיקר והמקבל טפל אדרבה מפני שנשלם המשפיע ע\"י המקבל הרי המקבל עיקר והמשפיע טפל וכן להיפוך בלא משפיע לית לי' כלום כו'. ומזה יובן שגם בשרש שרשם דדכר ונוק' משפיע ומקבל שהוא שרש התענוג הנמצא במשפיע ובמקבל שהוא ענין טבע הטוב בשביל המקבל דוקא שניהם כאחד באו בעצמות בלי שיקדים הא' על זולתו כלל ובסיבת זה אין לאחד שלימות בלא זולתו ושניהם כאחד חשיבי בבוא הדבר לגילוי שפע למקבל כנ\"ל וד\"ל. (והוא ענין הנ\"ל באו\"כ אם שרש הכלים קדמו בעצמות או שרש האור קדם כו' ואם שניהם כאחד באו מטעם כל הנ\"ל וד\"ל):\n(ה) <b>והנה</b> אחר כל הנ\"ל יובן בענין ג' דיעות הנ\"ל שהם חלוקים הכל במקום אחד והוא לפני ההשפעה דמשפיע דמ\"ד שמים קדמו הוא בעצם התענוג להשפיע כנ\"ל ומ\"ד ארץ קדמה במח' בעצמות שהוא בשביל הקבלה דמקבל דוקא ומ\"ד ששניהם כאחד באו בעצמות כנ\"ל זהו ענין תחלה וסוף דתענוג זה בשפע באו כאחד כמו עיגול הנתפס במח' כאחד שזהו ענין מח' כללית שצופה כו' כנ\"ל (והוא מה ששיער בעצמו בכח מה שיהי' תחלה וסוף בשפע זו שבא שיעור זה בסקירה אחת ונק' מח' אחת לבד כנ\"ל) ששייך הכל לענין ההשפעה עכ\"פ. אבל הנה יש עוד מדריגה ד' שעולה על הכל והוא ענין סוף מעשה עלה במחשבה תחלה שזהו לפני המח' הכללית שכוללת תחלה וסוף הנ\"ל (והיינו קודם ששיער בעצמו בכח מה שעתיד כו' שלמעלה מטהירו עילאה וטה\"ת שע\"ז אמר השמים ושמי השמים לא יכלכלוך כנ\"ל ונק' יחיד כו'). ויובן זה ממ\"ש וירא אלקים את כל אשר עשה כו' כמו שאנו רואים באדם למטה שבגמר בנין ביתו משתעשע בטוב מלאכתו שאעפ\"י שעונג זה מפרט טוב הבנין אבל משתעשע כל נפשו בעונג זה ונוסף שלימות התענוג בעצם מזה העונג בעילוי והגבהת עונג עצם הנפש ביותר מכמו שהיה כו' וכך מכל אשר עשה שכולל תחלה"],[2300680148,"וסוף דתענוג שבמלאכתו הנ\"ל וזהו מכל דוקא אז נתמלא אור שעשועים העצמיים שבעצמותו שלמעלה הרבה מכל עיקר התענוג שבהשפעה בתחלה ובסוף הנ\"ל ואם לא היה טוב מאד הרי כל אשר עשה בעונג בתחלה וסוף אינו ערך כלל להעלות ולהוסיף אור בעצמות התענוג הפשוט שנבדל בערך מכל עיקר העונג להשפיע למקבל דכל ענין התענוג הזה הוא חוץ מעצמותו כו'. וא\"כ י\"ל לכאורה מאין יבא הכח ועוז בטוב מאד שבכל אשר עשה להגיע לעצמותו ממש אחר שאין ערך ביניהם כלל וכלל כו' אלא צ\"ל דאעפ\"י שתענוג זה בהשפעה חוץ מעצמותו אבל מצד שיש בעצם הטוב ליתן כל עצמותו כנ\"ל ואין זה רק בקבלת המקבל בכי טוב כנ\"ל ולכך מכל אשר עשה דוקא כו' שהוא בכלי המקבל כשהוא טוב מאד בלי גבול כמו שהוא בעצם הטוב בלי גבול שזהו כמו הנתינה של כל עצמותו במקבל דוקא כו' מזה מגיע לבחי' עצמות השעשועים שבשלימות עצמותו ממש דהיינו הך ממש וד\"ל. אבל קודם גמר המעשה בטוב מאד הגם שכבר היה ברצונו הנעלם בעצמו' בתענוג העצמי להיטיב לא הגיע זה לבחי' תענוג שבעצמותו ממש כו' וזהו וירא לאחר כל אשר עשה דוקא והנה טוב מאד בכלות יום הששי אז ויכולו השמים כו' שעלה הכל כאחד בעצמות התענוג שמצד העצמות ממש אבל קודם שגמר כל אשר עשה לא ראה עדיין שהוא טוב מאד והיינו כמ\"ד ארץ קדמה מאחר שמגמר המעשה בא שלימות עצם התענוג מזה מוכרח שקדם זה בעצמות התענוג והוא ענין סוף מעשה עלה במח' תחלה פי' עלה ולא עולה דבהכרח שכבר עלה במח' טרם שבא לכלל בחי' התענוג להשפעה למקבל וזהו לפני תחלת המח' וסופה דשפע המשפיע הנ\"ל מאחר שבגמר המעשה דוקא עולה בעצמות ממש ומ\"ש וירא את כל אשר עשה דמשמע כשראה המעשה דוקא ולא קודם לכן היינו לא קודם שגמר המעשה אבל מה שעולה אחר גמרה הוא שכבר עלה לפני מח' א' כללית הנ\"ל וזהו לשון עלה במח' תחלה דמשמע שיש מח' שבאה אחריה והיא תחל' אליה והיינו לפני מח' כללית דתחלה וסוף עלה תחלה אליה מח' דסוף מעשה דוקא והפי' דסוף מעשה זה אינו ענין רק קבלת המקבל אלא המכוון מזה שנגמר בכי טוב קבלת השפע בפו\"מ כמו עד\"מ משעשועים שבגמר שלימות טוב הבנין שכל נפשו משתעשע בזה (והוא אלף הז' שבו מנוחה לחה\"ע כידוע שזהו בכלות אלף הששי שהוא יום הששי שראה את כל אשר עשה בו' אלפי שני כו' וד\"ל). ונמצא מובן מכל זה עכ\"פ בענין הנ\"ל בפי' נעוץ תחלתן בסופן כו' דמה שלא ימצא ראש וסוף ונק' עיגול מח' כללית הנ\"ל אעפ\"י ששניהם כאחד ממש מ\"מ נבדל בחי' סוף מעשה בזה במה שעולה הוא דוקא בעצמותו והוא המכוון העולה מסוף מעשה דוקא ויובן זה גם בענין הנ\"ל ברצון ומעשה ששקולים כאחד ואין זה בלא זה כלום כנ\"ל מ\"מ יש מעלה יתירה בגמר וסוף המכוון העולה לאחר שנעשה רצונו יותר מכל עיקר ענין הרצון הזה שבא במעשה ואין עיקר המכוון הזה רק בסוף מעשה כשהוטב מאד מכל אשר עשה רצונו כו' וד\"ל וזהו ביום עשות ה'"],[2300680163,"אלקים ארץ ושמים שזהו בגמר המעשה בכלות יום הששי שעלה סוף המכוון דשפע זו שנתקבל בשם אלקים משם הוי' כו' שמגיע בעצמות ממש ובהכרח שכבר עלה זה במח' תחלה (קודם ששיער בעצמו בכח כנ\"ל. ומ\"ש בע\"ח ענין חפץ חסד שזהו כמו טבע הטוב בעצם להטיב כו' היינו התענוג הכולל ההשפעה בכח ובפועל יחד כנ\"ל שמזה באה ענין מח' כללית הנ\"ל אבל כדי שיהי' חפץ חסד כו' תלוי עכשיו במעשה התחתונים והן נשמות הצדיקים בגופים בתו\"מ שלזה הי' הכוונה מתחלה לפני עלות מח' דחפץ חסד הכללי הנ\"ל וכמאמר במי נמלך בנשמתן של צדיקים כו' שכבר נמלך כו' כנ\"ל בפי' סוף מעשה עלה במח' תחלה והיינו שמה שעולה מטוב מעשה הצדיקים שזהו סוף המכוון הוא שכבר עלה ונמלך טרם ששיער כו' וד\"ל):\n(ו) <b>ואחר</b> כל הנ\"ל י\"ל ענין הנ\"ל בטעם שהי' בהמ\"ק דשלמה מאבנים בחי' דומם בדפנות ומעזיבה שזהו מדריגה עליונה יותר מעצי שטים כו' דקרשי משכן דמשה כו'. דהנה ידוע בסדר המדריגות דומם צומח חי מדבר כפי שבאו בסדרן בהשתלשלות ודאי בחי' המדבר שהוא האדם גבוה מכולן והחי למטה והצומח למטה מן החי והדומם הוא אחרון מכולם בהיותו במיעוט וצמצום היותר מכולן וידוע דזהו כפי הסדר בהשתלשלות מלמעלה למטה דוקא שהוא נק' או\"י בכלל וכמו\"כ ד' יסודות ארמ\"ע העפר למטה מכולם (וכמ\"ש בע\"ח דזהו ד' מדריגות דאבי\"ע אצי' בחי' מדבר ובריאה בחי' חי ויצירה בחינת צומח ועשיה בחי' דומם והן ארמ\"ע שהן נגד ד' אותיות הוי' יו\"ד באצי' ה\"א בבריאה כו' וזה מקבל מזה דזהו סדר ההשתלשלות בכלל ובפרט) והכל מלמעלה למטה דוקא אך מלמטה למעלה בבחי' או\"ח נהפוך הוא שהתחתון עליון מכולם והוא בחי' דומם למעלה מצומח וצומח למעלה מחי וחי למעלה ממדבר כו' לפי שבבחי' או\"ח חוזר לקדמותו ובשרש דצח\"מ כמו שהי' למעלה לפני סדר ההשתלשלות קדם הדומם לצומח וצומח לחי היפוך סדרן הבא בהשתלשלות מלמעלה למטה כו' וזה ענין נפלא איך יתכן לומר בדומם הגשמי שהוא בא במיעוט וצמצום החיות ביותר מהכל שבשרשו גבוה הוא מהכל וכמו\"כ בד' יסודות ארמ\"ע איך יאמר בשרש העפר שגבוה יותר משרש האמ\"ר אם למטה נמוך נמוך הוא מכולם. אך הנה אנו רואים דבר פלא והפלא ביותר במה שהצומח יצמח מן הארץ שהוא בחי' הדומם דעפר כמו האילן ופירותיו וכל צמח תבואת הארץ דלכאורה אם הצומח הוא למעלה מן הדומם וקודם לבא בסדר ההשתלשלות כנ\"ל א\"כ איך יקבל שפעו ביניקתו מן העפר הדומם שהרי שרשי יונקותיו דאילן בארץ הוא עיקר המצמיח אותו ואם אין לשרשיו יניקה בעפר אינו צומח כלל כידוע וכך כל צמח תבואות הארץ ע\"י קליטת הגרעין בעפר דוקא יצמחו ואם לאו לא יצמחו כלום כידוע בענין השרשה וקליטה כו' והנה ודאי יש בכלל מאתים מנה ויש בצומח מן הדומם שגם הוא דומם אבל יתרונו הוא שצומח בבחי' התפשטות וריבוי גדול שאין זה בדומם שאינו מתפשט כלל"],[2300680178,"וכלל רק כמו שהוא כך ישאר לעולם בלי תוס' כו' וא\"כ איך יהי' להיפך שסיבת הצמיחה תבא מן הדומם שהוא בהעדר ההתפשטות וצמיחה שזהו עיקר ההפרש בין הצומח והדומם ואיך יבא דבר מהיפוכו כו' ועליון יקבל מתחתון עילה מעלול כו' (כי ידוע דסיבת התהוות מהות הדומם בא מחמת הסתלקות וצמצום דחי וצומח עד שלא נשאר רק בחי' הדומם) ואם נאמר שיש בדומם מכח הצומח שהרי מקרא מפורש הכל היה מן העפר כו' זהו עצמו פלא גדול איך הכל היה מן העפר שזהו נגד ההשתל' דדצח\"מ וארמ\"ע כו' ומאין יש כח בעפר הדומם ליתן שפע יניקה לאילן הצומח שיגדל ממנה ומכחה דוקא שהרי גזרו אומר במשנה בירך על פירות האילן בפה\"א יצא משום דמארעא קא רבי כו' וכן כתיב ארץ ממנה יצא לחם כו' וכידוע דגם האדם מן האדמה נוצר ונעשה וגם אדם שנולד מזיווג זו\"נ גשמי' גידולו מן הארץ דוקא כמו שאמרו ארץ מגדלת חכמים שזהו מן ד' נהרות שיוצאים מעדן הארץ כמ\"ש במ\"א באריכות. אך הנה הענין הוא משום דמה שבא הדומם לבסוף בסדר ההשתלשלות מזה מוכרח שבשרש שלפני ההשתל' היה ראשון כנ\"ל ע\"כ גם בהיותו למטה מכולם בסדר השתלשלות יש בו כח ליתן שפע יניקה לצומח שלמעלה הימנו מפני שבאמת למעלה הוא מן הצומח בשרשו למעלה ושם הוא בחי' מקור לצומח כו' וד\"ל. ואמנם היא גופא י\"ל איך יוכל להיות הדומם למעלה מן הצומח בשרשו כנ\"ל וגם אם בשרש הוא למעלה מהצומח הרי למטה הוא בא אחרון שהוא בהעדר ההתפשטות והצמיחה כנ\"ל. והנה להבין זה יש להקדים עוד ענין נפלא שאנו מוצאים בדומם למעלה מצומח וחי ומדבר והוא אשר הכל היה מן העפר בבחי' התחדשות גמורה הנק' חידוש יש מאין ולא יש מיש כידוע ומבואר במ\"א שביסוד המים והרוח ואש לא יוליד חדש ממש רק בעפר יוליד התהוות חדשה לאין שיעור והכל הי' מן העפר היינו כל חלקי דצח\"מ מתהווים מן העפר בהתחדשות מאין ליש דוקא כו' וז\"ש תוצא הארץ תדשא הארץ דארץ אפיקת תולדין כו' ואמנם הנה כ\"ז הוא רק מטעם אחד הנ\"ל בארץ בענין ארץ קדמה דסוף מעשה דוקא עלה כו' ע\"כ נמצא בארץ סוף הכל מכח העצמות שקדם להכל ולכך יש בכחה להוות הכל מאין ליש בלי שיעור כמ\"ש במ\"א. אך עדיין אין זה מובן דסוף מעשה הנ\"ל הוא העולה מסומ\"ע ולא מעצם שהוא הדומם דעפר ואיך העפר בעצמו יתן יניקה ושפע לצומח וחי כו' (ואם מפני שנעוץ תחב\"ס וסוב\"ת אבל לא למעלה מתחלתן ותחלה הוא בחי' הכתר שנק' אין כידוע בענין החכ' מאין כו' א\"כ זהו בא בבחי' התפשטות עכ\"פ מאין והדומם כמו שהוא למטה הוא היפך ההתפשטות כו'). והנה יש להקדים לזה במהות ענין הדומם בהיות ידוע שבדומם יש מבחי' הצומח ונק' צומח שבדומם כמו ההר כו' ומפני שיש בחי' צומח בדומם מזה בא סיבת הצמיחה מן העפר וכך יש בחי' חי ומדבר בהעלם בדומם העפר ולזה ארץ מגדלת חכמים כו' ואמנם הגם שבכ\"א מחלקי דצח\"מ כלול מהכל כי גם בצומח יש מכולם וכן בחי ובמדבר"],[2300680193,"שהרי האדם יש בו בחי' החי והצומח ודומם בדרך התכללות טפל בעיקר והעיקר הוא המדבר וחי טפל בו וצומח טפל יותר ודומם שבו הוא האחרון יותר מ\"מ ערך הדומם שבאדם נבדל מדומם וצומח הגשמי מאחר שהוא כלול בחי ומדבר כו' וכן בחי כלול צומח ודומם אך ניטל ממנו חלק המדבר ובצומח ניטל ממנו החי והמדבר עד הדומם שניטל ממנו גם הצומח ואמנם כלול מצומח וחי ומדבר בהעלם והעלם זה לכאורה היפך העלם דצ\"ח שבמדבר שנעלם כאילו אינו במציאות כטפל כו' ובדומם צומח חי מדבר שבו בהעלם והסתלקות ולא בגילוי. ובאמת נהפוך הוא דהנה הדומם הוא הנק' עצם חומר הפשוט בלתי מורכב כלל וצומח חי מדבר נק' מורכבים ולא פשוטים וידוע ענין עצם חומר הפשוט שהוא הנק' חומר ההיולי שבלתי מורכב אך ורק ממנו יסתעף הכל מהעלם לגילוי (כידוע הדוגמא מעץ מורכב מד' יסודות ארמ\"ע ובשריפתן כלים ג' המורכבים שבו שהן אש ומים רוח ונשאר אפר מיסוד העפר שזהו חומר הפשוט והיולי דכולם כו') ונק' העלם שלו בבחי' העצמיות עיקר הנעלם עד שמה שכלול בו הכל הגם שהוא בהעלם גדול אין זה בחי' העצמית שלו רק בחי' ההתפשטות שבא בהעלם עצמותו אבל הוא עצמו בבחי' העדר ההתפשטות דוקא ואעפ\"י שזהו כדבר והיפוכו אם עצמו ומהותו פשוט בלתי מתפשט ומתחלק בהרכבת זולתו איך יכלול בעצמו דבר זולתו שיתפשט הימנו אך הנה באמת אדרבה היא הנותנת דמשום שהוא עצם פשוט ע\"כ ממנו יסתעף הכל דהיינו שהכל כלולים בו בעצם דוקא וא\"כ התכללות דצ\"ח במדבר היפך מהתכללות צח\"מ בדומם שהרי אין המדבר עצם פשוט והיולי ע\"כ נק' דצ\"ח שבו מורכבים כי גם הוא מורכב משא\"כ בדומם שהוא עצם חומר פשוט ע\"כ צח\"מ הכלולים בו בהעלם היינו בהעלם עצמותו הפשוט כמו כל כח היולי שכלול בו מה שעתיד לצאת ממנו מהעלם לגילוי שאין התכללות זו נק' מורכב כי לא נודע מציאותם כלל בעודנם כלולים בכח עצם ההיולי ולא כהתחכמות שתצא מכח היולי של השכל לגילוי במדות ומחדו\"מ כו' שהמדות ומח' ודיבור מורכבים במציאות בפ\"ע אלא שהן טפלין כו' אלא כמו כח היולי דחכ' שבכחו להשכיל כל מיני שכל שלא נודעו השכלות הללו בכח ההיולי כו' כך הצומח חי מדבר שכלולים בדומם שכלולים בהעלם הרי הן בבחי' כח העצמיות שם ולא במציאות צומח חי מדבר כו' ולפי\"ז בחי' דומם שבדומם הוא העיקר שנק' עצם פשוט בלתי מתפשט כו' ובחי' צומח שבדומם הוא הכח להצמיח שאין זה רק כח הנעלם בעצם הדומם שאינו צומח במציאות וכן החי שבו כו' ומה שבמדבר למעלה במדריגה בדומם הוא למטה במדריגה כי צומח שבמדבר למטה מחי שבו ובדומם צומח שבו למעלה מחי שבו וחי למעלה ממדבר כו' להיות שהצומח שבדומם הוא קרוב יותר לבחי' האין העצמי שבדומם הפשוט רק שבא בהתפשטות מן העצם וגם זה בכח הנעלם שבדומם ואחריו בחי' החי כו' ועד\"ז אמר הכל היה מן העפר דוקא להורות על עיקר התהוות המציאות"],[2300680207,"במקורם העצמי הוא מן הדומם הפשוט משום דנק' עצם פשוט והיולי הנק' חומר הפשוט ע\"כ ממנו דוקא מסתעף הכל מהעלם עצמית לגילוי עיקר מציאות דצח\"מ ואח\"כ נעש' במציאותם בגילוי בבחי' מורכבים כמו במדבר שמורכב מדומם צומח חי כו' וד\"ל (ולכך אנו רואים ביו\"ד מאמרות שהצומח דעשב ועץ קדם לצאת מארץ מחי וחי קודם לאדם כו' משום דארץ הוא עצם הפשוט שהמדבר הכלול בו בהעלם הוא אחרון כו' וד\"ל):\n(ז) <b>והדוגמא</b> מכל זה יובן למעלה בענין ארץ קדמה הנ\"ל. ויש להקדים עוד ענין המבואר במ\"א בענין ב' מדריגות דאין ויש דהיינו שתים שהן ארבע ב' מדריגות באין וב' מדריגות ביש א' אין של היש והב' אין בעצם אמנם ב' מדריגות ביש א' יש שלמטה מאין והב' יש שלמעלה מאין ונק' יש בעצם ודרך כלל הן ג' מדריגות יש ואין ויש ואין זה כולל ב' מדריגות כנ\"ל. וכך הוא בענין נקודה קו שטח אך בנקודה וקו הקו הוא היש של אין דנקודה והשטח יש של אין דקו שהקו הוא בבחינת המשכת יש בגילוי ולא נודע עדיין במהות יש רק בשטח וכך הנקודה הגם שנק' אין לגבי הקו שאינה בבחי' המשכה עדיין אבל עכ\"פ היא בבחי' גילוי קצת כנקודה שמורה על דבר מה רק שהיא בהעדר ההתפשטות כו' אבל קוצו של יו\"ד דנקודה הוא בהעלם למע' מבחי' גילוי דנקודה כו'. ונמצא ד' מדריגות יש כאן והכל אין למעלה מיש קוצו דיו\"ד ויו\"ד אין ויש ואין ויש דקו ושטח וכמו שהיו\"ד נק' גילוי יש עכ\"פ לגבי אין והעלם העצמו' כמ\"ש והחכ' מאין תמצא מאין ליש תמצא כך הקו נק' גילוי יש יותר לגבי היו\"ד שנק' העלם ואין שהוא העדר התפשטות והקו נק' אין והעלם לגבי השטח שהוא בהתפשטות יש לאורך ורוחב כו'. ועד\"ז יובן בד' מדריגות דיש ואין ואין ויש דב' מדריגות דאין אין בעצם הוא כמו קוצו של יו\"ד ואין של היש יו\"ד דחכ' ונק' גם הוא אין בעצם לגבי הקו והקו נק' אין של יש גמור דשטח ולפי\"ז אין בעצם הוא יש בעצם שלמעלה מאין דהיינו למעלה מאין דיש בלבד כו' (ולפי הנ\"ל ב' מדריגות דאין גם אין בעצם למטה מיש העצם להיותו בא בהתפשטות עכ\"פ להיות המשכת אין ליש משא\"כ יש בעצם) והנה ידוע הדמיון מזה למעלה הוא בחי' כתר וחכ' ומדות ומל' שהכתר מקור כל המשכה בבחי' היולי והעלם בלתי נודע והוא כמו קוצו של יו\"ד שהחכ' תמצא ממנו בהעלם ונק' אין בהעלם והוא שכלול בו כל מה שעתיד להתמשך התחכמות בגילוי ומ\"ש תמצא הוא בחי' נקודה דיו\"ד דחכמה שבא מן ההעלם לגילוי הנק' הברקה כידוע רק שהוא כנקודה אחת בלבד בלתי התפשטות עדיין בהשגה כו' ובחי' חכמה שבהעלם הכתר נק' ח\"ס כידוע ונק' אין של היש דנקודה בגילוי מאחר שנק' משפיע נקודת שכל בגילוי עכ\"פ וכמ\"ש במ\"א בענין אל\"ף אאלפך חכ' כו' ומדריגה הב' בח\"ס שסתום לגמרי בלתי בא לעולם להיות מקור לנקודת חכ' הגלויה ונק' פלא כידוע וזהו הנק' אין בעצם ונכלל בכלל בחי' כתר שבכתר שהוא בחי' אור העצם הפשוט ממש ומה שהכתר הוא מקור"],[2300680220,"כל המשכה בהעלם כנ\"ל היינו מבחי' ח\"ס דכתר שנק' אין דיש עכ\"פ. והנה מבחי' נקודה דחכ' נמשך הקו שהן מדות ששרשם בהשגה דבינה שנאמר יקוו המים ובנקודה דחכ' הגם שהיא בגילוי לא נודע עדיין בחינת המשכה למדות כו' ונק' אין ליש דקו שזהו למטה מאין דח\"ס לחכ' דנקודה הנ\"ל ומן הקו דמדות נמשך למל' שהוא הדיבור שבא בהתפשטות אורך ורוחב להגביל אורות המדות והן צירופי אותיות והיינו בחי' שטח דאותיות כו'. והנה בדרך המשכה מלמעלה למטה יו\"ד דחכ' שבאה מהעלם לגילוי עכ\"פ נק' ראשית והוא בחי' מדבר שכלול בו חי וצומח ודומם שהן הקו ושטח חי בבינה וצומח במדות ודומם בדיבור וכידוע דאבא יסד ברתא דשרש הדבור בחכ' ואם אין חכ' בגילוי מן העלם אין דבור ובעוד נקודת דחכ' בלתי התפשטות כלול בה מה שעתיד לבא בהשגה ומדות ודבור ואח\"כ יוצא לגילוי מה שהי' בהעלם בנקודה זו. אך א\"כ למה נק' הדיבור בשם דומם שהוא לשון דממה ושתיקה אם עקרו בחי' התפשטות בגילוי צירופי הדיבור להוציא לאור נקודת דחכ' שבבינה ומדות אלא צ\"ל שיש בדבור למע' מנקודה דחכ' והיינו בבחי' אין הנעלם שבעצם שסתום לעולם שנק' כתר שבכתר או פנימית ח\"ס כנ\"ל שלא באה לבחינת נקודה די' כלל ע\"כ ממילא א\"א לבא בגילוי בדבור כלל ולכך נק' דומם לשון שתיקה וזהו סייג לחכ' שתיקה כידוע דהשתיקה שרשה בהעלם דח\"ס שנק' פלא ולכך נק' סייג שהוא המבדיל להעלים שבלתי יבא בגילוי. ואמנם גם בדומם זה יש בחי' צומח וחי ומדבר והיינו בבחי' כתר דח\"ס שהוא עצם אין הפשוט (או יש בעצם הפשוט) הנה בחי' צומח שבו למעלה מחי כו' והוא מה שמתפשט מעצם הפשוט להיות מקור לחכ' דנקודה הנ\"ל וכידוע בענין מזל ונוצר שמשם שרש יניקה והתפשטות לבא מן ההעלם לגילוי אור דחכ' כשערה הצומח כו' אך נק' צומח שבדומם הפשוט ובחי' החי הוא כמו והחכ' תחיה כו' שהוא נקודה דיו\"ד שכבר בא לגילוי בבינה ומדות עד הדיבור שהוא עיקר בחי' המדבר כידוע בפי' ויהי האדם לנפש חיה לרוח ממללא בדיבור דוקא והוא היפך ענין השתיקה שזהו מצד עצם אור הכתר שלמעלה מבחינת מקור לגילוי חכ' כנ\"ל. ולפי\"ז לכאורה איך יהיה דבר והיפוכו שאיך יבא לגילוי נקודה מהעלם הפשוט שנק' דומם פשוט ועצמי בלתי מתפשט כלל אלא צ\"ל כנ\"ל דאדרבה היא הנותנת דמשום שהוא דומם פשוט הרי הוא העצם הפשוט שיכלול הכל בהעלם העצמו' ויש בכלל מאתיים כו' ע\"כ יוכל להסתעף ממנו הכל כו' וזהו ענין הנ\"ל בחומר הפשוט שכלולים בו בבחי' עצמיו' ולא כהתכללות דצ\"ח במדבר כטפל כו' אלא כמו כל כח היולי בעצם שכולל כל מה שיבא ממנו שאין התכללות זו התכללות דבר מה שהרי אין מציאות ידוע שם עדיין רק מה שיש בכחו כו' ולא כהתחכמות הגלוי' שכוללת ההשגה והמדות ודבור כנ\"ל ביו\"ד דנקוד' חכ' שזהו התכללות דבר מה שנודע שם במציאות רק שנכללים כטפל כו' אבל התכללות בהעלם העצמו' הפשוט הכל הוא בבחי' הכח היולי העצמי עדיין רק מ\"מ מה שיש בכחו להשכיל אעפ\"י שלא יצא לעולם"],[2300680233,"לגילוי נק' התפשטות דעצם הפשוט ממש כמו בחי' פנימית ח\"ס שנק' פלא שנק' תעלומות חכ' הרי זהו בכח ההיולי עדיין ומ\"מ נק' צומח שבדומם כמו כח הצומח שבארץ שבכחו להצמיח הכל ואינו מצמיח כלום עדיין משא\"כ מזל ונוצר שנק' צומח עכ\"פ וכמו גידול החכ' באדם ברוב ימים כו' משא\"כ טרם שבא גידול זה לגילוי הגם שהיה כלול בהעלם כח היולי דחכ' בקטנותו כמו בוצין בוצין כידוע זהו שנק' צומח הכלול בעצם הדומם וכמו\"כ חי ומדבר וזה למעלה מזה (וכמו במשה שהי' כבד פה בדבור מצד שרשו בפנימי' ח\"ס דוקא הי' כלול בהעלם העצמות כח הדבור שנק' פה וכמ\"ש מי שם פה לאדם פי' מהיכן עצם כח היולי דפה דאדם מדבר שנק' רוח ממללא הלא אין זה תלוי בחכ' דיו\"ד רק בכתר שבכתר שנק' אנכי). ובכ\"ז מובן עכ\"פ בסדר מדריגות דצח\"מ שסידורן הפוך מעליון לתחתון דכמו שהן בבחי' אדם דחכ' דצ\"ח כלולים בו כטפל כו' והדומם אחרון שהן אותיות הדיבור ובלמעלה מבחי' אדם שהוא כתר וח\"ס שבו בכללותו בחי' הדומם למעלה שהוא שרש השתיקה שבפה כנ\"ל וזהו מ\"ש בזוהר קול דממה דקה תמן קאתי כו' וכידוע בענין אד' שפתי בצלותא בלחש כו' והיינו העצמו' הפשוט ונק' דומם ע\"ש בחי' העדר התפשטות ומה שכלול בעצם בחי' התפשטות ג\"כ נק' צומח שבדומם ומשם יש שרש לצומח דח\"ס לבא לגילוי נקודה ע\"י מזל כו' כמו מזל מחכים והוא ע\"י בקיעה כו' עד בחי' מדבר דחכ' הוא אחרון וכמו בסדר המאמרו' דתדשא הארץ קודם לתוצא הארץ נפש חיה כו' ואדם אחרון כנ\"ל וזהו אחור וקדם צרתני כו' וד\"ל. ועם כל הנ\"ל יובן עכ\"פ ענין הנ\"ל שבבחי' או\"ח דוקא שעולה לקדמותו שלפני ההשתלשלות דחכ' כו' כח הדומם למעלה מכולם ע\"כ יובן שאין זה פלא כלל מה שאנו רואים למטה שהצומח יצמח מן הדומם העפר ויקבל ממנו יניקה כנ\"ל באריכות משום דבשרש הדצח\"מ כמו שהן למעלה בבחי' הכתר הרי בחי' צומח מקבל באמת מהדומם דהיינו ענין התכללות דצומח שבדומם הפשוט ההיולי כנ\"ל וד\"ל:\n(ח) <b>ומעתה</b> יובן ענין הנ\"ל בבנין בהמ\"ק דשלמה שהיה מאבנים ועפר כו' בהיות שזהו ההפרש בכלל בין משכן דמשה לבהמ\"ק של שלמה שהי' בדוגמא דלעתיד דמשכן דמשה הי' כפי סדר ההשתלשלות בבחי' או\"י מלמעלה למטה דוקא שהוא שם הוי' יו\"ד חכ' ה' בינה ו' מדות ה' דיבור שהוא הדומם האחרון כמו דצח\"מ למטה דמדבר קודם לכולן ודומם אחרון כנ\"ל וזה הי' מפני שעתה בחכ' אתברירו דהיינו אדם בחי' מדבר והן הארון ולוחות שהיו במשכן שניתן ע\"י משה שהוא שם מ\"ה כמ\"ש ונחנו מ\"ה (ואעפ\"י שהי' מפנימית ח\"ס כנ\"ל מ\"מ ירד ונתצמצם למטה בלשון יפה דתושב\"כ ותושבע\"פ כידוע) וזהו שהי' סדר מעשה הקמת המשכן יריעות עזים מלמעלה וקרשים ועצי שטים לדפנות ועפר הי' בקרקע המשכן וכמ\"ש בזהר דיריעות שש משזר כו' כללי' ו\"ק דבינה בבחי' מקיפים והי' מצמר החי כו' והדפנות היו מבחינת צומח דעצי שטים עומדים שהן בחינת המדות שנק' צומח שמקבל מבינה ובחי' מקיפים דבינה עודפי'"],[2300680245,"על הקרשים מזה ומזה שהן היריעות שהיו מכסים מלמעלה וכמו נוטה שמים כיריעה בבחי' מקיפים כו' (והענין הוא כמו מ\"ד שמים קדמו הנ\"ל דקדם התענוג להשפיע כמו עצם הטוב וכנ\"ל וע\"ד הנ\"ל באין דיש דחכ' בבינה כו') והיינו שהי' עיקר הכח ועוז ליחודי' עליונים שנעשי' ע\"י הקרבנות מבחי' המקיפים הללו שנק' אהל המשכן דלכך נק' אוהל מועד כו' ולכך היו עודפים גם על הקרשים כו' כידוע דהקרשים היו במספר מכוון להיות עומדים בבחי' משפיעים למטה שהן האדנים שהי' בהן בית קיבול חללי לקבל הקרשים וכידוע דזהו שם אדנ\"י שמקבל מז\"א שנק' אדון כמו מלפני אדון חולי. אך כדי שיהי' יחוד זה דקרשים באדנים מתקיי' ועושה פירות כו' הרי זה הי' ענין העודף דיריעות לכסות עליהם שיוכלו להתייחד כו' וכידוע דבכל יחוד משפיע ומקבל יש עזר עליון מבחינת המקיפים כו' (וכמ\"ש ויאמר פרו ורבו כו' וארז\"ל איש ואשה זכו שכינה שרויה ביניהם כו'). אך הנה בחי' הדומם הי' אחרון במשכן דמשה והוא עפר שהי' בקרקע המשכן שלא הי' מרוצף בקרשים רק עפר ממש כו' (וכמו ה' אחרונה דהוי' עולם הדבור שהן אותיות בחי' דומם נק' עפר שבקרקע המשכן העליון והמדות ששופעים בדבור העליון נק' בחי' צומח והן בחי' הדפנות שהיו המשפיעים באדני הקרשים כמו עד\"מ דברים שיוצאים מן הלב יש בו חיות רב ואם אין הלב נמשך בדבור אין לדבור חיות כלל אלא הוא כדומם ממש שניטל ממנו חלק החי וגם חלק הצומח כו' שהוא אחרון כנ\"ל). וכ\"ז במשכן דמשה שהי' בו הארון דאורייתא מח\"ע נפקת לברר בירורים דעה\"ד טו\"ר שנק' נובלות חכ' שלמעלה (כמו יו\"ד נקודה דחכ' שיצא לגילוי ממזל ונוצר). אבל בהמ\"ק דשלמה הי' למעלה מסדר ההשתלשלות דאבי\"ע שהן כמו דצח\"מ למטה (שהוא ד' אותיות דהוי') שהרי הי' בו בחי' דומם למעלה מכולן והוא המעזיבה שע\"ג הקורות דהיינו במקום יריעות דמשכן כו' וכנ\"ל באריכות. והענין הוא שהי' בנין זה כדוגמא דביהמ\"ק דלעתיד להיות דלעתיד יהי' בחי' תשלום כל הבירורים דרפ\"ח כו' ויהי' בבחי' או\"ח לקדמותו כמו שהי' לפני סדר ההשתלשלות דאבי\"ע דהיינו כמו שבעצמות הפשוט הי' הכל בהתכללות בהעלם עצמי (כנ\"ל באריכות) ששם ודאי ארץ קדמה לשמים דהיינו ענין סוף מעשה עלה במח' תחלה הנ\"ל שעלה לפני תחלת המח' והוא בחי' דומם שבשרשו הוא עצמי ופשוט בלתי התפשטות כלל וכלל (שהוא בחי' כתר שבכתר כנ\"ל או פנימית ח\"ס כידוע דפנימית אבא הוא פנימי' ע\"י והיינו עצם האין כמו שהוא או עצם יש האמיתי) וז\"ש א\"ח עט\"ב דארץ דלמטה שנק' א\"ח תהי' עטרת לבעלה שהוא החכ' ומדות כו'. (והיינו דוקא בכתר שבכתר שהוא דומם שבדומם) (וכמ\"ש וזכרתי את בריתי כו' והארץ אזכור) ולכך הי' הדומם למעלה מהכל בבהמ\"ק דשלמה והדפנות היו ג\"כ מאבנים ועפר ולא הי' בחי' צומח כלל בבנין זה וכמ\"ש והבית בהבנותו אבן שלימה כו' (דאבן אינו מצמיח כלום כו'. וז\"ש אבן מאסו הבונים היתה כו') וגם הקורות שהיו מעצי ארזים היו רק בבחי' טפל ומשמש להחזיק המעזיבה בלבד שהיתה"],[2300680257,"מבחי' דומם והוא לפי שבשרש הדצח\"מ כמו שהן למעלה מן ההשתלשלות הרי באמת הצומח מקבל מן הדומם (וכנ\"ל באריכות בענין התכללות צומח שבבחי' דומם העצם ההיולי ופשוט כו') ואין זה פלא כלל אשר ארזים בחי' צומח יהיו משמשים לקבל עליהם המעזיבה הדומם כמו שאין זה פלא מה שהצומח יצמח מן הדומם למטה כאילן ופירותיו שיונקים מן הארץ כנ\"ל והכל מטעם הנ\"ל. וכמו\"כ הטעם דהכל הי' מן העפר דוקא כו' וד\"ל. וזהו קורות בתינו ארזים כו' פי' קורות בתינו דבהמ\"ק דשלמה דארזים לשבח קאמר דמה שהי' במשכן דמשה דפנות מעצי ארזים בחי' משפיעים כנ\"ל בבתינו הן רק בחי' קורות להחזיק עליהם המעזיבה שנק' תמכין בלבד. והענין הוא דמשכן דמשה שנק' אהל מועד היינו התו' הנגלית לנו שבאה מהעלם עצמו' ח\"ס שבפנימית הכתר לגילוי במדות כשר פסול כו' לברר עה\"ד טו\"ר כנ\"ל לכך נק' עצי שטים עומדים כידוע דשרש המדות שלמטה מן השכל הוא בחכ' עצמה ועד למעלה גם במדות שבמקור החכ' שהוא העונג הנמשך ומורגש בחו\"ב תרין ריעין כו' ונק' ארז אשר בלבנון דלובן העונג העליון שבא במדות שבתענוג דחכ' כו' (כאהבה בתענוגים שבנקודת חכ' מאין תמצא לגילוי כו'). (וכמ\"ש אכלתי יערי עם דבשי ייני עם חלבי והכל מדבר בתו' שבאה מההעלם העצמו'). אבל בהמ\"ק דשלמה שא\"ח עט\"ב כנ\"ל היה גם מדות דארזים רק קורות בחי' תמכין דאורייתא כו' כמו תמכין דאורייתא למטה שאינם רק מחזיקים לומדי תורה כך מדות עליונות דעונג המורגש בחכ' אינם רק בחי' תמכין לאורייתא דח\"ע העצמיית כמו שהוא בעצמות ממש (כמו אור צח כו' אוכם כו' דלגבי העצמו' נק' המשפיע מקבל איידי דטריד כו') וכמו שאנו רואים למטה בעונג המדות דחכ' שאינם אלא כמחזיקים לגופו של עצם כח היולי דחכ' שיהי' מתקיים וחזק במעמדו לבד וכמו ובלב כל חכם לב דוקא נתתי חכ' ובלא לב לא יקנה חכ' וכמו לקנות חכ' ולב אין כו' (בל\"א דער קוועל אין שכל במורגש מחזק לעצם כו') וזהו מן השבח הגדול ששיבח כאן דכ\"כ גדלה למעלת בתינו עד דגם בחי' התמכין דאורייתא הן מן הארזים ואינם עומדים זקופי' מה שבמשכן דמשה היו עומדים זקופים להשפיע כו' והיינו משום דבימי שלמה הי' עליית המל' ח\"ת בח\"ע העצמית דוקא כמ\"ש בזהר דהוה קיימא סיהרא באשלמותא כמ\"ש וישב שלמה על כסא ה' כו' והן ע\"ס דמל' בשלימותן בכתר בבחי' כתר שבכתר כנ\"ל באריכות וד\"ל (אך באמת פי' הפשוט דקורות בתינו ארזים שלא הי' מעזיבה דעפר עליהם כי קורות שהוא בלשון המקרא היינו שכל שטח שהי' הקורה מארזים שהוא דבר חשוב ביותר ואעפ\"י שלעתיד נאמרו כל דברי שה\"ש שצומח יהי' למטה מן הדומם מטעם הנ\"ל אך בענין הקורות שהן בחי' מקיפים במקום יריעות דמשכן משה כנ\"ל ארזים חשובים יותר לפי שארז גידולו מן הארץ תכלית הגידול כמו תכלית גידול דחכ' בזקן שקנה חכ' בהגיעו לתכלית חכמה הנעלמה בעצמי' כמו וה' נתן חכמה לשלמה ח\"ת ע\"כ וידבר כו' עד הארז כו' ולא יותר דהיינו עד שרשו בעצמו' ח\"ס"],[2300680269,"כנ\"ל. וזהו ענין הקורות שהן עשוים להחזיק לדפנות מכל צד ומעלה ומטה יחד וז\"ש ויורהו ה' עץ כו' עץ החיים למחזיקים בה דוקא שהיא ח\"ע העצמית שמחזקת הכל למעלה ולמטה ולד' סטרין יחד. וזהו קורות בתינו ארזים מעה\"ח שיריעות דמשכן היו רק בדרך לבוש והעלם שנא' עוטה אור כשלמה כו' והיינו בחי' צומח שבדומם היולי הנ\"ל שמגיע לעצם הפשוט דכל התפשטות כו' מגיע בעצם כו' וכידוע דאא\"ס למעלה עד כו' ולמטה עד אין כו' וזהו כמו הארז שתכלית גידול צומח שבדומם הי' מונח בבחי' דומם כאבנים לקורה להחזיק הדפנות בקרקע שהי' מאבן שעיקר המקור לעתיד וד\"ל:\n(ט) <b>וזהו</b> ויגש אליו יהודה כו'. דהנה ידוע בזהר עמ\"ש כי הנה המלכים נועדו עברו יחדיו כו' שזהו בחי' יסוד ומל' שהן יוסף ויהודה ובכלל היינו בחי' זו\"נ דאצי'. וזהו ויגש אליו יהודה דוקא שהוא בחי' המל' שנגש ונתקרב להתייחד ביוסף שהוא בחי' יסוד ז\"א בחי' צ\"ע כו'. אך הנה תחלה י\"ל שרש ענין ההפטרה דפרשה זו (ביחזקאל ל\"ז) ויהי דבר ה' כו' קח לך עץ אחד וכתוב עליו ליהודה ולבני ישראל חבריו ולקח עץ א' וכתוב עליו ליוסף עץ אפרים וכל בנ\"י חבריו וקרב אותם אחד אל אחד והיו לאחדים בידך וכאשר יאמרו אליך מה אלה לך דבר אליהם כה אמר ה' הנה אני לוקח את עץ יוסף ושבטי ישראל חבריו ונתתי אותם עליו את עץ יהודה ועשיתם לעץ אחד והיו אחד בידי כו' עד הנה אני לוקח את בנ\"י מבין הגוים כו' ועשיתי אותם לגוי א' בארץ כו' ומלך א' יהי' לכולם כו' עד ועבדי דוד מלך עליהם ורועה אחד יהי' לכולם כו' עד ודוד עבדי נשיא להם לעולם כו'. והנה לכאורה סמיכות ענין זה דעץ יוסף ועץ יהודה לפרשה זאת דויגש אליו יהודה הוא בהיפוך גמור דבפ' זאת משמע דיהודה הוא למטה הרבה מיוסף וע\"כ נגש אליו יהודה בהכנעה גדולה ואמר לו בי אדוני ידבר נא עבדך כו' ואל יחר אפך בעבדך כו' ובענין העצים דיוסף ויהודה הרי אמר בתחלה קח לך עץ אחד וכתוב עליו ליהודה כו' ואח\"כ ליוסף עץ אפרים כו' והיו לאחדים עכ\"פ לא שיוסף הוא למע' מיהודה ולא עוד אלא שבסוף אמר הנה אני לוקח את עץ יוסף כו' ונתתי אותם עליו את עץ יהודה כו' שיתן את עץ יהודה על עץ יוסף דמשמע מזה שעץ יהודה יהי' למעלה מעץ יוסף וכמו שמסיים ועבדי דוד שהוא מיהודה מלך על כולם ודוד עבדי נשיא להם לעולם שהוא מלך המשיח כידוע. אך הנה כ\"ז יובן עפ\"י כל הנ\"ל בענין קורות בתינו ארזים כו' בענין ב' מדריגות דצומח ודומם דעכשיו בחי' הצומח למעלה מבחי' הדומם שהצומח הוא בחי' כח ההתפשטות דצמיחה בארץ ברב תבואות וכל צמח השדה בפירות ועשבים ובחינת הדומם הוא המקבל שבו יצמח הכל מכח הצומח והדומם הוא עפר הארץ שאין בו מצד עצמו שום התפשטות כלל (כענין אסתר קרקע עולם כו') רק מזרע צומח שנזרע בארץ יצמיח מן הארץ הכל כו'. וכך יובן ברוחניות למעלה בענין שפע האלקית דבחי' יסוד יוסף צ\"ע הוא בחי' המשפיע הכל במל'"],[2300680281,"כמו בחי' הצומח שמצמיח הכל ובחי' המל' בחי' מקבל הוא כמו בחי' דומם וכידוע דבחי' יסוד נק' עץ עשה פרי ונק' עץ השדה וכמ\"ש והי' כעץ שתול כו' אשר פריו יתן כו' ולכך נק' יוסף לשון להבא שתמיד יוסיף אור ושפע כצומח שצומח וגדל בתמידות בלי שיעור כלל וכלל וזהו ענין יוסף לשון תוס' תמידית וכמ\"ש יוסף ה' לי בן אחר שהוא בנימין צ\"ת כו' כמ\"ש במ\"א. וזהו כענין יוסיף דעת כו' שגם בשכל וחכ' מרבה השפע בתוס' בחידוש בתמידות בלי הפסק כלל כמו מעיין המתגבר כו' וד\"ל. וזהו שהי' נק' בן פורת יוסף כו' שמפרה ומרבה השפע תמיד וכמו שמצמיח רב תבואות ופירות לאין שיעור במל' שהוא בחי' המקבל וכמ\"ש הטעם לקריאת שם אפרים (שהוא עץ אפרים שהוא עיקר עץ יוסף) כי הפרני אלקים בארץ כו' (וכידוע שבדרך כלל בכללות כל ההשתלשלות הן כלולים בד' מדריגות דדצח\"מ שהן ד' יסודות ארמ\"ע שהוא לנגד ד' אותיות דשם הוי' יו\"ד באצי' ה\"א בבריאה וי\"ו ביצי' ה\"א בעשי' והיינו ענין ד' מדריגות דארמ\"ע ודצח\"מ אש בבחי' אצי' רוח בבריאה ומים ביצירה ועפר בעשיה וכן מדבר דאדם בבחי' אצי' וחי בבריאה וצומח ביצי' ודומם בעשי' כו'. וכמו\"כ יש ד' מדריגות הללו דארמ\"ע ודצח\"מ באצי' עצמו וגם לפני האצי' כו' והוא ד' אותיות דהוי' דאצי' עצמו כו' ובחי' יו\"ד דחכ' בחי' מדבר וה\"א בינה בחי' חי וז\"א בחי' צומח ומל' דאצי' בחי' דומם כו' וכמו אבן מאסו הבונים כו' שהוא בחי' מל' שנק' אבן א' ב\"ן כו' ולפעמי' נק' עפר וארץ כמ\"ש תוציא הארץ ארץ עילאה ונק' עפר שבקרקע המשכן העליון כו' וכתי' הכל הי' מן העפר כו' ובחי' ז\"א נק' עצי הקרשים דמשכן כמו עצי שטים כו' שמדות דז\"א הוא בחי' עץ כמ\"ש כי האדם עץ השדה והוא בחי' צומח כעץ עשה פרי כו' כנ\"ל ופרטי ההתחלקות דמדות דז\"א שהוא צומח דעץ הן נעשו בחי' קרשי המשכן למעלה להאיר במל' שהן בחי' אדני הקרשים דמשכן מדומם דכסף כו' וד\"ל (וכמו עד\"מ מן המדות שבלב שהן בחי' צומח כעץ השדה בקטנות וגדלות כאזוב שבקיר עד הארז שבלבנון שהן מדות שברצון ותענוג שלמעלה מן השכל כנ\"ל ומן המדות שבלב נמשך לדבור שהן רק בחי' דומם שהאותיות הן בחי' דומם מבלי נוסף בהן דבר כדומם שאין בו התפשטות כלל רק מה שיאיר באותיות הדבור מבחי' צומח דמדות וחי דבינה ומדבר דחכ' שנק' עי\"ז רוח ממללא כו' וד\"ל). ובדרך כללות יותר דהיינו מעצמות המאציל עד סוף העשי' מבחי' המל' שכוללת בי\"ע הוא בבחי' עשיה וז\"א בבחי' יצי' ואו\"א בבריאה דאצי' וע\"י וא\"א באצי' דאצי' והן ד' מדריגות דצח\"מ ובכללות יותר נק' א\"ק אדם דבריאה וע\"י וא\"א אדם דיצי' ואו\"א וזו\"נ אדם דעשי' כו' שהן דצח\"מ שמל' דא\"ס בחי' מדבר וא\"ק בחי' חי כו' וכך גם לפני הצמצום הראשון יש בחי' דצח\"מ ומל' דא\"ס בחי' דומם כמו בחי' אותיות דטה\"ע כו'):\n(י) <b>וזהו</b> ויגש אליו יהודה שהוא בחי' המל' שנגש ונתקרב לבחי' צ\"ע יסוד ז\"א דהיינו כערך בחי' הדומם לגבי בחי' הצומח לקבל ממנו שפע אור הזרוע לצ\"ע כו'. והגשה זו היא בחי' העלאת מ\"ן דמל' כו' וזהו למהוי אחד"],[2300680293,"באחד יחו\"ע מאיר ביחו\"ת דמל' כמו שיהי' לע\"ל הוי' אחד ושמו אחד וזה נעשה ע\"י בחי' הגשה זו דיהודה בהעלאת מ\"ן כמ\"ש ידבר נא עבדך דבר באזני אדוני ואל יחר אפך כו' שלא ימשיך בחי' גבורות קשות ביותר (כמשי\"ת) וזהו ענין ההפטרה על פ' זאת קח לך עץ אחד כו' שזהו בחי' המל' דיהודה וישראל חביריו שכולל כתר כהונה וכתר מל' (ואעפ\"י שהמל' בבחי' דומם נק' עץ יהודה להיות בבחי' צומח שבדומם שהרי גם האילן מארעא קא רבי וע\"כ בירך על פרי העץ בפה\"א יצא כו' שהוא מצד השרשים דאילן שיונקים בארץ שמשם עיקר חיות האילן ופירותיו) ולקח עץ א' וכתוב עליו ליוסף כו' שהוא בחי' צ\"ע בחי' יסוד (וזהו שכתוב לכל בנ\"י חביריו שהן יו\"ד השבטים לבד יהודה ובנימין שהי' מולכים עליהם מלכי ישראל הכל משבט אפרים כידוע) וקרב אותם כו' והיו לאחדים כו' עד ועשיתם לעץ אחד דהיינו למהוי אחד באחד והוא ע\"י חיבור ויחוד דיהודה ביוסף בהעלאת מ\"ן תחלה כי עכשיו בחי' יוסף הוא המשפיע למל' דיהודה וכמו כל מקבל שצריך להעלות מ\"ן למשפיע כמ\"ש ואל אישך כו' וכמו שהי' יוסף בחי' צ\"ע דאצי' השליט על כל הארץ ומשביר בר כו' כך הי' יוסף העליון מאיר במלכי ישראל שהיו משבט אפרים שכולל כל יו\"ד השבטים ומלך יהודה לא הי' רק על שבט יהודה ובנימין כו' וז\"ש יוסף על אפרים כי הפרני אלקים בארץ שהוא בכל א\"י ביו\"ד השבטים כו' להיותו עיקר ומקור כללי המשפיע לכנ\"י שהוא בחי' המל' וכנ\"ל בפי' בן פורת יוסף כו' וזהו ויגש אליו יהודה במס\"נ על בחי' צ\"ת שהוא בנימין שבזה דוקא הי' יכול לעלות ולהתייחד ביוסף בחי' צ\"ע עד שלא הי' יכול יוסף להתאפק כו' עד שנתוודע יוסף אל אחיו כו' שכ\"ז הי' הסיבה רק ממס\"נ דיהודה על בנימין צ\"ת דוקא וד\"ל. אך הנה כל זה עכשיו דוקא אבל לע\"ל הנה נהפוך הוא שבחי' יהודה יהי' במעלה ומדריג' גבוה הרבה יותר מיוסף שבחי' המל' דיהודה יעלה למע' מבחי' יסוד צ\"ע וכמו שיתעלה בחי' הדומם לע\"ל למעלה מבחי' הצומח (שהרי כל מה שיש בכח הצומח להצמיח זהו בא מן הדומם דוקא ונק' צומח שבדומם דהיינו רק חלק כח ההתפשטות שבדומם שהוא למטה מן הדומם עצמו שהוא בחי' העצם ממש כמו שהוא שלמעלה מן ההתפשטות דצומח שבו כו' וכענין סייג לחכ' שתיקה שנק' דומם כאשר הוא למעלה מהתפשטות אור דחכ' מאין ליש כו' והוא בחי' כתר שבכתר שלמעלה מצומח דח\"ס כנ\"ל) וזהו שבהפטרה זו אמר תחלה עץ יהודה כו' וקרב אותם אחד אל אחד כו' והיו לאחדים בידך שהוא מלמעלה למטה דאו\"י דיחו\"ע דמשפיע נמשך למל' יחו\"ת למהוי אחד באחד כנ\"ל שזהו מדבר עכשיו שיוסף למעלה מיהודה אבל מ\"ש עוד הנה אני לוקח עץ יוסף ושבטי ישראל חביריו ונתתי אותם עליו את עץ יהודה ועשיתם לעץ אחד והי' אחד בידי דוקא זהו מדבר בעליית המל' דעץ יהודה יהיו למעלה על עץ יוסף וכמו שמסיים הדבר ועבדי דוד מלך כו' ודוד עבדי נשיא להם לעולם בנצחי' דא\"ס דהיינו אחר שיהי' יחוד וחיבור דיהודה ויוסף בחי'"],[2300680304,"יסוד ומל' שנגשו להתייחד ביחו\"ע ויחו\"ת והיו לאחדים ממש בזמן הגלות אח\"כ לע\"ל ישאר הכל ליהודה שיעלה למעלה במדריגה על יוסף צ\"ע כמ\"ש א\"ח עט\"ב דבחי' ב\"ן יעלה למעלה מהמשפיע דשם מ\"ה כו' (כנ\"ל בפ' מקץ באריכות כו') וכמבואר למעלה בענין קורות בתינו ארזים כו' בענין אבנים ועפר שבבנין שלמה כו' עד שיגבר יהודה להיות שליט על הכל במעלה ומדריגה כמ\"ש היתה לראש פינה כו'. והוא מ\"ש ודוד עבדי נשיא להם לעולם כענין דוד מלך ישראל חי וקיים כמ\"ש חיים נתתי לו בנצחית דא\"ס כו' וכן אמר עד דוד הגדיל כו' וד\"ל. ובכ\"ז יובן בתוס' ביאור בטעם ענין קריאת ההפטרה זו דקח לך עץ אחד כו' על פרשה זו דויגש אליו יהודה דוקא לפי שענין אחד הם וכל ענין הפרשה זאת דויגש סובב והולך ע\"ד הנ\"ל ממש שאמר בהפטרה זו בעץ יהודה ועץ יוסף בתחלה ובסוף דהנה בתחלה אמר כאן ויגש אליו יהודה דהיינו בהכנעה ותחנונים ודיבר במס\"נ ממש על אודות בנימין צ\"ת שאמר יוסף שיהי' לו עבד והם יעלו לשלום אל אביהם שא\"א להם לעלות לאביהם בלא בנימין צ\"ת שנפשו קשורה בנפשו כו' עד ישב נא עבדך תחת הנער כו' שהוא העלאת מ\"ן דמל' ליסוד והיו לאחדים ממש (כמ\"ש בהפטרה וקרב אותם אחד אל אחד והיו לאחדים בידך כו') עד ולא יכול יוסף להתאפק כו' ולא עמד איש אתו בהתוודע יוסף אל אחיו שזהו בחי' גילוי יחו\"ע ביחו\"ת למהוי אחד באחד ממש כנ\"ל ואמנם באמת עיקר ענין ההגשה דיהודה הי' בתחלה בהעלאת מ\"ן ומס\"נ לגבי יוסף רק כדי שיהי' נשאר הכל לבחי' המל' שתעלה לע\"ל למעלה מבחי' יסוד כמ\"ש א\"ח עט\"ב כו' (וכמ\"ש בהפטרה ונתתי אותם עליו את עץ יהודה כו') כי הגשה זאת דיהודה הי' כדי ליכלל לבחי' יוסף ביהודה אח\"כ (וז\"ש ידבר נא עבדך דבר כו' שהוא דבר מל' דיהודה שיהי' לע\"ל במשיח כו') וכמ\"ש ודוד עבדי נשיא להם כו' וראי' לזה ממה שמיד בכלות דברי יהודה לא יכול יוסף להתאפק ונתוודע אל אחיו דהיינו הגם שנכלל ונתאחד יוסף במדריגת יהודה ואחיו כהתאחדות משפיע במקבל כמו ע\"כ יעזוב איש כו' ודבק באשתו כו' אבל זהו כדי שאח\"כ יתעלה יהודה למעלה ממנו וישאר הכל ליהודה שהוא בחי' המל' וכמ\"ש אבן מאסו הבונים שהוא בחי' ב\"ן היתה לראש פינה עט\"ב כו' וד\"ל וכמבואר (בענין קורות בתינו ארזים כו') בעליית בחי' הדומם למעלה מן הצומח שהרי בבנין בהמ\"ק דלע\"ל יהי' כמו בנין בהמ\"ק דשלמה שהיו כולם מאבנים ועפר בחינת דומם דוקא ומה שהי' במשכן דמשה עצי שטים עומדים דקרשים זקופים באדנים בבחי' משפיע למל' הרי בבהמ\"ק דשלמה רק קורות להחזיק המעזיבה דעפר (שהוא בחי' תמכין דאורייתא כנ\"ל) וז\"ש אב\"ן כו' פי' בחי' הדומם שאבן ועפר הוא המעזיבה שעל הקורות שיהי' בביהמ\"ק דלע\"ל במקום היריעות במשכן דמשה שז\"ש היתה לראש פינה בבחי' מקיפים עליונים דיריעות ולמעלה מהם (לפי שבחי' הדומם למעלה מן הצומח כמו שהוא בשרשו למעלה דדומם תחלה"],[2300680315,"ואח\"כ צומח ואח\"כ חי ומדבר כו' וראיה ממה שהכל הי' מן העפר וכנ\"ל בענין ארץ קדמה לשמים כו') והארזים שהן בחי' צומח הי' רק קורות להחזיק המעזיבה בבחי' תמכין לבד כו' מה שבמשכן דמשה הי' דפנות שהן הקרשים הזקופים באדנים שנק' משפיע שהוא שפע המדות במל' כנ\"ל וד\"ל:\n(יא) <b>אך</b> הנה עדיין י\"ל בשרש ועיקר כל הנ\"ל מאיזה טעם יתעלה בחי' יהודה למעלה מיוסף צ\"ע כו' וגם בטעם ענין אבן מאסו כו' שיהיו עלי' בחי' הדומם למעלה מבחי' הצומח וע\"כ לא יהיו יריעות בביהמ\"ק דלע\"ל רק מעזיבה וקורות תחתיהן כו' כנ\"ל ואם מטעם המבואר למעלה בענין ארץ קדמה לשמים במח\"ת כו' היא גופא י\"ל מאיז' טעם ארץ קדמה כו' וד\"ל. והנה יש להקדים תחלה לזה ענין אחד הידוע והוא בב' מדריגות דיראה יר\"ת ויראה עילאה שהן ב' מדריגות דחכ' ח\"ת וח\"ע וכמ\"ש הן יראת ה' היא חכ' כו' וכתיב ראשית חכ' יראת ה' דח\"ת הוא יראה תתאה וח\"ע הוא יר\"ע ושניהם ענין אחד ממש והיינו ב' מדריגות שבבחי' הביטול א' ביטול היש לאין זהו יר\"ת וח\"ת והב' ביטול העצמי דבחי' אין ממש שנק' מ\"ה בעצם כו' זהו בחי' יר\"ע וח\"ע שע\"ז אמר הן יראת ה' היא חכ' כו'. ולהבין ביאור זה הנה יש להקדים תחלה ענין ושרש אהוי\"ר שנק' דו\"ר כמ\"ש ברע\"מ שהן ד' מדריגות דו\"ר רו\"ד שנמצא יר\"ת דחילו תתאה ויר\"ע דחילו עילאה וב' רחימות באמצען רחימו תתאה ורחימו עילאה כו'. ויש להבין תחלה ענין דו\"ר תתאין שהן אהוי\"ר שידוע דאהוי\"ר נק' ב\"ן וב\"ת שהיראה נק' ב\"ת והאהבה נק' ב\"ן שהן בחי' דכר ונוק' משפיע ומקבל כו'. וביאור הענין ידוע שהיראה אינה רק בחי' ביטול חיצוני לבטל רצונו בעול ושפלות והכנעה גדולה שהוא בבחי' ריחוק בעצמו עד שאינו אלא בחי' מקבל מן המשפיע להיות שיכול לקבל בנפשו גילוי אור האלקי ע\"י ביטול היש וגסות שלו לאין האלקי ביראה ושפלות וריחוק כמו וירא העם כו' ויעמדו מרחוק כו' וכן מרחוק ה' נראה לי כו' אך הנה מדריגות האהבה הוא בבחי' הקירוב דוקא שהרי מהות האהבה הוא בבחי' הדביקות האלקי בקירוב ודיבוק דוקא שהוא בבחי' הפנימי' דוקא כמו לך אמר לבי כו' את פניך הוי' אבקש כו' וכן צמאה לך נפשי כו' וזהו הגורם המשכות שפע האה' האלקית בקירוב ופנימי' דוקא כאברהם אוהבי שהמשיך באהבתו כמים הפנים אל פנים כו' אור אה' עליונה מלמעלה למטה דרוח אייתי רוח כו' וזהו שהאה' נק' בחי' משפיע שמשפיע לאדם אה' עליונה האלקי' ונק' בחי' ב\"ן בחי' דכר כמו כי זכר חסדו כו' (וזהו רחימו תתאה שנולד מרחימו עילאה שהוא בחי' בינה והוא אהבה שבתענוג שבשכל והשגה אלקי' עצמו שהוא ה' ראשונה דשם הוי') וזהו והחיות רו\"ש רצוא בבחי' האהבה והקירוב והדיבוק שזהו בחי' משפיע ליראה שהוא בחי' שוב שעומד מרחוק בשפלות שאחר בחי' הרצוא שוב כמו וינועו ויעמדו מרחוק כו' ואם לא האה' בקירוב תחלה אין בחי' שוב דיראה שהוא בחי' מקבל שנק' בת לשון נוק' (כמ\"ש במ\"א על מ\"ש אשרי איש ירא כו' איש אש יו\"ד"],[2300680326,"דאה' שמשפיע לאשה אש ה' כי מאיש לוקחה כו') וכמו\"כ אחרי בחי' השוב דיראה רצוא דאה' וכמ\"ש עבדו את ה' ביראה תחלה ביראה ואח\"כ וגילו ברעדה הגילה הוא החדוה בקרבת אלקים ובמקום גילה זו תהא רעדה בבחי' שוב דיראה כמו וינועו כו' ונמצא עכ\"פ היראה בחי' מקבל נק' בת והאה' בחי' משפיע כמו שמדות שבלב נק' צומח בהתפשטות ונק' עצי שטים דקרשי המשכן שעומדים זקופים ומשפיעים למל' שהוא בחי' היראה בחלל דאדנים שמקבלי' הקרשים כו' כנ\"ל. וזהו ג\"כ ענין ויגש אליו יהודה שהוא בחי' היראה דמל' בבחי' ביטול ושפלות לגבי יוסף שהוא בחי' המשפיע דאה' כו' שנק' בן כמ\"ש בו בן פורת כו' והיינו כמו שעכשיו בחי' צומח למעלה מבחי' דומם כך האה' שהיא בבחי' צומח למעלה מבחי' היראה שהיא מבחי' דומם בביטול ושפלות כנ\"ל וד\"ל. אך הנה לע\"ל כתיב א\"ח עט\"ב שבחי' היראה שהיא בחי' מקבל עכשיו תתעלה למעלה מבחי' האה' שנק' משפיע עכשיו ותהי' עטרת לבעלה כו' והוא מ\"ש ג\"כ אב\"ן מאסו הבונים שהן בחי' המוחין דאו\"א שמולידים אהוי\"ר ב\"ן וב\"ת כו' והיתה בחי' הב\"ת בשפלות המדריגה מאד (כי מאיש לוקחה זאת אחת מצלעותיו ואו\"א תקינו לה שלזה נק' בונים כו' וד\"ל) היתה לראש פינה בראש דח\"ע והוא בחי' יר\"ע כנ\"ל. והענין הוא כידוע הכלל דנעוץ תחלתן בסופן וסוב\"ת דבחי' היראה שנק' ח\"ת נעוץ סוב\"ת ביראה ודחילו עילאה שהוא בחי' ח\"ע כמ\"ש הן יראת ה' היא חכ' שבראש דוקא שהוא בחי' כח מ\"ה ביטול במציאות האמיתי ועצמי כמו ונחנו מה מ\"ה ממש שלמעלה מביטול היש ולמעלה גם מאה\"ר בתענוגים ברשפי אש שלהבת י\"ה שנק' רחימו עילאה וכש\"כ מרחימו תתאה הנ\"ל להיות שזהו בחי' יר\"ע שהוא ביטול במציאות בתכלית מכל וכל עד שאינו מרגיש א\"ע כלל וכלל בבחי' יש ודבר מה והוא כמו שמתבטל פתאום בבואו לפני המלך עד שנעשה כאבן דומם ממש שלא יכול לדבר ואין בו שום התפשטות והרגשה בעצמו כלל וכלל כמו בש\"ע אד' שפתי תפתח כו' כידוע. אך א\"כ איך יוכל להיות שבחי' יר\"ת שאינו רק ביטול הישות וגסות בשפלות והכנעה לקבל עול לבד יעלה ויגיע למדריגה זאת דיר\"ע שהוא ביטול העצמי מכל וכל כנ\"ל אמנם הענין הוא דאדרבה היא הנותנת משום דביטול חיצוני זה שהוא מבטל א\"ע לבד ה\"ז כמו ביטול העצמי והפנימי בשרשו ביר\"ע שהוא ביטול הפנימי מכל וכל כי הרי בשפלות והכנעה זו שביר\"ת בריחוק מקום אעפ\"י שאינו רק ביטול היש לבד ואינו בבחי' ביטול במציאות כלל עכ\"ז הרי ביטול רצונו וכל עצמו להיות נכנע לכל אשר יגזור אומר עליו בקעומ\"ש הרי נעוץ בסוף זה מתחלת הכל שהוא ביטול הפנימי דיר\"ע ונעוץ סופן בתחלתן שיכולה יר\"ת לעלות בשרשה ביר\"ע שהוא ביטול המציאות מכל וכל כו'. וראיה לזה ממ\"ש סוף דבר כו' את האלקים ירא בביטול דקעומ\"ש לבד כי זה כל האדם דח\"ע שהוא יר\"ע כנ\"ל (כמו שהי' במ\"ת שע\"י שאמרו נעשה בקעומ\"ש לבד נמשך להם ממילא בחי' ביטול דיר\"ע עד שעל כל דיבור כו' וד\"ל) וז\"ש"],[2300680336,"ואלה דברי דוד האחרונים (שלמעלה מראשית דחכ' שבמדות) נאום הגבר הוקם על עולה של תורה ומצות למעלה גם מפנימית דאה\"ר בתענוגים דרחימו עילאה ותתאה כו' מטעם הנ\"ל וזהו ענין עליית המל' שהוא היר\"ת בקבלת עומ\"ש למעלה מצ\"ע דיוסף הוא בחי' כתר שם טוב דמשיח שעולה על גביהן כו' כמ\"ש הוקם על כו' ונמצא שיראה תתאה החיצונית שאינה אלא בחי' דומם בלא התפשטות אה' כלל יהיה למעלה מבחי' צומח דאה' שהוא רחימו תתאה ורחימו עילאה הפנימי' להיותה עולה בשרשה בבחי' יר\"ת דח\"ע שהוא בחי' ביטול האמיתי מכל וכל כנ\"ל וד\"ל:\n(יב) <b>ומזה</b> יובן הטעם יתרון מעלת ביהמ\"ק דלע\"ל על משכן דמשה דבמשכן דמשה הי' הצומח דקרשים בחי' משפיעי' למל' שזהו כמו התפעלות האה' שנק' משפיע כנ\"ל אבל לע\"ל תתעלה יר\"ת החיצוני' למעלה מבחי' עצי שטים דקרשים שעכשיו הן משפיעים ע\"כ יהי' הכל מאבנים ועפר בחי' דומם גם הדפנות גם המעזיבה למעלה יהיה מעפר בחי' דומם שהוא בחי' היראה כו' מפני שתגיע היראה בשרשה ביר\"ע דח\"ע בחי' מ\"ה האמיתי ע\"כ גם במעזיבה יהי' בחי' הביטול האמיתי שלמעלה מבחי' היריעות דמשכן משה שהן מקיפים דאה' בתענוגים כו' עד שבחי' צומח דקורות ארזים יהיה תחת המעזיבה לחיזוק לבד והוא בחי' אה\"ר בתענוגים שנק' ארזי לבנון כידוע יהיה רק בחי' תמכין דאורייתא שהוא בחי' ח\"ע בחי' הביטול האמיתי דיר\"ע הנ\"ל וד\"ל. ובזה יובן ג\"כ ענין וטעם דארץ קדמה לשמים במח\"ת כו' דהיינו בתחלת המח' דח\"ע שבראש שהוא בחי' ביטול האמיתי דמ\"ה דחכ' בחי' האין דח\"ע כמו מה פשפשת כו' שם ארץ קדמה לשמים כו' דהיינו בחי' יר\"ת שנק' ארץ קדמה לשמים שהוא האה' שנק' משפיע כמו השמים שנק' משפיע לארץ מטעם דנעוץ תחלתן בסופן וסב\"ת שהוא ביטול העצמי' שנעוץ בביטול חיצוני דיר\"ת והיו לאחדים ממש כשתגיע יר\"ת ביר\"ע שהרי גם בביטול העצמי ממש הרי עיקר הביטול הוא מה שנעשה כמו אבן דומם ממש מופשט מבחינת יש ודבר מה לגמרי מאחר שהוא בלי הרגשה בעצמו כלל וכלל והיינו ג\"כ ענין השפלות והכנעה דיר\"ת שנפשו כעפר ודומם כו'. וזהו טעם ענין עלי' בחי' הדומם לעץ דלע\"ל בבה\"מ במעזיבה שע\"ג הקורות וגם הדפנות שהן כמו אהוי\"ר שנולדים מן השכל גם הם יהי' מאבנים ועפר שהוא בחי' הביטול אמיתי דח\"ע דוקא שגם התפעלות אה\"ר בתענוגים שנק' יש מורגש גם הם יהיו בבחי' הביטול דח\"ע ויר\"ע והיינו מה שהקורות דארזים יהיו מונחים תחת המעזיבה מעפר שהוא רק כמשמשין להחזיק לבחי' הביטול האמיתי דבחי' דומם ממש (וכאה\"ר בתענוגים לפני בואו אל המלך שנכספה וגם כלתה נפשו לראות פני מלך וזהו חיזוק והכנה בבחינת הביטול במציאות ממש שנעשה כאבן דומם ממש מבלי הרגשת תענוג ואה' כלל בהגיעו לפני המלך ממש וזהו ענין עליות הנשמות בג\"ע עכשיו דכתיב והי' מדי חדש בחדשו כו' יבוא כל בשר להשתחוות לפני הוי' ממש בביטול העצמי ממש דהיינו בבחי' דומם ממש שזהו"],[2300680346,"למעלה הרבה גם מאה\"ר בתענוגים שלפני עלותם לה' להשתחות כו' דע\"ז אמר אז תתענג על הוי' כו' וד\"ל). (וזהו ענין ויגש אליו יהודה שהוא בחי' הביטול דיר\"ת דדוד הוא מלך המשיח הקים על שעי\"ז יוכלל יוסף ביהודה בהתוודע לאחיו כו' כנ\"ל משום דנעוץ תחב\"ס שהוא יר\"ע שלמעלה מיוסף כנ\"ל. אך כ\"ז הי' ענין הגשה בבחי' העלאת מ\"ן במס\"נ ביראה זו כמו בזאת יבא אהרן כו' בזאת דיראה דוקא ולא בזה דבחי' ב\"ן דכר דאה' והוא מה שאמר לו ידבר נא עבדך דבר שהוא היראה בקעומ\"ש שנק' דבר מל' מצות המלך וכתיב כבוד אלקים בחי' ב\"ן דיראה הסתר דבר שהוא בבחי' ס\"ג דבינה עלמא דאתכסיא וז\"ש באזני אדוני שיכנס באזניו אוזן דבינה בחי' ס\"ג וכמ\"ש אוזן מילין תבחן בין טו\"ר ע\"כ אל יחר אפך בעבדך כי בחי' יסוד ז\"א דיוסף כלול מהכל ויכול להשפיע גם מבחי' הגבורה דאף וישתלשל מזה בחי' גבורות קשות ביותר ולזה בקש שלא יחר אפו אחר שנמתקים הגבורות בחסדים דאימא בבחי' ס\"ג בשרשן כי כמוך כפרעה בחי' פריעה והתגלות דבחי' המל' שמקבל מה\"ח מיסוד שאין צד אחיזה לגבורות קשות שם דכד אריה וארייתא כו' ועוד ששרש צ\"ע ביסוד דא\"א שנק' טובו הגדול כמ\"ש צדיק כתמר יפרח כמ\"ש כשם שאין בלבך אלא אחד כו' שלא שייך שם בחי' דינים ממש כי אין רע כו') ופרטי ענין הסיפור הזה בכל אשר עשה יוסף עם השבטים וביהודה בפרט שמסר נפשו על צ\"ת בנימין כמ\"ש ישב נא עבדך תחת הנער שירד בחי' המל' להיות בחי' מט\"ט עבדי' דשכינתא להיות עבד ליוסף צ\"ע תחת הנער דבחי' צ\"ת כו' הענין הי' רק לתקן החטא שלהם בקנאתם על יוסף צ\"ע שבודאי השבטים שהי' מרכבה לשכינה כמ\"ש כשם שאין בלבך אלא אחד כו' לא הי' בזה קנאה גשמית ח\"ו רק לש\"ש על אודות גילוי עצמות אור אצי' שביעקב ליוסף לבד ובפרט בכתונת הפסים שעשה בחי' מקיפים עליונים כו' וחשקה נפשם ג\"כ לזכות לעילוי גדול כזה בקרבת אלקים ונמנע מהם אור העליון שאינו לפי\"ע כלל ע\"כ נתקנאו בו. אמנם מה שיש בזה תערובות חלק רע דק\"נ דבריאה שהוא כמו קנאה דנחש הקדמוני דבריאה באדה\"ר וחוה דבריאה שהי' שרש לקנאה זו גם באדם דאצי' והוא נחש הנחושת דמשה כו' בחי' גבורות דקטנות דשם שדי (שנק' חויא דרבנן כמ\"ש במ\"א כו') שנשתלשל מזה השנאה ממש בעוה\"ז ראה יוסף שנחש דעשיה קשור בשבטים שלמטה מזה יניקה למות ממש כמו שהמות גשמי נמשך מזוהמא דקנאה נחש דעשיה באדה\"ר שלמטה לזאת רצה לתקן שיוסר מהם המות הרע הזה כי שרש קנאתם לשם שמים הי' בבחינת אלקו' ממש כנ\"ל רק תערובות אפס קצהו ירדה למטה בבחי' רע ע\"כ התחכם בתחבולות שונות לעשות אותם מרגלים לראות את ערות ארץ מצרים שהוא נחש דק\"נ וציערם הרבה עד שהביאם למס\"נ על בנימין צ\"ת שהיה במדריגות יוסף בחיצוני' דיסוד שהוא עושה התקשרו' המקבל במשפיע כו' בחי' צ\"ע וצ\"ת וזהו ויבך על צוארי בנימין ובנימין בכה על כו' וד\"ל. ובמס\"נ שלהם על בנימין ממילא ניתקן חלק הרע דקנאה שלהם ביוסף והוסר מהם המות"],[2300680356,"דנהח\"ק למטה ולא נשאר רק שרש הקנאה בדקותו למעלה שמשם נמשך הקנאה דע\"ש בישראל להורידם מגדולתם ואמונתם ונתקנו ביו\"ד הרוגי מלוכה כידוע וד\"ל. וכך הוא הענין גם למעלה מעלה בשרש לשרש דק\"נ דאבי\"ע שאינה רק קנאה כמו קנאת נחה\"ק כו' והוא שהחריב לביהמ\"ק שנתן עיניו בקנאה על גילוי אלקות וכן במ\"ת הקנאה גברה שהורידם בחטא העגל כו' ועיקר הקנאה שלהם הוא רק להדמות לסט' דקדושה כקוף בפני אדם וע\"כ כל תשוקתם להיות מנגדי' לקדושה בכדי להוריד הקדושה וזהו כל עיקר ענין הקטרוגים של המלאכים הרעים שנק' גבורות קשות כמו בר\"ה שבאו להתייצב על ה' ויבא גם השטן בתוכם להיות מזה רצועה לאלקאה בפו\"מ ח\"ו וד\"ל. ובחי' התיקון שלהם הוא להסיר שרש הקנאה דנחה\"ק למעלה ולמטה והיינו כמו שעשה יוסף צ\"ע עם השבטים שהסיר מהם כל קנאה דנחה\"ק בשרשו למעלה ולמטה ע\"י מס\"נ של השבטים על צ\"ת שהוא"],[2300680366,"בחינת התקשרות עצמית דכנ\"י בתו\"מ ובאמונה פשוטה כו' שזהו שמתקן לקנאה דנחה\"ק שבאוה\"ע על ישראל בכל דור לאמר לכו ונכחידם מגוי ולא יזכר שם ישראל עוד וד\"ל. וזהו כל אריכות הסיפור בב' סדרים הללו דמקץ ויגש בעובדות ותחבולות שונות דיוסף עם אחיו להמציא נפשם במס\"נ על בנימין ונשלם כוונתו בהעלאת מ\"ן דיהודה בכל דבריו איך אעלה כו' ופתח דבריו הי' להמתיק הגבורות קשות שלא יחר אפו בסיבת קנאת נחה\"ק ויקובל דבר שידבר באזניו כו' שיבא לגילוי בדבר מלך כמ\"ש כבוד מלכים חקור דבר כו' שיחקור לאמתתו בעלמא דאתגליא דוקא. וזהו שחזר הדברים אדוני שאל את עבדיו כו' שנעשה מזה פרשה שלימה בתושב\"כ דאורייתא מח\"ע נפקת באותיות בגילוי כו' שא\"א לעשות נגד משפט התו' שנק' אמת ע\"כ ולא יכול יוסף להתאפק כו' לפי שאין מסך מבדיל למנוע יחוד וגילוי יוסף צ\"ע בשבטים בכל דור ודור דהתורה נצחית הוא בכל דור ובכל זמן כידוע:"],[2300680037,"(א) <b>אסרי</b> לגפן עירה ולשרקה בני אתונו כיבס ביין לבושו כו' חכלילי עינים כו'. הנה פסוק זה אסרי כו' קאי אדסמיך ליה עד כי יבא שילה ולו יקהת עמים כו' פי' כאשר יתגיירו העמים אזי אסרי לגפן כו'. ויש להבין סמיכות הענין למה תלה זה בזה. אך הענין דאמרז\"ל אין בין העוה\"ז לימוה\"ש אלא שיעבוד גליות בלבד כו'. דהנה ימות המשיח אינו העוה\"ב שלאחר תחיית המתים שאז יהי' מתן שכרם של צדיקים אבל בימות המשיח יהי' עיקר השלימות במעשה המצות דוקא והוא בבחי' היום לעשותם ולא לקבל שכרם (וזהו שהשיבו משיח היום אם תשמעו בקולי כו') ומה שלא הי' שלימות המעשה באדה\"ר בג\"ע דכתי' ביה ויגרש האדם כו' וידוע פי' לעבדה ולשמרה שהן רמ\"ח מ\"ע ושס\"ה ל\"ת ע\"י שהי' מבער הקוצים כו' וגם מה שלא נשתלם המעשה בימי דוד ובזמן הבית עד שגלו מא\"י כו' ישתלם בימוהמ\"ש שאז נק' אדם בשלימות משא\"כ קודם לכן ואדם אין כו' כי כל עיקר הכוונה הראשונה שהניחו לאדה\"ר בג\"ע הוא לעבדה כו' ולא עלתה בידו כו' לזאת הי' הכוונה לתקן המעשה בכניסת אבותינו לא\"י בהיות שכל עיקרי המצות תלוין בארץ דוקא כמעט ד' חלקים מהם כו' מזה נראה שעיקר הכוונה בשביל המעשה כמו שאמר היום לעשותם. אך שלא נשלמה המעשה עד יוהמ\"ש וד\"ל. וזהו שאנו אומרים ושם נעשה את קרבנות חובותינו תמידים כו' כמצות רצונך דמשמע שאז דוקא נעשה כמצות רצונך ולא קודם לכן מפני שעיקר שלימות המעשה לא היה עדיין עד ליוהמ\"ש כנ\"ל ובגלות שנתקנה התפילה במקום קרבן א\"ז עדיין כמצות רצונך ממש. ויש להבין הטעם לכל זה שהרי באמת התפלה יותר גדולה במעלה מן הקרבנות שע\"י התפלה מעלה הוא נפש האדם השכליי' ומקריבה לה' אחד במס\"נ ע\"י ההתבוננות כו' והקרבנות הוא העלאה"],[2300680053,"הגשמי' של נפש הבהמה ע\"ג המזבח כו'. אך הענין הוא דכתיב גפן ממצרים תסיע כו' כסו הרים צלה כו' וידוע דכנס\"י נמשלה לגפן ועד\"מ הגפן הגשמי הנה אנו רואים סיבת יציאת היין מן הענבים הוא ע\"י דריכה בגת דוקא להיות כי היין כנוס בענבים בהעלם וע\"י הדריכה יוצא לידי גילוי כו' ועוד זאת אנו רואים שהיין המשובח ביותר יוצא מן הענבים הגדלים למטה בגפן סמוך לקרקע וכמ\"ש רז\"ל בנסכים לא הי' מביאין מן הדליות אלא מן הרגליות כו' והנה היין מתחלק לכמה מינים שונים יש יין לבן הנק' חווריין עתיק כו' והוא היין המשמח כו' ויש יין אדום והוא יין המשכר כו'. ובכל המשל הזה יובן הנמשל בכנס\"י בהיות שאהבה הנטוע בכללות נש\"י לה' אחד טבעיות הוא שמוטבע בנפשם מכח ירושתם מאבותיהם כמ\"ש נטעתיך שורק כו' וכן נק' גפן שנגדלה בענפים רבים אך מפני שאהב' זו מסותר' היא בהעלם גדול מפני חומר מחשך גופם כידוע צריך להוציאה מן ההעלם ע\"י דריכה דוקא והוא בחי' לב נשבר ונדכה כו' וגם כל מה שמשפיל עצמו ביותר מפני הלב נשבר כו' עד שנפשו כעפר לכל תהי' כו' יהי' היין משובח ביותר (והוא כמשל הענבים שברגליות הגפן כנ\"ל) והיינו שתהי' האהבה המסותרת בבחי' גילוי רשפי אש בעריבות ומתיקות ביותר כו'. והנה על יין אמרו נכנס יין יצא סוד לפי שהיין הי' ראשית יציאתו מן ההעלם לגילוי כשיצא מן הענבים לכך טבעו בעצמו ג\"כ להוציא את ההעלם שבנפש האדם לידי גילוי כששותיהו כו' והיינו בנמשל בכנס\"י כאשר האהבה אלקי' היא בהתפעלות השמחה וחדוות ה' מעוזו כו' ע\"י ההתבוננות בהתענגו על ה' כו' נק' חמר חוורין עתיק כו' והוא היין המשמח אלקים כו' וכאשר מתפעל באהבה של מרירות וכלות הנפש בתשוקה מרחוק כו' מפני שמתבונן עוצם ריחוקו מה' אחד כו' עד שמואס"],[2300680069,"בחייו כו' הגם שמרירות זו מפני האהבה לה' היא באה ממה שאיננו משיג אלקות בבחי' קירוב כו' כמשל המתאווה תאוה ואינו משיגה כמו באותו שהעלה טינא בלבו כו' עכ\"ז בחי' גבורות והסתלקות הוא בהיפוך השמחה והחדוה שהוא בחי' המשכה וירידה כו' ולזה הטעם נק' יין אדום והוא יין המשכר ומבלבל הדעת ובחי' גבורות נמשכים ממנו כו' ואינו משמח כלל כו' ושני מיני אהבות הללו הן בחי' חו\"ג דיין שיוצא מן הענבים ע\"י דריכה כו' וזהו גפן ממצרים תסי\"ע בעודנה בבחי' ההעלם דענבים שבגפן כו' נק' כנס\"י גפן כו' והוא כשנסעה שכינה עמהם ממצרים במ\"ב מסעות ואח\"כ נכנסו לא\"י ונתגלו ההעלמות שבה בבחי' חו\"ג של יין המשמח ויין המשכר בכמה מצות מעשיות וכמשי\"ת בעז\"ה וד\"ל:\n(ב) <b>והנה</b> אנו אומרים בשבת וינוחו בו כל ישראל מקדשי שמך כו'. ויש להבין הלא הוא ית' קדוש מעצמו מצד שהוא קדוש ומובדל בערך מכל ההשתלשלות כמ\"ש כי קדוש אני כו' ואני ה' מקדשכם שקדושת ישראל נמשכה מקדושתו ואיך יתכן שיהי' קדושת ה' תלוי' בקדושת ישראל עד שיקראו מקדשי שמו שגורמים להיות שמו קדוש כו'. אך הענין הוא שאנו אומרים אתה קדוש ושמך כו' וקדושים בכ\"י יהללוך סלה. פי' בכל יום משמע שמלאכים הללו הנק' קדושים הם מתהווים בכל יום ומהללים כו' וביאור הדברים הנה הוא ית' נק' אדון הנפלאות פי' נפלאות הוא מה שאינו מושג ונתפס בשכל והשגה כו' כמו כי יפלא ממך הדבר כו' ואדון הנפלאו' הוא למעל' מעלה גם מבחי' ההפלאה וכמ\"ש עושה פלא שהפלא ג\"כ בחי' עשי' גשמי' לגבי עצמותו ית'. ולהבין זה הנה החכ' מאין תמצא והיינו ענין התהוות השכל מלמעל' מן השכל שנק' פלא בהפלאת העלם הדבר איך יתהווה היש מן האין כו' וגם זאת בחי' עשי' גשמי' נחשבת לגבי עצמות ההעלם שלמע' מהתהוות חכמה כו' ולכך נאמר עושה פלא וגם על מה שנתהווה מן החכ' נא' בחי' עשי' כמ\"ש כולם בחכמה עשית מטעם זה שהחכמה עצמה שמאין תמצא היא בחי' עשי' בלבד וד\"ל. והטעם שנק' בחי' עשי' דוקא הוא לפי שהמעשה מסתעפת מן השכל וכערך המעשה לגבי השכל שהוא סוכ\"ד כן ערך התהוות השכל מלמעל' מן השכל בבחי' מעשה סוף כ\"ד של ההעלם העצמי' כו' כמ\"ש במ\"א וד\"ל. וזהו ושמך קדוש פי' החכמה שנתהווה ע\"י שם הוי' וממנו נסתעף כל ההשתלשלות כמ\"ש בראשית ברא כו' כידוע גם הוא קדוש ומובדל כו' בהיות שבי\"ה הוי' צור עולמים כתיב ופי' י\"ה הן חו\"ב וביו\"ד שבחכמה נמשך הוי\"ו ממנו ונעשה שם הוי' לצייר עולמים ב' מיני עולמות עלמין דאתכסין ועלמין דאתגלין כו' כי הנה ביו\"ד נברא העוה\"ב דכתי' בו עין לא ראתה אלקים זולתיך כו' ואינו בחי' ג\"ע העליון שהרי הנשמות נהנין מזיו כו' והוא בבחי' גילוי ההעלם. אך לגבי עוה\"ז הגשמי נק' עלמא דאתכסי' כו' אבל עלמין סתימין דבי\"ה כו' שעין לא ראתה כו' היינו שלא בא לידי גילוי כלל מן ההעלם ואינו נתפס בשום נברא כלל רק אלקי' זולתיך כו' והוא היו\"ד שממנו נבראו העלמין סתימין וכמ\"ש בי\"ה הוי'"],[2300680085,"צור עולמים ונמצא שמו ית' הנק' הוי' קדוש ומובדל הוא כאשר הוא בשרשו בי\"ה כו' וזהו ושמך קדוש והיינו ג\"כ ענין עושה פלא הנ\"ל וכ\"ז נמשך מפני שאתה קדוש בעצמו ומהותו כלומר שהוא אדון הנפלאות למעל' מהתהוות פליאות חכ' מאין ליש ונק' קדוש בעצם שאינו גם בגדר התהוות עלמין סתימין כו' ונק' סתימא דכל סתימין כו' וד\"ל. וזהו ענין ישראל מקדשי שמך הגם שהוא קדוש מצד עצמו כו' אך כדי להמשיך מקדושת עצמותו לקדש את שמו להיות עושה פלא ובי\"ה הוי' צור עולמי' כנ\"ל הוא ע\"י ישראל דוקא לפי שבאתעדל\"ת אתעדל\"ע כידוע והנה המצות מעשי' ידוע שישנם באצי' ולמעלה מהאצילות ג\"כ כידוע בענין הקב\"ה מניח תפילין כו' וזהו אשר קדשנו במצותיו מצותיו ממש הם וע\"י המצות שישראל עושין למטה עושה הקב\"ה מצותיו למעלה מעלה עד שנמשך מקדושתו העצמי לקדש את שמו הוי' בכל מצוה לפי אופן המשכתה באא\"ס עצמו כמו להיות נברא עושה פלא הוא החכ' מאאלפ\"ך חכמה ע\"י הנחת תפילין דמארי עלמא כו' והתלבשות אוא\"ס בחסד להיות עלמין סתימין כמ\"ש כי בי\"ה כו' ע\"י הצדקה וכדומה לזה בכל המצות מעשיות המה מקדשי שמו ית' דהיינו להיות נמשך מאתה קדוש לשמך קדוש כנ\"ל וד\"ל. ועיקר הטעם לזה הוא לפי שהמצות שרשן בבחי' רצה\"ע שלמעלה הרבה מן החכ' כידוע ולכך יש ביכולת מעשה המצות לקדש את שמו ית' להיות קדוש בקדושת הכתר עליון וזהו אשר קדשנו במצותיו וכמ\"ש במ\"א וד\"ל. וזהו וקדושים בכ\"י כו' פי' כי להיות כי הוא ית' מחדש בכל יום מע\"ב (כי יש ב' מיני השתלשלות הא' להמשיך להנבראים שפע חדשה בלבד והב' להמשיך נבראים חדשים מעיקרם ושרשם והיינו ענין יוצר משרתים ואשר משרתיו כו' כמ\"ש במ\"א) וזהו במה שהמל' יורדת להסתתר בבי\"ע להחיות רוח שפלים וכמ\"ש ותקם בעוד לילה ותתן טרף לבית' כו' ולהיותם ממש מאין הם משיגים ביותר שורש מקור המהווה אותם איך שהוא בחי' אין כו' ואומרים קדוש כו' ונכללים ומתבטלים במציאותם וזהו שאומרים קדוש קדוש כו' כלומר שמשיגים בחי' התהוותם הוא מאין שהוא קדוש ומובדל בערך מהם ואו' אי\"ה מקום כבודו כו' והיינו לפי שמתחדשים ממש וקרובים אל האין ביותר וזהו הטעם שנקראים קדושים ע\"ש צעקתם לומר קדוש וע\"ש התקרבותם לבחינת קדושת ה' והכל ענין א' וד\"ל. והיינו שהם אומ' קדוש בלי הפסק כלל דהיינו בבחי' עילוי אחר עילוי בבחי' הסתלקות והעלם השגת' באלקות עד שיהללו סלה מפני שאין קץ ושיעור לרוממות אלקו' למעלה מעל' מן החכמה כמו שנק' אדון הנפלאות כו' וד\"ל. ואמנם גם היכולת הלז' שיוכלו הקדושים הללו לומר קדוש בלתי הפסק להיבטל ולהיכלל במקורם הוא בא ונמשך מקדושה העליונה שישראל מקדשים שמו כמ\"ש ושמך קדוש ואח\"כ וקדושים בכ\"י כו' מטעם הנ\"ל וד\"ל. ובכל זה יובן יותר הטעם דיפה שעה אחת בתשו' ומע\"ט בעוה\"ז מכל חיי העוה\"ב לפי שחיי העוה\"ב הוא מן היו\"ד שבי\"ה כו' אבל אא\"ס בעצמו קדוש ומובדל גם מעשות פליאת חכמה כו' וכנ\"ל וע\"י מעשים טובים בא ונמשך קדושת עצמותו להיות קדושת שמו"],[2300680101,"כנ\"ל לכך יפה הוא מכל חיי העוה\"ב לפי שהן שרשים ומקורים לחיי העוה\"ב שנמשך מן היו\"ד והוא אשר עין לא ראתה כו' כנ\"ל וד\"ל:\n(ג) <b>והנה</b> כתיב תחת אשר לא עבדת את ה' אלקיך בשמחה וטוב לבב כו' שזהו ענין שמחה של מצוה כו' וצ\"ל למה גדלה מעלת השמחה יותר מן המצוה עצמה כו'. אך הענין הוא דמן המצות נעשו לבושין לנפש האלקי' כידוע ע\"פ ואברהם זקן בא בימים כו' מ\"ש בזוהר דאינן לבושין כו' שהן בחי' אורות מפנימי' רצה\"ע כו' החופף על הנשמה בג\"ע אך הנה אמרו דאפי' פושעי ישראל מלאים מצות כו' ואנו רואים שאין המשכות גילוי אלקו' כלל עליהם כו' אלא הענין הוא שע\"י עונג האלקי בהתבוננו' בגדולת הבורא הנק' חמר חוורין עתיק כו' כנ\"ל יגיל וישמח בה' ויתענג על ה' מחמת ההתבוננות ואז כאשר יתבונן במצות ה' איך שהם פנימית רצונותיו ית' שהוא מבחי' אוא\"ס ב\"ה בעצמו הנק' אדון הנפלאות יגיל וישמח לבו בקיום המצות באמרו אשר קדשנו במצותיו כו' ושמחה ש\"מ זו מעוררת וממשכת מלמעלה בחי' יין לבן העליון שגנוז בו השמחה והעונג העליון כו' וזהו כבס ביין לבושו ביין חמר חיורין העליון לבושי המצות שנתלבשו בענינים גשמי' דנוגה ומכש\"כ במצות שפושעי ישראל עושין שנפשותם מלאין מן לבושים צואים לבושים מסאבותא כו' על כולם יין הלבן העליון מכבס אותם כו' והוא ע\"י שמחה של מצוה דוקא וד\"ל. ועד\"ז יתפרש ובדם ענבים סותה דהנה פי' דם ענבים הוא בחי' יין המשכר והוא יין אדום כדם כו' דהיינו בחי' גבורות קדושות בבחי' מרירות עצומה מגודל עוצם ריחוקו מאלקי' חיים בלבושי נפשו הצואים כאשר יהי' ממארי דחושבנא על המעשים ומחשבות ורצונות אשר לא לה' המה כו' ובמרירות זו נהפך מרירא למיתקא וחשוכא לנהורא כו' כי אין מיתוק הדין אלא בשרשו שהגבורות דקדושה האלקי' כופה ומגרש את הרע דקליפת נוגה כידוע וכענין לעולם ירגיז אדם יצר טוב כו' וד\"ל ונק' דם ענבים לפי שהדם הוא הנה\"ב דנוגה וע\"י הענבים שהוא ההתבוננות בגדולת ה' תתמרמר הנפש האלקי' ויהפוך רצון הגוף כו' ונהפך דם ליין והוא יין האדום המשכר כו' לפי שבחי' גבורות קשות דנוגה מסתעפים ממנו דהיינו גם הרוגז וכו' וד\"ל והנה אנו רואים שעיקר התענוג תלוי במילוי רצון שכשממלא רצונו מתענג בו אח\"כ מאוד ומצטער מאוד מן ההיפוך כשלא נתמלא רצונו וא\"כ כל שהי' לו תשוקה ותאוה אל אותו דבר שרוצה בו ביותר כן תגדל העונג ביותר כשימולא רצונו וישיג אותו הדבר משא\"כ אם לא הי' חושק ומתאווה אליו כ\"כ שאין המילוי רצון כ\"כ גם העונג בו אח\"כ מועט הוא כו' ועד\"ז יובן בעבודת ה' שבחי' המרירות וגבורות דקדושה הרי הוא בחי' תשוקה מרחוק לידבק בה' אחד ומחמת זה מצטער על ריחוקו מה' כו' וא\"כ כל שיגביר ויגדיל התשוקה מרחוק בבחי' מרירות כו' כן ירבה ויגדל העונג האלקי בהשיגו הרצון שלו הוא התענגו על ה' בהתבוננות בבחי' קירוב שהוא מדריג' יין המשמח הנ\"ל הנק' חמר חיוורין עתיק כו' ונמצא"],[2300680117,"יין האדום הוא הכנה ליין הלבן וצריך להקדים בנפשו בחי' יין המשכר ליין המשמח לפי שריבוי יין הלבן תלוי בריבוי יין המשכר כו' וזהו המשך הפסוק כבס ביין כו' ערך הכיבוס ביין הלבן בריבוי עונג העליון לפי ערך ריבוי דם הענבים שקדמו כו' לפי שריבוי השמחה של מצוה בהמשכות אא\"ס בעצמו כו' תלוי' לפי אופן ריבוי תשוקת הנפש למילוי רצון זה כנ\"ל וד\"ל וזהו זאת נחמתי בעניי כי אמרתך חייתני פי' בעניי ריבוי המרירות שמצד הגוף הנק' עוני כו' זאת נחמתי כי אמרת ה' במעשה המצות הוא חיות ומזון הנפש ביתר שאת מפני ריבוי המרירות כנ\"ל וד\"ל וזהו ענין הדריכה בגת שהוא לב נשבר הוא בחי' הכנה כללי' לב' מיני יין הנ\"ל שיצאו מן ההעלם לגילוי כי המרירות בחי' התלהבות והתפעלות הלב הוא וגם היא לא תבוא לידי גילוי מן ההעלם עד שיוקדם בחי' הדריכה והוא לב נשבר ונדכה הנק' כובד ראש והוא בחי' עצבון הגוף אך אין לערבב שמחת הנפש בעצבון הגוף כמ\"ש במ\"א וד\"ל וענין הרגליות הוא בחי' השפלות עד קצה האחרון ונפשו כעפר כו' הן הענבים הטובים להוציא מהן ב' מיני יין הנ\"ל משא\"כ מן הדליות כנ\"ל וד\"ל. ועתה יש להבין פי' סותה מה היא הנה הוא מלשון מסוה ופי' מסוה הוא כיסוי הראש והפנים כידוע דהנה יש ב' מיני לבושי' הא' לבושי הגוף הנחתכים ונעשי' כפי מדת האברים של הגוף ולפי תועלת היופי השייך להגוף כו' והב' הן לבושי הפנים והראש שתועלת' הוא ביופי הפנים שאין לו ערך כו' משא\"כ בחי' יופי הגוף וגם תועלת הכלי' ואברים הפנימים בראי' שמיעה ריח ודיבור כו' ג\"כ הן גבוהים במדריג' הרבה מתועלת אברי הגוף כמו כלי ההבטה דרך המסווה שתועלתו יקר הרבה מלבוש היד וכדומה כו'. וידוע דעל הלבושים דוקא שורה בחי' המקיפים וא\"כ מקיפי הראש והפנים גבוהים הרבה ממקיפי הגוף כו'. והנמשל מכל זה יובן למשכיל למעלה בהיות ידוע דלבושי המצות הן בחי' מקיפים עליונים מפנימית רצונותיו ית' וע\"י היין מתכבסים כמ\"ש כבס ביין לבושו וכנ\"ל. והנה כנגד ב' מיני יין הנ\"ל נמשך ב' מיני לבושים של מעשה המצות מלמעלה למטה כו' לבושי הראש ולבושי הגוף וכיבוס הלבוש ביין הוא לפי אופן מדריגתו והיינו שע\"י היין הלבן נמשך לבושי הגוף ונכבסו בו כנ\"ל לפי שהוא מדריגת השמחה בחי' הירידה והמשכה כו' וכמו תועלת לבושי הגוף כו' אבל ע\"י דם ענבים יין האדום הנ\"ל נמשך לבושי הפנים והוא המסווה שכלי הפנים תועלתם יקר הרבה כו' והוא בבחי' עלי' והסתלקות כו' כמו עילוי מדריגות כלי ההבטה היינו כאשר יסתכל בכלי ההבטה המסתיר כלי העין כו' והיינו מ\"ש הביטו אליו ונהרו כו' פי' הביטו בהסתכלות חזקה ע\"י כלי ההבטה ינהרו הפנים ממילא בבחי' ראי' חושית הגם דחכמה היא בחי' ראי' אבל הוא ראי' שכלי' כו' ואז ממילא ופניהם אל יחפרו ויכלמו דהיינו ההשגה בחכ' הנק' פנים בבחי' מוחין שבראש כו' וענין הסתכלות החזק הוא כשיביטו אליו דוקא אליו ולא למדותיו כו' דאעפ\"י שא\"א להסתכל בשכינה היינו"],[2300680133,"באספקלריא דלא נהרא אבל בכלי ההבטה שמאירה כתי' הביטו אליו ונהרו כו' ובהיפוך את זלעו\"ז עשה האלקי' כתי' עינים להם ולא יראו כי עיני החיצונים סומין בבחי' העדר השגה כו' וגם בלעם הי' שתום העין כו' לפי שאור המקיף מסמא עיני החיצונים וע\"י המסווה בצדיקי' יאיר את עיניהם כו' לאסתכלא ביקרא דמלכא ע\"י אותו הלבוש כו' וד\"ל. ועד\"ז שארי כלי לבושי הפנים בשמיעה וריחא כו'. וכ\"ז נמשך ע\"י היין דדם ענבים דוקא לפי שהמרירות הוא בחי' בעלי תשובה ואעפ\"י שאין עושין מצוה כצדיקי' ואמנם ע\"י עליות והסתלקות נפשם במס\"נ מלמטה למעלה כו' ע\"י המרירות מעומקא דליבא מעוררים למעלה ג\"כ בחי' לבושי הראש שמקיפים למעלה מבחי' המוחין שבראש כנ\"ל וע\"י מעשה הצדיקים ע\"י שמחה של מצוה שהם מתענגים על ה' בבחי' ירידה והמשכה כו' מעוררים בחי' ירידת עונג העליון להיות שורה על לבושי הגוף כו' והיינו שאמרו שבע\"ת גדולים מן הצדיקי' עד שבמקום שבע\"ת עומדים דהיינו לנגד פנים העליונים שם אין צדיקי' גמורים יכולים לעמוד וד\"ל וזהו כיבס ביין לבושו ע\"י הצדיקים ובדם ענבים סותה ע\"י בע\"ת כו' וד\"ל:\n(ד) <b>ואחר</b> כל הנ\"ל יובן הטעם שעיקר שלימות המעשה יהי' לימות המשיח דוקא כנ\"ל בהיות שמבואר למעל' שלימות המשיח יהי' בחי' אדם בשלימות בכנס\"י ולזה הטעם זמן הקיום של המצות בשלימות כמצות רצונך כו' בימות המשיח דוקא כו'. וביאור הדברים הנה כתי' ואדם אין לעבוד כו' ואחר שנברא האדם כתי' ויניחהו בג\"ע לעבדה ולשמרה כו' ואחר שחטא כתי' ויגרש את האדם כו' וכשנכנסו כנס\"י לארץ נתקן קצת בחי' אדם כמ\"ש ואלה המצות אשר יעשה אותם האדם כו' שע\"י מעשה המצות נעשה בחי' אדם לעילא כמ\"ש במ\"א אך עדיין לא הי' שלימות האדם עד ימות המשיח דכתי' בי' ישכיל עבדי כו' וגבה מאד אותיות אדם בהיפוך אתוון ר\"ת אד\"ם אדם דוד משיח כידוע והיינו ג' הזמנים שיהי' בהם בחי' אדם באדה\"ר ובדוד ושלימותו יהי' במשיח והוא יתקן בחי' אדם בשלימות עד שיהי' יותר נעלה גם מבחי' אדם שהי' באדם הראשון בג\"ע קודם שחטא דכתי' בי' ויניחהו בג\"ע כו'. וביאור ענין אדם הוא ע\"ד דוגמא באדם הגשמי שהוא בן דעת ושכל ואין לנפש הבהמה ערך עמו כלל כידוע כו' כמו\"כ כאשר השכל האלקי' יתגבר בנפש האלקי' ויכיר את בוראו בבחי' מוחין דגדלות בהתגלות תמידי בלי נפילה לעולם כמו שישכיל בשכל האנושי דבר המוטבע כו' אז נק' אדם לגבי נפשות השכליות דנוגה והן נחשבים בחי' בהמה לגבי' כמו שאמר כלב סר צילם מעליהם לחמנו הם כו' כי צל אדם סר מעליה' ואחד ירדוף אלף כמו שאדם אחד ירדוף אלף צאן כו' ואז יש ביכולת האדם הזה לתקן נה\"ב להעלות בחי' ניצוצות דקדושה שנפלו בה ע\"י שבה\"כ כידוע והו\"ע הקרבן שיקריבו ליומהמ\"ש להעלות הכבשים והפרים כו' בהיות שאז יתגלה כבוד ה' וראו כל בשר כמו בשכל אנושי בבחי' ראי' מקרוב כו' לכך יהי' ביכולתם להעלות גם הכבשים והפרים"],[2300680149,"ולעשות בהם כמצות רצונך כו' מפני שיש בכח האדם להעלות נפש החי ע\"ד העלאה של עכשיו שנפש האלקי' בהתדבקה לה' בתפילה תעלה מה שתאכל מן החי וצומח כו' כמאמ' רז\"ל משחרב בהמ\"ק שולחנו ש\"א מכפר עליו כו' אך באמת התפלה שעכשיו במקום קרבן אין הענין כקרבן ממש שהרי אז דוקא נא' כמצות רצונך ולא עכשיו אלא הענין הוא שתפלה ודביקות ה' במס\"נ אינה פועלת אלא התיקון לתקן בחי' אדם בלבד וכן עשיות המצות אינם אלא תיקון נפש האדם שיהי' בבחי' אדם אבל אין עדיין בחי' אדם בשלימות עד לימהמ\"ש וזהו שאמרו תפלה במקום קרבן ולא כקרבן ממש כי העלאת נפש הבהמה והצומח שגם הם יוכללו באוא\"ס א\"א כ\"א ע\"י אדם השלם בשלימות אבל כשיש בו קצת מבחי' נפש הבהמה איך ביכולת נפש הבהמה לעלות ולתקן כו' כי רוח האדם היא העולה למעלה מעלה להכיר את בוראו כו' ורוח הבהמה יורדת למטה מטה כו' וכאשר הם ב' הפכי' בתכלית אז יעלה רוח האדם את רוח הבהמה כו' וד\"ל וזהו שעיקר זמן היום לעשותם יהי' בימות המשיח משא\"כ בזמן הגלות אין מעשה המצות אלא לעילוי ותיקון הנפש בלבד שיקרא אדם כו' וענין תיקון המצות לעשותו אדם היינו כל מה שנתבאר למעל' ע\"פ כבס ביין לבושו כו' שע\"י ב' מיני יין הנ\"ל יקרא אדם במעשה המצות כמ\"ש ואברהם זקן בא בימים כו' וד\"ל. וזהו אסרי לגפן עירה כו' פי' לימהמ\"ש שאליו יקהת עמים כדקאמ' בסמוך אז יהי' כנס\"י בתכלית השלימות של בחי' אדם כנ\"ל והנה נק' בשם גפן כבר כשיצאו ממצרים כנ\"ל כמ\"ש גפן ממצרים תסיע כו' והיינו ב' מיני יין הנ\"ל בשמחה ש\"מ ושמחה של בע\"ת דם ענבים שבכל אלה נכבסו לבושי המצות להיקראות בשם אדם בשלימות וזהו אסרי לגפן עירה שמן הגפן הנאסר ונקשר לצאת ממנו היין הנ\"ל נתהווה עיר\"ה עיר ה\"א וכו' כי הנה בפי' עירה יש ב' ענינים הפכים הא' מלשון עיר פרא אדם יולד ול' עיר אלא שנהפך מעיר פרא אדם להיקרא אדם והוא בחי' עיר אלקינו כו'. ופי' הדבר הנה עיר פרא כו' הענין הוא כמו שהוא בתחלת מולדתו כשנוצר בטבעו מדותיו משוגעים כפרא אדם כו' ובעבודת ה' יובן הנמשל דהיינו כאשר לא נהפך באדם הטבעיות שלו כעס וגאוה ותאוות וכדומה מחמת עבודת ה' אלא עדיין הוא כמו שנולד בטבעו מבטן אמו נק' פרא אדם היפוך בריאת אדם השלם אלא כנפש בהמה נחשב הגם שיש לו שכל אנושי כו' ומטעם הנ\"ל אבל כששכל האלקי' נתגבר בו עד שנהפך טבעו שנולד בו ויכול לעמוד נגד טבעו מן הקצה אל הקצה בכל הענינים כו' זהו הנק' אדם כמ\"ש כי רוח האדם הוא העולה כו' וזהו שע\"י אסירת הגפן לצאת מן ההעלם בחי' אהבה ויראה בבחי' ב' מיני יין הנ\"ל להיקראות אדם אז נק' עיר\"ה בה\"א ע\"ש עיר אלקינו כמארז\"ל אימתי גדול כשהוא בעיר אלקינו בבחי' בית והיכל כתפארת אדם לשבת בי\"ת כו' והן המדות אהוי\"ר כו' משא\"כ מי שטבעו כמו בהמה כמו שנולד אינו מן הישוב שבבחי' אדם כו' וד\"ל:"],[2300680164,"(ה) <b>ולשרקה</b> בני אתונו. הנה שרקה היא זמורת גפן ילדה ורכה שענביה מועטין ומעט יין בהם כו' וכתי' אנכי נטעתיך שורק כו' בחי' נקודת שור\"ק כו' כי הנה הגפן יש בו ב' סגלות והסגול הן האבות ב' נקודות למעלה וא' מלמטה והשורק ג' נקודות שלו הן זה תח\"ז כו'. וביאור הדברים יובן בעבודת ה' שכאשר עבודתו באהוי\"ר בהתלהבות והתקרבות הרי ימינא ושמאלא ובינייהו כלה כו' בבחי' סגול כדוגמת האבות וזהו בחי' גפן שנמשלה כנס\"י עד שכסו הרים צלה פי' לאחר שקיבלו התו' והמצות נתכסו גם ההרים הן האבות מן בחי' הצל המגין עליהן שהמה בחי' מקיפים עליונים שע\"י מעשה המצות כמ\"ש ה' צלך על יד ימינך כו' והוא צל של בחי' חושך העליון כמ\"ש ישת חושך סתרו והוא בחי' כתר עליון שאינו מושג כלל וכלל ונק' אדון הנפלאות כנ\"ל עד שהפלא נחשב ג\"כ בבחי' עשי' כו' ועליו אמר אני הוי' לא שניתי כי הוא למעלה מהפלא' חכמה כו' ואין בו שינוי מקודם השפעה לחכמה לאחר השפעה כו' וע\"כ גם ההרים שהן הסגול נתכסו ונעלמו אורם בבחי' הצל של הרי חושך הללו כו' וד\"ל. אבל שרק\"ה הוא כדוגמת נקודת השור\"ק ג' נקודות זה תח\"ז כו' היינו שאין התפעלות אלקו' בלבבו בבחי' קירוב כו' רק מרחוק ה' נראה לו וכו' עד שהוא מודה במוח בבחי' הודאה בלבד ומשפיל א\"ע מפני זה בבחי' ביטול כלומר מפני שמרגיש איך שהוא רחוק מה' הוא עומד מרחוק יותר כי כל שמודה בהודאה שבמוחו ביותר איך שהוא ית' קדוש ומובדל כו' וכדומה אז יפול לבבו בבחי' הכנעה וביטול מרחוק כמ\"ש וינועו ויעמדו מרחוק כו' והוא בחי' השור\"ק זה תחת זה פי' ההשפלה שמשפיל עצמותו למטה מטה מאוד כו' וד\"ל. והנה ג' נקודות שבסגול נהפך סדרן בשור\"ק להיות זה למטה מזה בקטנות השפלות אחר הקירוב כו' וזהו ואנכי נטעתיך שור\"ק כו' ואמנם לפי סדר הגידול של הגפן הנה בתחילה הוא שור\"קה וכשמתגדל נעשה גפן כו' כמו\"כ יובן הנמשל שבצאת בנ\"י ממצרים אשר בשר חמורים בשרם בחי' חמור דקליפה הוא חכמ' דקליפה שהי' בחרטומי מצרים שנק' פרא אדם כשהוא עיר כמ\"ש עיירים כו' שהי' מדריגת כנס\"י אז בבחי' שור\"ק בלבד כמ\"ש נטעתיך שורק שענין יציאתם ממצרים ג\"כ לפי ערך מדריגתם ולכך אמר בני אתונו בני ל' בנים כמ\"ש בנים אתם לה' כו' והיינו לאתהפכא חשוכא לנהורא בלבד שזה כענין ברא כרעיה דאבוה כו' בבחי' הקטנות דשור\"ק כנ\"ל והוא נהפך ונעשה מבחי' אתונו כשיצאו מקליפת מצרים שנק' אתון וחמור כו' וד\"ל וכשבני ישראל כבר נסעו ממצרים במ\"ב מסעות והגדילו פרים בענבים ויין כמ\"ש גפן ממצרים תסיע כו' כתי' אוסרי לגפן עירה שנהפך מעיר פרא אדם כו' להקרא אדם בשלימות כנ\"ל עד שכסו הרים צילה כו' וד\"ל. וזהו המשך הפסוקים אסרי לגפן עירה בזמן הגלות שבמעשה המצות בב' מיני יין המשמח ומשכר כו' עושים בחי' אדם הנק' עי\"ר ה' ע\"י שנכבס ביין שבגפן זה הלבושי' ובדם ענבים סותה לבושי הראש הנק' סותה כו' וזהו כבס ל' עבר לעשות השלימות שיהי' בזמן ימוהמ\"ש ואז חכלילי"],[2300680179,"עינים מיין כו' כאשר יהי' בהם בחי' אדם בשלימות כתי' כי עין בעין יראו כו' בלתי מסוה הפנים מפני שנתאדמו העינים מהיין המשמח והיין המשכר בבחי' גבורות ומס\"נ דבע\"ת כנ\"ל וזהו לאחר התחי' שיהי' זמן קבלת שכר של המעשה דהיום לעשותם שבימות המשיח כו' ואז כתי' עין לא ראתה אלקי' זולתיך כו' דגם מה שהנשמות נהנין בג\"ע עין לא ראתה עדיין מה שיראה עין בעין בזמן ההוא כו' ולכך נק' בשם עוה\"ב שעתיד להיות כו' וד\"ל. ולזה הטעם אמרו שיפה שעה א' בתשומ\"ט בעוה\"ז מכל חיי העוה\"ב כנ\"ל בענין היו\"ד שנברא בו העוה\"ב שהוא מ\"ש עין לא ראתה כו' וקיבול השכר הרי בא ונמשך ע\"י המעשה שקדמה בימות המשיח ושכר מצוה מצוה כו' וד\"ל:"],[2300680038,"<b>ביאור על הנ\"ל</b>\n(א) <b>להבין</b> שרשי הדברים הנ\"ל הנה שורש ענין גפן ממצרים תסיע כו' כסו הרים צלה כו' הוא בחי' שם ב\"ן שנעשית ראש לשועלים כו' ומבררת רפ\"ח ניצוצין בלילה בעוד שנותנת טרף לביתה כמ\"ש ותקם בעוד לילה כו' ולאחר הבירור מתעלי' למעלה מעלה מאוד בבחי' כתר עליון שלמעל' מן ההרים עליונים וזהו כסו הרים צלה כו' וכמ\"ש אשת חיל עטרת בעלה כו'. וכדי להבין כל זה יש להקדים לבאר תחילה ענין הבירור שלה ברפ\"ח כו' הנה אנו אומרים וקדושי' בכ\"י יהללוך כו' י\"ל למה נק' קדושים אך הענין ידוע שיש ב' מיני מלאכים יוצר משרתים ואשר משרתיו כו' דהיינו המלאכים שנבראו מן ו' ימ\"ב ואשר מתחדשים בכל יום משם ב\"ן והוא בהמה רבה דרביע על אלף טורין ושתת לון בגמיע' חדא כו' פי' שמרוח פיו ית' מתהווים נבראים חדשים מאין ליש בכל יום ובעוד לילה חוזרים למקורם ושתית לון בגמיע' כו' כלומר שמתכללים במקורם בבחי' ביטול המציאות כמ\"ש במ\"א והוא ענין הבירור שלהם מעה\"ד טוב ורע ע\"י גמיעה זו שנכלל הטוב שבהם באלקי' חיים ולכך נק' קדושי' שמשיגים בחי' קדוש הוי' וצועקים אי' מקום כבודו כו' ונכללי' בבחי' ביטול כו' וזהו שבכל יום ויום מתחדשים המלאכי' הללו הנק' קדושי' וע\"י בירור דשם ב\"ן המבררת אותם בכל לילה יהללו בכל יום כו' וד\"ל. והנה ישראל הם מקדשי שמך פי' שמעלים ומגביהים את שם ב\"ן הנק' שמך כידוע להיות בבחי' קדושה העליונה דכתר עליון כו' להיות כי הבירור דשם ב\"ן הנ\"ל א\"א כ\"א בהיות שם ב\"ן מבורר בעצמו מקודם בשרשו ומקורו כו' והוא ע\"י ישראל מקדשי שמך כו' כי ישראל הוא בחי' שם מ\"ה המברר ב\"ן כידוע ואח\"כ או' המלאכים קדושתם איה כו' וממילא נתעוררו בקדושתם ע\"י קדושת ישראל כי בירור שלהם ממילא נעשה אחר בירור דמ\"ה כו' וד\"ל. ועיקר הקדושה הוא שהוא ית' אדון הנפלאות דוקא דהיינו שהחכמה הנק' פלא אותי' אלף מאאלפ\"ך חכמה כידוע ג\"כ בחי' עשי' לגבי עצמי' אוא\"ס ב\"ה והוא קדוש ומובדל גם מן החכמה שמחי' כו' וד\"ל. ועתה י\"ל ענין הבירור דשם ב\"ן בעצמו כו' הנה כתי' יין המשמח אלקים פי' אלקי' הוא שם ב\"ן והוא ענין"],[2300680054,"<b>הגפן</b> שיש בו מבחי' הגבורות יין אדום ובחי' החסדים חמר חוורין כו' ושניהם ענין בירור ומיתוק הגבורות הקשות דנוג\"ה ע\"י יין המשמח אלקי' כי נכנס יין יצא סוד כו' מפני שבשמחה והעונג האלקי' שע\"י התבוננות הנק' יין המשמח בזה נמתק ונתברר הרע שבגופו החומרי מקליפת נוגה כו' כמו\"כ למעלה נמתק ונתברר אלקי' שם ב\"ן ע\"י היין העליון המשמח אלקי' בבחי' עונג העליון מכל הגבורות הקשות שיונקים ממנו כו' וזהו נכנס יין יצא סוד הגנוז באור עונג העליון כו' כמ\"ש במ\"א וד\"ל והיינו דוקא כשמתהפך חשוכא לנהורא ומרירא למתיקא כו' ע\"י השמחה אז משמח אלקי' כו' והוא ענין הבירור דשם ב\"ן עצמו הנק' אלקי' כידוע והנה עלי' המל' בחי' אלקי' לאחר הבירור שלה הוא בבחי' כתר עליון למעלה מבחי' פלא דחכמה והוא הנק' חושך כו' וזהו גפן ממצרים תסיע מבירורים דרפ\"ח שנפלו בנוג\"ה כו' ואח\"כ נתעלית מאוד בבחי' כתר עליון עד שכסו הרים צילה כו' למעלה משם מ\"ה שביררה הנק' הרים עליונים כידוע וד\"ל:\n(ב) <b>ולהבין</b> טעם הדברים הנה יש להקדים תחלה ענין כבס ביין לבושו כו' בהיות שיש ב' מיני העלאות מ\"נ דב' מיני יין הנ\"ל יין אדום דם ענבים כו' ויין חיור עתיק כו'. ויובן ענינם בהפרש שבין צדיקים ובע\"ת שההפרש ביניהם ידוע שהשמחה ועונג האלקי' בצדיקי' הוא מצד אלקו' לבד והוא בבחי' ההמשכה מלמעלה למטה בחי' גילוי אלקו' מן ההעלם כו' ע\"י התענגם על ה' במס\"נ שלהם כו' וכמ\"ש שמחו צדיקים בה' כו' כי שמחה זו מצד אלקו' מתייחסת לצדיקים בלבד מפני שהשגתם נפלאה באור א\"ס ומתענגים בה בבחי' גילוי ההעלם וכמ\"ש במ\"א וזהו בחי' היין הלבן שמגלה ההעלם בשמחתו כו' והוא מבחי' החסדים דע\"י כו' ואמנם בבעלי תשובה העלאת מ\"נ שלהם הוא מלמטה למעלה והיינו בבחי' מרירות וגודל עוצם התשוקה מרחוק כו' ונק' יין אדום מבחי' הגבורות כו' ואין שמחה זו שמצד היין האדום בבחי' גילוי ההמשכה אלא בהיפוך בבחי' הסתלקות ובחי' אור חוזר כו' ולכך נקרא דם ענבים כו'. והנה לנגד ב' מיני העלאת מ\"נ הללו מלמעלה למטה ומלמט' למעלה יש ב' מיני המשכות מ\"ד בב' מדריגו' הנ\"ל והן בחי' המקיפים של לבושי' במעשה המצות בהיות ידוע שהמצות שרשן בבחי' ארחין דגלגלתא כו' והגלגלתא היא שורש כל המקיפים בדרך כלל כמשל העטרת על הראש שהיא מקפת הגלגלתא ג\"כ דהיינו גם עצם הגלגלתא כו' והנה ידוע עצם הגלגלתא כלול מתרי\"ג ארחין היינו תרי\"ג מקיפי' פרטים בתרי\"ג מצות כו' ונחלקי' דרך כלל לב' מיני מקיפים א' מקיפי הראש והב' מקיפי הגוף עד\"מ לבושי הגוף שאינן דומין ללבושי הראש כו' ומקיפים הג' ראשונות חב\"ד שבראש הוא בבחי' עצם הגלגלתא ומקיפי הז' התחתונות שבכללי' הגוף רמ\"ח כו' ג\"כ נמשכי' מגלגלתא אך כללות כולם נמשכים מעשרת שעל הגלגלתא המקיף הכללי והוא מקור כל המקיפים וד\"ל וא\"כ מובן שמקיפי חב\"ד שבראש נמשכים ע\"י העלאת מ\"נ דבע\"ת דוקא ומקיפי הז\"ת שבגוף נמשכים ע\"י העלאת"],[2300680070,"מ\"ן דצדיקים כו' שהרי המ\"ד לפי אופן המ\"ן הוא וכמו שהמ\"נ דצדיקי' מלמעל' למטה כך המ\"ד שלהם מלמע' למט' בבחי' גילוי העלם אור חסד עליון דכתר וגלגלתא בלבושי הגוף כו' עד\"מ השמחה של חמר חוורין עתיק כו' והמ\"ן דבע\"ת שהוא בבחי' גבורות דאו\"ח כנ\"ל גם המ\"ד שלהם בבחי' מקיפים דאו\"ח שהן לבושי השערו' שבראש שהן בבחי' או\"ח וכדומה לזה יובן ענין המסוה שעל פני הראש שהוא בחי' לבושי מקיפים דג\"ר שבראש כו' וד\"ל וזהו הטעם שבמקום שבע\"ת עומדי' אין צדיקי' יכולים לעמוד דהיינו במקיפים דג\"ר שבראש שאין הצדיקי' בשמחתם שבבחי' מקיפי' דז\"ת בז\"א יכולים לעמוד שם וד\"ל. וזהו שורש ענין הפסוק כבס ביין לבושו ביין הוא חמר חיוורין כו' נכבסו לבושי המקיפי' דז\"ת שע\"י הצדיקי' בשמחה של מצות שהן עושים כו' ובדם ענבים סותה היינו בחי' מסוה הפנים שהוא לבוש המקיף דג\"ר שבראש שע\"י העלאת מ\"ן דבע\"ת בבחי' מרירות וגבורות התשוקה מרחוק הנק' דם ענבים כו' וד\"ל. ועתה יובן טעם הדברים הנ\"ל שעלי' המל' דשם אלקי' בבחי' צל חושך העליון בחי' מקיפים דאו\"ח עד שכסו הרים צלה כו' לפי שיין המשמח אלקי' שע\"י בע\"ת בחי' יין אדום הרי מעלת הזהב על הכסף כו' עד שנתעלית המל' בבחי' מקיפי' דגלגלתא עצמה הנק' עטרה שעל הראש מקור כל המקיפים מפני המקיפים דאו\"ח הנ\"ל שמעלים ועולין עמה כו' משא\"כ מקיפים דז\"ת שיורדי' ואין עולין לכך כסו הרים הן ז\"ת בצלה צל המקיפי' דגלגלתא כו' עד שגם ענפיה המסתעפי' ממנה הן ז' מד\"ר ארזי אל המה שמבריחי' מן הקצה אל הקצה מבחי' קו וחוט של אוא\"ס שמאיר בגלגלתא כו' לפי שנעוץ סופן בתחלתן כו' וזהו שאשת חיל עטר' בעלה מטעם הנ\"ל וד\"ל:\n(ג) <b>והנה</b> להבין המשך הפסוקי' זא\"ז אסרי לגפן כו' כבס ביין כו' חכלילי עינים כו'. וגם להבין שורש ענין אסרי לגפן ולשרקה כו' ענין ההפרש בין סגול לשורק כו'. יש להקדים תחלה שורש ענין התחלת הדברים שהיום לעשותם כו' לא יהי' אלא לימהמ\"ש כו'. הנה כתיב ואדם אין לעבוד את האדמה בהיות שבחי' אדם הוא כמ\"ש אדמה לעליון כו' וכמ\"ש נעשה אדם בצלמנו כדמותנו ואז וירדו בדגת הים. וזהו ואדם אין לעבוד כו' פי' כי עד\"מ כשאדם עומד במקום נמוך לא יוכל להשיג בידיו דבר שעומד במקום הגבוה הרבה מראשו גם כשיפשוט ידיו אך כשעולה במקום הגבוה יוכל להוריד ידיו למקום הנמוך ולהגביה הדבר שעומד שם אצלו כו' כי כל היותר נעלה יותר יוכל לירד למטה מפני שידיו ארוכות לפשוט אותם גם לנמוך מאוד או עד\"מ מי שהוא חכם ביותר יוכל להשפיל א\"ע גם לקטני הדעת להבינם מדע וכיוצא בזה יובן הנמשל בהיות שאדם הוא אותיות אדם דוד משיח כידוע ולפי שהי' אדה\"ר בקטנות המוחין בירידה גדולה ע\"כ גרשוהו מג\"ע העליון לעבוד כו' כי לא הי' ביכולתו לברר ולהפך חשוכא לנהורא כו' דהיינו בירורי' דרפ\"ח ניצוצי' שנפלו בנוגה וזהו לעבדה לבער הקוצים כו' מפני שלהגביה ולהעלות דבר נמוך צריך שיהי' יותר נעלה"],[2300680086,"בגדלות המוחין כמשל הנ\"ל וגם בימי דוד שהי' כנס\"י בבחי' אדם קצת יותר נעלה ממדריג' אדה\"ר ג\"כ לא הי' ביכולתם להעלות הדברים תחתונים דקליפת נוגה ע\"י הקרבנות כו' מפני שלא הי' בחי' אדם שלהם בצלמנו ממש בבחי' כתר עליון אדמה לעליון כו' רק בבחי' ז\"א בלבד כידוע שהי' היחוד זו\"נ פב\"פ בזמן בית ראשון כו'. אבל לימהמ\"ש דכתיב בי' ישכיל עבדי ירום ונשא כו' שהן ה' עליות הנוק' עד שהיא עטרת בעלה בחי' מאד אותיו' אדם בהיפוך אתוון כידוע והוא בבחי' כתר ועתיק כמ\"ש כסו הרים צלה כו' ואז נתקיים בה נעשה אדם בצלמנו כדמותנו ממש אדמה לעליון כו' לכך עיקר מעשה המצו' בזמן ההוא לפי המשל הנ\"ל שכשעומד במקום גבוה יותר יוכל להשפיל ידיו הארוכים להגביה את הנמוך כו' כמו\"כ בהיות כנס\"י בבחי' כתר עליון כמ\"ש וגבה מאוד כו' אז ירדו בדגי הים ועוף השמים כו' דהיינו לברר בירורי נוגה היותר נמוכי' ולהעלותם בקרבן כמצות רצונך כו' משא\"כ עכשיו אדם אי\"ן לעבוד כו' וד\"ל. וזהו הטעם שהיום לעשותם כו' כמצות רצונך לא יהי' אלא ליוהמ\"ש דוקא ולמחר לקבל שכרם היינו למע' מבחי' המצות שבארחין דגלגלתא אלא בבחי' עצמי' אוא\"ס ב\"ה שלמעלה מגלגלתא הרבה כי הרצון שבכתר הוא נמשך בבחי' הארה בעלמא מן המצות דאא\"ס שהרי עצמי' אוא\"ס גם בעל הרצון לא יתכן לקרותו כמ\"ש במ\"א וד\"ל והיינו טלא דבדולחא דנטיף להחיות מתים לאחר ימות המשיח שזה יהי' שכר המצות וד\"ל. ובזה יובן למה אמרו כבס ביין כו' ל' עבר לפי שתיקון הכביסה ביין לבן ואדום בצדיקי' ובע\"ת הנ\"ל אין זה אלא הכנה בלבד לימות המשיח כדי שיהי' בבחי' אד\"ם אותיות מא\"ד שהוא בבחי' גלגלתא כו' וד\"ל. ועתה יובן פי' דברי הפסוקי' אסרי לגפן עירה כו' פי' עירה ל' עיר פרא כו' בהיות שעשר כתרין דקליפת נוגה נק' פרא אדם יולד והיינו כמו שנולד בטבעו המוטבע בנפש הבהמית שירד ע\"י שבה\"כ כו' וכשנהפך חשוכא לנהורא כו' ונעשה אדם בשלימות כמו לימות המשיח כנ\"ל נק' עיר\"ה עיר ה\"א דהיינו בחי' מל' הנק' אדם תתאה וכענין אימתי גדול כשהוא בעיר אלקינו כשהמל' נבנית בבנין שלם דוקא והן בחי' האותיות כשהן במילואן אבנים בונות כו' כמ\"ש בס\"י וד\"ל. והמשך ד' הפסוקי' כך הוא אסרי לגפן היינו כשהגפן שם ב\"ן אסור וקשור בידי חיצונים דנוגה הנק' עיר פרא כו' והן בחי' החרצנים והזגים שבענבי הגפן כו' וע\"י דריכה ברגל יוצא היין מהם והוא המשובח ביותר דהיינו ברגליות דוקא לפי שכל שנפל למטה בשבירה יותר גבוה הוא בשרשו ביותר כידוע ולכך כשנהפך חשוכא כו' נעשה עיר\"ה עיר אלקי' כו' לפי ערך הירידה כן ערך העלי'. משא\"כ לשרקה שהוא גפן רך בשנים שיינו מועט גם בהתהפכות לטוב לא יהי' ממנו עיר אלקי' בשלמו' הבנין אלא בני אתונו פי' בני שם ב\"ן דקטנות וכענין ברא כרעי' דאבוה כו' וד\"ל:\n(ד) <b>ושרשי</b> הדברים הנ\"ל הנה יש להקדים ענין הידוע בכהאריז\"ל דלפעמים יחוד זו\"נ פב\"פ שווין בקומתן כו' ולפעמים מלבשת עד החזה בלבד ולפעמים"],[2300680102,"בקטנות גדול יחודם והוא בנצח והוד כמאמ' איהו בנצח ואיהי בהוד כו'. וביאור הדברים הנה כשמלבשת עד החזה כו' עד ימין ושמאל תפרוצי כו' שיחבק לה בעלה בין תרין דרועין כו'. ובעבודת ה' יובן זה כאשר יתפעל האדם בהתלהבות אהבה או יראה כו' הנה ירגיש וישיג את אלקי' חיים בלבבו בבחי' השגה ותפיסה ע\"י אהוי\"ר והו\"ע חיבוקו שנחבקה נפשו בין תרין דרועין דבעלה שם מ\"ה בימין ושמאל העליוני' כו' כתי' ימין ושמאל תפרוצי כו' וד\"ל. אך כאשר אין האדם מתפעל באהו\"י ואיננו מדובק באלקי' חיים בבחי' קירוב אך רק מרחוק ה' נראה לו בבחי' הודאה בלבד דהיינו התפעלות השכל בלבד איך דכולא קמי' כלא כו' ויתכן אליו הביטול כו' וכיוצא ולא נגע הענין בלבבו כו' זהו בחי' הוד דהודאה ובינ\"ה עד הוד אתפשטת כלומר כ\"כ כח הבינה וההתבוננות מתפשט עד שיסתעף ממנה מדריג' תחתונה דהודאה ג\"כ כנ\"ל וכמו\"כ יובן למעלה דאיהו בנצח ואיהי בהוד היינו כשהמל' איננה בבחי' קירוב באוי\"ר כו' אלא בבחי' הודאה בלבד זהו איהי בהוד והמשכת המ\"ד שלה ג\"כ לפי ערך והוא מבחי' נצח דז\"א בלבד וזהו איהו בנצח וזהו יחוד שלהם היותר חיצוני' כו' וד\"ל. וזהו ענין ההפרש בין גפן לשורקה כו' בהיות שההפרש שבין סגול לשורק אינו אלא שג' נקודות הסגול ב' מלמעלה וא' מלמטה וג' נקודות השור\"ק זת\"ז ובעקמומית כו' והענין הוא כמ\"ש במ\"א בענין שיר על היין שיש ג' מדריג' בקול הא' מלמעלה למטה והב' מלמטה למע' והג' הממוצע המחברם כו' והו\"ע הסגול ימין ושמאל ואמצע כו'. והיינו מ\"ש למעלה בענין יחבק לה בעלה כו' ימין ושמאל כו'. וזהו לגפן בב' סגלות מלמטה. אבל לשורק\"ה כאשר לא נגדל הגפן כ\"כ אינו בבחי' סגול אלא בבחינת שור\"ק שזה תחת זה דהיינו בבחי' הודאה בלבד וג' נקודות מורים ההשפלה שנשפל בעצמו מחמת ההודאה וזהו שהן זת\"ז ולצד ימין דנצח כו' וד\"ל. להיות כי נצח והוד הן תרין שוקין כידוע ע\"כ נאמר ולשרקה בני אתונו פי' בני הן נו\"ה תרין שוקין דאיהו בנצח כו' והיינו כאשר המל' בבחי' שורק בלבד וד\"ל. וענין אתונו כו' הן עשר כתרין דקליפת נוגה שבשר חמורים הם כו'. ויובן ביאור הדברים ע\"י הקדמה להבין מה ששלח יוסף ליעקב עשר אתונות נושאת בר ולחם ומזון לאביו לדרך כו' כי הנה ידוע שנפלו בשבירה מן האורות שקדמו לפני האצי' כו' וגבוהים מאוד במדריגה אך שנתגשמו בקליפת נוגה. ואמנם כשהם מתבררים הרי הם גבוהים מאוד מצד עצמם ולכך אמר שעשר אתונות דנוגה נושאות בר ולחם ומזון ליעקב בעל עולם האצילות כי גבוהים ממנו בשרשם לאחר הבירור וזהו לאביו לדרך וד\"ל. ועיקר הטעם כמ\"ש חיל בלע ויקיאנו שבתגבורת הקדושה האלקי' גם מה שבלעו הקליפות יניקה מסיבת הנפילה כו' יקיאו ויהי' למזון ולחיות ולתוספת מרובה כו' וכענין העורבים שכלכלו את אליהו וזה פלא למה ציוה ה' לעורבים דוקא לכלכלו. אך הענין הוא שהעורבין הם בבחי' כתרין דנוגה הטמאים ואכזרים המה כו' וכאשר אליהו הי' מרכבה לשם ב\"ן בגמטרי' אליהו בחי'"],[2300680118,"מל' דאצי' הרי נתברר מהם הטוב הגנוז בהם שנפל בשבירה כענין חיל בלע כו' נמצא בהם להיות למזון ולשפע לאליהו ולכך ציוה את העורבים דוקא לכלכלו וד\"ל וכענין הזאת הי' בי' חמורים וי' אתונות ששלח יוסף ליעקב לרמז לו שיוכל לברר כל טוב מצרים ולמצוא בהם לחם וב\"ר כו' וד\"ל. ועד\"ז יובן גם כאן ל' לשורקה בני אתונו פי' שאתונות דכתרי' דנוגה יתהפכו לטוב וימצא מהם השפע אלקי' בבחי' שור\"ק עד שנק' בני ברא כרעי' דאבוה בחי' נו\"ה כו' והוא שם ב\"ן דקטנות כו' מפני שיינו מועט כו' דבחי' הודאה בלבד. משא\"כ ע\"י התהפכות עיר פרא אדם כו' נעשה עי\"ר ה' בבחי' גדלות הבנין דאדם כנ\"ל וד\"ל:\n(ה) <b>ושורש</b> ענין חכלילי עינים מיין כו' היינו לאחר שזכר איך שאסר לגפן כו' ונהפך לעיר ע\"י שכבס ביין לבושו כו' שהוא מעשה המצות כנ\"ל אמר חכלילי עינים פי' שנתאדמו העינים מבחי' יין האדום דוקא כו' בהיות שמבואר למעלה שמקיפי הראש נעשים מבעלי תשובה דוקא ואמנם עכ\"ז בבחי' לבוש המקיפי' הם מתגלי' וזה יהי' לימות המשיח אבל לתחיית המתים כתי' עין בעין יראו כו' בלתי לבוש המסוה וכמ\"ש הביטו אליו כו'. וזהו חכלילי עינים שיתאדמו מפני הבטתם עין בעין בלתי לבוש המסוה שלא יכיל כלי העין למיסבל כו' וד\"ל. וכ\"ז למה מפני שלבן שינים מחלב פי' חלב הוא לאחר ששלמו ימי היניקה בחלב שנגדלו המדות ע\"י החלב כידוע ומבואר במ\"א ואז זמן צמיחת השינים והטעם לזה בהיות שעיקר מציאת החלב נעשה מדם שנעכר ונעשה חלב כידוע. וביאור הדברים הוא לאכללא שמאלא בימינא הגבורו' דיין אדום הנ\"ל דמדריג' בע\"ת בחסדים דיין לבן בצדיקים והיינו שלא יהיו מפורדים זה בפ\"ע וזה בפ\"ע ע\"ד דוגמא כששמח בהתבוננות בעונג האלקי' במדריג' הצדיקי' אין בלבבו בשעה ההיא מבחינת מרירות והתשוקה מרחוק כמדריג' הבעלי תשובה כלל וכשהוא במרירות ושפלות אין בו בשעה ההיא מבחי' השמחה כלל שזה בחי' פירוד בין החסדי' והגבורות כו' אך כשנכללי' זה בזה והי' לאחדים היינו כאשר תהי' השמחה עם המרירות מעורבים בתכלית בתנועה וסקירה אחת בלתי פירוד כלל כו' אז נכלל שמאלא בימינא ודם נעכר ונעשה חלב הוא בחי' הגדלת השכל במדות כמו שנגדלים המדות בתינוק היונק מחלב כו' כמ\"ש במ\"א וד\"ל וכמו\"כ יובן למעלה דמוחין דז\"א נגדלו בימי היניקה מחלב דאימא עילאה כו' ע\"י שנכלל יין אדום ונעשה חלב דאימא כו' מהעלאת מ\"ן דבע\"ת וכדומה לזה בירורי רפ\"ח שנפלו כו' וד\"ל ואז זמן צמיחת השינים מפני שליבון השינים בא מן החלב לפי שענין השינים הן ל\"ב נתיבות חכמה שנמשכי' לאחר ששלמו ימי יניקה דוקא כו' בהיות שאנו רואים כי כאשר יטחן המאכל בשיניו דק דק יפרד במעיים הפסולת שלו ויוצא לחוץ והטוב שבו יעוכל ונהפך לדם כו' וכאשר לא יטחן בשיני' אלא יבלענו כולו כא' מעורב הטוב עם הפסולת לא יתעכל כלל ויזיק לגופו כו' ונמצא פעולת השינים הוא לברר ולחלק המאכל כו'. וכיוצא בזה יובן בחכמה שיש מי"],[2300680134,"שלא ישכיל השכל בכי טוב אם לא ידבר ויפרשנו בפרטי הענין בריבוי דברי' כמשל הלועס ממש כן ילעוס בפה לדבר דברי השכל הרבה פעמים עד שישכילנו הטיב ויוכל להכיר בין הטוב והשקר והפסולת כו' ואז ימצא מרגוע לנפשו השכלי' לקבענה בלבו להיות לו למזון ולשפע כו' ואם לא הי' מפרשה בפה הטיב לא ישכילנו כלל ולא יבחין בין טוב לרע ולא יוקבע בנפשו כלל כו' והיינו בחי' ל\"ב נתיבות החכמה שיורדים וטוחנין את השכל כמשל השינים הטוחנין המאכל והוא הטעם שנקרא גירס\"א כמשל הגריסין שנטחנו כו' כמ\"ש במ\"א וד\"ל. ולהיות כן זמן צמיחת השינים דל\"ב נתיבות החכמה אחר זמן היניקה מן החלב מפני שנתרבה המוחין כ\"כ עד שיכול לירד ממנו ל\"ב נתיבות בליבון השינים לברר וללבן כו' שהוא ענין ליבון הלכות הנק' בר\"מ דהיינו ליבון ובירור ההלכה להבחין בין טוב לרע כו'. ובעבודת ה' היינו בחכמה אתברירו לאתהפכא חשוכא לנהורא כו' לזרוק הפסולת מן כו' ולבחור בטוב ולא להטעות א\"ע מעורב אמת ושקר יחדיו כו' כמו המטעה א\"ע כו' וד\"ל. וזהו חכלילי עינים להביט עין בעין כו' מפני שכבר ליבון השינים בהגדלת החכמה מן החלב דיניקה כו' וערך אדמומי' העינים במוחין דגדלות הוא לפי ערך שלימו' החלב דיניקה כידוע וד\"ל והיינו רק לפי ערך הדם שנעכר ונעשה חלב כן יהי' ערך האדמומי' והליבון כו'. וזהו המשך הפסוקי' אוסרי לגפן כו' וכבר כבס ביין כו' ובדם ענבים סותה אז חכלילי עינים מיין ולבן שינים מחלב וד\"ל:"],[2300680039,"(א) <b>חכלילי</b> עינים מיין ולבן שינים מחלב. הנה ידוע שהתורה נק' בשם יין וחלב כמ\"ש לכו שברו ואכלו בלא כסף כו' יין וחלב. ויש להבין למה נק' בשם ב' דברים הללו דווקא יין וחלב. והנה יש להקדים ענין א' הידוע שיש ב' מיני אהבות אה\"ר ואה\"ע מלמעלה למטה כמו אהבת עולם אהבתיך כו' וכן אה\"ר אהבתנו כו' וכך יש ב' אהבות הללו מלמטה למעלה מכנ\"י לקוב\"ה והיינו בחי' אה\"ר שנק' אה' המוסתרת בלב כאו\"א מישראל ואה\"ע הבאה בגילוי בלב כאו\"א בכל חו\"ח לפום שעו\"ד. והענין הוא בפי' אה\"ע בכנ\"י שזהו באה מצד העולם והוא מחמת ההתבוננות בגדולת הבורא ית' בהתהוות ריבוי רבבות עולמות עליונים ותחתונים געה\"ע וגעה\"ת והיכלות מלאכים רבים לאין שיעור כמ\"ש היש מספר לגדודיו כו' והכל רק מבחי' מלכותו ית' דכתיב מל' מכ\"ע שמחי' כל העולמות דבי\"ע מאין ליש וכמ\"ש ואתה מחי' את כולם וזהו הנק' בחי' ממכ\"ע שממלא אור ושפע אלקית בתוך כ\"ע בגבול ומדה ונק' כהפב\"נ ממש כידוע וזהו ענין חידוש מע\"ב בכל יום ויום וכאשר יתבונן האדם היטיב אמיתית הענין הזה שכח אלקי ממש מהווה כל הברואים בכל רגע ורגע מחדש חיותם מאין כו' עי\"ז יתפעל בלבו באה' נגלית המושכת את לבו לאהוב ולדבקה בו ית' שהוא עיקרא ושרשא דכ\"ע ונק' מקור חיים ואלקים חיים ומלך עולם ולא יחפוץ בטפל וכמ\"ש מי לי בשמים כו' וזהו בחי' יחו\"ת בבשכמל\"ו ועוד יש התבוננות למעלה מזו והוא בבחי' יחו\"ע דשמע ישראל"],[2300680055,"<b>בבחי'</b> סוכ\"ע כידוע דמלבד שהוא עצמו ית' קדוש ומובדל בערך מכל ההשתלשלות אף מהיות נק' מקור חיים כנ\"ל ונק' סובב כ\"ע אלא גם בבחי' ממכ\"ע עצמו הוא קדוש ומובדל שנק' קדוש בשמים ובארץ לפי שגם בחי' הארה זו שמחי' את כל העולמות אין לעולמות ונבראים ערוך לו כלל וכלל להיות ידוע שאין התפשטות הארה זו בעולמות כדמיון אור וחיות הנפש בגוף שהנפש עצמה מתפעלת ממקרי הגוף לפי שחיות הנפש שבגוף הוא בחי' חיצוני' והגשמת חיות הרוחני שבנפש כגשמי' דצומח עשב מכח הצומח הרוחני וכה\"ג בדם הוא הנפש כידוע אבל למע' באלקים חיים א\"א לומר כן דאין בו שינוי והתפעלות כלל מחיות העולמות כמו שאמר אתה הוא קודם שנבה\"ע כו' וכתיב אני הוי' לא שניתי כו' כידוע לפי שגם אור האלקי המהווה כל העולמות הוא בבחי' מקיף מרחוק ולא בא בבחי' קירוב הערך ככה\"פ בנפעל ממש או כחיות הנפש בגוף אלא רק מבחי' שמו ית' כשם המלך על אנשי המדינה שאין זה ממהותו כלל רק התפשטות שמו לבד וכן אמר הודו על ארץ ושמים כו' והוא בבחי' הוד דמל' כמ\"ש מל' כו' ונק' מלך מרומם לבדו מתנשא מימו\"ע כו'. ואמנם המשכה ושפע זו מבחי' שמו שם אלקים הוא שמתחדש החיות לכל העולמות בתמידות בלי הפסק כלל וכלל וכמ\"ש מחדש בכ\"י מעשה בראשית כו' לפי שיש בזה בחי' א\"ס ממש וזהו שאומרי' ישתבח שמך לעד מלכנו פי' שמך הוא בחי' מל' דאצי' בבי\"ע משובח ומפואר בכל המלאכים ועולמות ומזה נמשך שפע חיותם בתמידית ונצחי' וזהו לעד מלכנו והכל רק בבחי' שם לבד וד\"ל. (וכמו\"כ במל' דא\"ס שלפני הצמצום הראשון כמ\"ש אני ראשון ואני אחרון כידוע שאין ערוך כלל לנאצלים לגבי מהו\"ע ית' ונק' שם ומל' לבד כנ\"ל במל' דאצי' בבי\"ע ממש) וזהו שאומרי' יש\"ר מברך לעלם פי' שמי' רבא הוא שמו הגדול הוא בחי' סוכ\"ע בכלל שלמעלה מבחי' השפעה אלקית הנק' מקור חיים וכמ\"ש כי עמך מקו\"ח וכל עיקר התפעלות הלב באה\"ר צ\"ל לבחי' סוכ\"ע דווקא שנק' שם הוי' בכלל וכמ\"ש אליך הוי' נפשי אשא אליך דוקא והוא הנקרא שמי' רבא שהוא קדוש ומובדל ומרומם לבדו ואינו נתפס כלל בעולמות כנ\"ל וע\"כ גם לענין הברכה אנו מבקשים ומתפללים שיהא שמי' רבא זה (שהוא בחי' מל' דא\"ס בכלל) מברך שעתה אינו אלא בחי' שם לבד שיבא מן ההעלם דמקיף לידי גילוי שזה עיקר ענין הברכה כידוע שיתברך ממקורו הנעלם לבוא לידי גילוי בעולמות כמו שיהי' לע\"ל דכתיב ונגלה כבוד ה' וראו כ\"ב כו'. וזהו עיקר ההפרש בין ברכה להודאה שההודאה אינו רק ההסכם מרחוק שמודה על האמת כמו שהוא שכך הוא באמת ונתאמת אצלו בכלי מוחו ולבו בבירור גמור מאוד איך שהוא ית' סוכ\"ע ומתנשא מימו\"ע כו' אמנם כדי שיהי' ענין זה עצמו דבחי' סובב בא לגילוי ממש בנפשו. כמו שיהי' לע\"ל וראו כ\"ב כו' כמו בבחי' ראי' חושית ולא בהסכם והודאה לבד זהו כאשר נגלה שם ה' ומתברך בכל עולמות וזהו עד\"מ הבריכ' שמתמלאת ממקור' מן המעין או הנהר שלזה נק' בריכה ל' ברכה והמשכה כך אמר דאיהו ברוך ואיהי ברכה שזהו"],[2300680071,"בחי' הברכה בשם הוי' סובב שיבא לידי גילוי ממש בג' עולמות דבי\"ע. וזהו לעלם ולעלמי עלמי' ג' עולמות וגם כפשוטו ל' נצחי' כידוע וד\"ל:\n(ב) <b>והנה</b> עד\"ז בג' עולמות בפרט שזהו כמשל ג' מדריגות דמח' דו\"מ דעולם הבריאה הוא בבחי' אותיות המח' ומבחי' אותיות דמח' נכנס בתוך הדיבור וע\"כ א' ברוך ה' מן העולם ועד העולם שזהו מעלמא דאתכסי' עולם המח' לעלמא דאתגלי' עולם הדיבור וזהו כללות ענין הברכה והיינו דווקא ע\"י ישראל שמברכים וממשיכים מן ההעלם לגילוי וכמ\"ש והייתם ברכה בקרב הארץ כו' וזהו שהשרפים אומרים קדושה כו' שקדוש ומובדל מהיות גם מקור לעולמו' והוא בחי' סוכ\"ע והאופנים אומרים ברוך שיומשך מהעלם דסובב לגילוי כנ\"ל (וע\"כ נק' קדוש וברוך כמו ל' הגמ' הקדב\"ה כידוע). והנה ידוע שעל יסוד זה הוסד כל ענין פסד\"ז שהוא רק להזכיר שבחי' הבורא ית' בקול ודיבור בפה דוקא וכמ\"ש רוממות אל בגרונם דוקא כדי שע\"י הדיבור של אדם למטה יומשך למעלה מבחי' ההעלם לגילוי בבחי' קול ודיבור העליון שמגלה מצפון המח' וזהו ענין הלל וברכה הלל בפסוד\"ז בקול ודיבור וברכה בויברך דוד ובשתים לפני' והברכה הוא ענין ההמשכה ממש מן ההעלם לגילוי כנ\"ל וד\"ל. וכ\"ז אינו רק הכנה לק\"ש דהיינו לאחר שנתעורר למע' להיות בחי' גילוי דסוכ\"ע למטה ע\"י ההלל וברכה כנ\"ל הנה זה בא בדרך פרט בק\"ש ביחו\"ע בפ' ראשון דשמע\"י דהנה ידוע בפי' שמע שהוא לשון הבנה והבחנה בבינה שבלב כמו דבר כי שומע עבדך כלו' מבין ולא שומע לאזנים לבד ואו' זה לניצוץ האלקי שנק' ישראל שישמע ויבין היטיב ויכיר ישראל זה איך שהוי' אלקינו ה' אחד והענין הוא כידוע בפי' אחד החי\"ת הוא ז' רקיעים וארץ שהוא בחי' מע' ומטה בכלל והד' הן ד' רוחות העולם מזרח ומערב כו' וזהו שאמ' תמליכהו בשמים ובארץ וד' רוחות העולם תו לא צריכת כו' להיותו כולל בחי' מקום שהוא בחי' ו\"ק העליונים ברוחניות דהרקיעים וארץ וד' רוחות הגשמיים יש להם שרש ברוחניות עד בחי' ו\"ק דאצי' (וע\"כ אומרים ברוך המקום ברוך הוא כו' וא' דהוא ית' מקומו ש\"ע ואין העולם מקומו ע\"כ אומרי' ברוך כ' הוי' ממקומו דוקא) וכידוע דהשתלשלות דבחי' ו\"ק דמקום בא בבחי' עו\"ע עד כמה מיני מדריגות בכל עולם לפי מדריגתו עד רום המעלות כמו הנה מקום אתי ממש כו' והמקור הראשון לבחי' התחלקות דמקום העליון יותר זהו ענין א' דאחד שהוא הנק' אלופו ש\"ע בכל עולם בפרט ואלופו ש\"ע בכללות וזהו א' דאחד שהוא אלופו דחי\"ת וד' שהן כוללים לבחי' מקום דו\"ק מעלה ומטה מזרח כו' וע\"כ צריך להאריך בד' דאחד להמשיך בו מבחי' אלופו ש\"ע כמ\"ש תמליכהו כו' וד\"ל וענין יחו\"ת דבשכמל\"ו זהו כח האלקי הבא בג' עולמות דבי\"ע והארה זו נמשך בג' מדריגות שם כבוד מלכותו כו' ושרש הארה זו דבחי' המל' בבי\"ע מקבל מבחי' ד' רבתי דאחד שהוא בחי' אחרונה שבאלופו ש\"ע דאצי' שזהו מל' דאצי' בבחי' אצי' ד\"ר העולם דאצי' כו' ומשם נמשך להיות ממכ\"ע שזהו ענין הברכה מן ההעלם לגילוי וזהו ברוך שם כבוד מלכותו"],[2300680087,"שיתחבר שם מל' דאצי' בבי\"ע כנ\"ל בפי' מן העולם ועד העולם כידוע וד\"ל. והנה אחר ההתבוננו' היטיב ביחו\"ע דשמע ישראל כנ\"ל יכוין למסו\"נ באחד דאלופו ש\"ע הנ\"ל והוא כשמאריך באחד דוקא וענין מס\"נ זו היא בחי' התכללות הנשמה האלקי' כניצוץ הנכלל במקורו בשלהבת כמ\"ש שמע ישראל דוקא ואח\"כ יתפעל באה' ורצון בפסוק ואהבת את הוי' אלקיך בכל לבבך ובכל נפשך שזהו מסירת הרצון שנק' גם הוא בשם נפש כידוע וענין אה' ורצון זה היינו שיהי' לאדם רק רצון א' לאביו שבשמים שזהו שדקדק לומר בכל לבבך כלומר לב א' ובכל נפשך וכל זה ריבוי לרבות כל הרצונות שיהיו מתהפכים כולן רק לה' לבדו וכמו מי לי בשמים ועמך כו' כלה שארי כו' והיינו בכל לבבך ב' יצריך שיתהפך גם היצה\"ר שבחלל השמאלי ולא יומשך אחר רצון זר בלתי לה' לבדו שזהו הנק' לאהפכא חשוכא לנהורא ומרירו למיתקא כו' וזהו ואהבת ב\"פ אור נגד ב' בחי' מס\"נ הנ\"ל וד\"ל:\n(ג) <b>והנה</b> כ\"ז נק' בחי' אה\"ע דכנ\"י שבאה התפעלות האה' והרצון בהם מצד ההתבוננות בעולמות דהיינו עלמא דאתכסיי' ואתגליי' שבכלל זהו בחי' סובב וממלא שמכוין בפסוד\"ז וביח\"ע ויחו\"ת דק\"ש כנ\"ל (וכמו\"כ מלמעלה למטה אנו אומרים אהבת עולם אהבתנו כו' כנ\"ל) בענין אלופו ש\"ע כו' ולזאת ודאי מובן שאהבה כזו יכולה לבא בכאו\"א לפום שעו\"ד להתלבש בנפשו במוחו ולבו בבחי' אור וכלי דהיינו שתוכל הנפש להכילו ולהגבילו בתוכה כפי אשר יוכל שאת בכלי מוחו ולבו להיותו בא בבחי' גבול ומדה מצד ההשתלשלות דסובב וממלא בלבד כנ\"ל ומזה הטעם אנו רואים שהתפעלות אה' זאת חולפת ועוברת מיד שיפסק כמעט רגע מהעמקת דעתו ולבו בהתבוננות ויסיח דעתו לחשוב מחשבות חוץ בעניני עוה\"ז ודאי מיד יפול לבו מאה' אלקי' זאת עד שצריך לחזור ולהעמיק דעתו ולבו ביגיעה גדולה בהתבוננות מחדש ויתפעל מחדש באה' האלקי' כו' לפי שיש באה' זו גבול וכליון מאחר שנלקחה מצד ההשגה המצומצמת שבמוחו וידוע דאזלעו\"ז עשה האלקי' דכמו שיש אה' דקדושה האלקי' כמ\"כ ממש בהסיר לבו ודעתו ויתחיל לחשוב בעניני גופני' מעולם הפירוד יפול באה' זרות דקליפה כו' וזהו כי קצר המצע כו' שנלאה כלי הלב מהכיל ב' מיני אהבות הפכיי' הללו בשעה אחד ואע\"פ שמיד שיפנה לבבו ויטרד מחשבתו בעסקיו חולפת ועוברת התפעלות האה' האלקי' דקדושה כי לא ישכנו כא' אבל האה' הזרה שנכנסת מיד במקומה היא היפך גמור מאה' דקדושה ואיך יוכל לעלות נפשו באחד אמתי הרי אמר מי יעלה בהר ה' נקי כפים ובר לבב דוקא כידוע כו' וד\"ל. וכ\"ז מצד שאה\"ע הנ\"ל בא בבחי' גבול ומדה בנפש לפ\"ע ההשגה המצומצמת בביטול כל העולמות מיש לאין זהו בבחי' גבול ותכלית כו' אבל יש עוד בחי' אה' שנק' אה\"ר והיא אה' המסותרת כנ\"ל שלמע' הרבה מבחי' אה\"ע הנ\"ל (כמו מלמ' למטה אנו אומרים אה\"ר אהבתנו כו' כנ\"ל) והיינו אה' שבלתי מוגבלת בנפש כלל שאין לה בחי' כלי בנפש להגביל אורה לא בשכל וגם לא ברצון וממילא אין לאה'"],[2300680103,"זו נפילה והפסק כלל עד שלא יוכל לבא לאה' זרה המנגד כלל אע\"פ שיטרד אדם בעסקים מאוד משום דהא בהא תליא כנ\"ל באה\"ע שמצד הגבלתה בכלי הנפש יש לה הפסק ויבא לידי אהבה זרה אבל אה\"ר זאת מושללת מב' דברים הללו והיינו שאינה נתפסת בכלי להגבילה ואין לה נפילה לעולם כו' והטעם לפי ששרש יסודה אינה בא בנפש האדם מצד ההתבוננו' בהשגת בבחי' ממלא וסובב שנק' אה\"ע כנ\"ל אלא התפעלות אהבה זאת באה בנפש אדם מצד בחי' מהו\"ע ית' שהוא למע' ממקור ההשתלשלות דסובב וממלא כו' דבחי' סו\"מ לא יתכן רק בבחי' האור והשפע הבאה ונמשך בשביל השתלשלות העולמות שיש בזה ב' מדריגות. א' בבחי' או\"פ שהוא בבחי' ממלא כ\"ע כנ\"ל. והב' בבחי' מקיף וסובב על כל עלמין (כמו ענין מח' א' הכללית שכולל הכל כמו הכלל אל הפרט כידוע) וע\"כ נק' סובב לגבי עלמין עכ\"פ אבל בחי' מהו\"ע א\"ס ב\"ה למע' מע' מהיות גם בחי' מקור למקור האור ושפע בשביל עולמו' ולא יתכן לומר בו גם בחי' סובב ומקיף לאבי\"ע שאינו בגדר עלמין כלל וכמא' שקודם שנבה\"ע הי' הוא שמו בלבד כו' וגם מה שנמשך ע\"י בחי' הקו\"ח אחר הצמצום הראשון אינו רק כציור וי\"ו ויו\"ד קטן שאינו אפי' בערך טפה בים שישתווה בערך מצד המספר אבל לגבי מהו\"ע ית' אין לכל השתלשלות דקו\"ח ערך כלל וכלל לא במהות ולא במספר כו' (ואפילו לחיי העוה\"ב אומ' אין זולתך כו') וראי' לזה שאין כל ההשתל' תופס מקום כלל וכלל במה שאין שינוי כלל וכלל מקודם ההשתלשלות לאחר ההשתל' כמ\"ש אני הוי' לא שניתי כלל וכמו שאו' אתה הוא קודם כו' וכידוע והנה לזאת גם בחי' התפעלות אה' האלקי' המסתעפת מצד התבוננות במהו\"ע ית' ממש נקראת בשם אה\"ר פי' רבה בלי גבול ומדה ושיעור כלל להיות שאה\"ר זאת הבאה מכח מהו\"ע ממש לא תבוא בהגבלה בכלי הנפש כלל כמו כלי השכל של מוח מאחר דלית מח' תפיס' במהו\"ע כלל ולא בכלי הרצון שהתפעלות הרצון יופסק אורו ואה' הזאת תבא מלמע' מכל ההשתלשלות דרצון וחכ' ומדות ע\"כ לא תוכל כלי הנפש לשאת אותה כי היא למע' מכלי כוחות הנפש המוגבלים בכלים כו' אלא רק בחי' עצמי' הנפש ומהותה ממש כמו שהי' במקורה הראשון כי חלק ה' עמו ממש וכן אמר כי הוא עשנו ולא אנחנו כו' היא שתוכל להכיל את האה\"ר הזאת לכך נק' אה' המסותרת שמסותרת בפנימי' ועצמי' הנשמה בבחי' יחידה שבה ולמע' הוא בבחי' סדכ\"ס (ועכ\"א אה\"ר אהבתנו כו') ומזה הטעם יובן ג\"כ שלא יוכל להיות נפילה כלל באה\"ר הזאת דהיינו שלא יפול ממנה להסיר לבו לאה' זרה כי אינה רק רצון פשוט א' ועצמי בלי נטי' כלל ואין לו חילוף ושינוי לפי שכל עצם אינו משתנה כידוע ועיקר הטעם הוא לפי שאה\"ר זאת בא ממקום ושרש גבוה מאוד נעלה שלמע' מע' מכל ההשתלשלו' דקו\"ח וסובב וממלא כו' שזהו למע' מהגבלת האורות בכלים כנ\"ל וא\"כ אין משם שרש אחיזה ויניקה כלל לחיצוני' שיסתירו ויחשיכו אור האה\"ר זו וכמ\"ש מים רבים לא יוכלו לכבות את האה' כו' וע\"כ לא יוכל לבוא בעודנו קשור בעבותות האה\"ר"],[2300680119,"זו לידי הפסק ונפילה שיוכל לבא לידי אהבה זרה שאין החיצונים יכולי' לקבל משם כלל וכלל כי מה שיש לחיצונים יניקה הוא מצד שאזלעו\"ז עשה כו' ואין זה אלא באור הבא בדרך השתלשלות אורו' בכלים דוקא אבל למע' מבחי' השתלשלות אין להם שרש כלל וכלל ואדרבה בהגלות נגלות אור עצמו' אלקו' שלמע' מהשתלשלות אז גם חושך דקליפה מתבטלת ממציאות הנפרד ויהופך החושך לאור וכמ\"ש גם חושך לא יחשיך ממך כו' כחשיכה כאורה כו' וע\"כ אנו רואים שאה\"ר זו באה מאליה מלמע' פתאום מבלי יגיעת מוחא ולבא להיות' מצד בחי' העצמי' הנפש בעצמי' מקורה יעקב חבל כו' כשלהבת העולה מאילי' ולכך אין הפסק כלל לאה\"ר זאת מאחר ששרשה למע' אינה באה בבחי' הגבלה והלבשה בכלי כלל א\"כ איך אפשר שיפסיקנ' דבר חוצץ מזלעו\"ז שכנגדה שילבישנה ויסתירנה (וגם בחינת עצמית הרע דק\"נ שנק' עומק רע ג\"כ לא יכבה אורה כמ\"ש מים רבים לא יכלו לכבות כו' וז\"ש בזוה' נפש כי תחטא תווהא הוא ועז\"א מיד כלב יחידתי כו') וזש\"א שימני כחותם על לבך דאע\"ג דאזיל הכא והכא דיוקני אשתאר בך כו' וע\"כ אפילו רושם בעלמא שנשאר מאור אה\"ר זו שנק' אה' המסותרת כנ\"ל בלב האדם כל היום שומרת אותו מכל רע וטומאה להיותו שומר ומקיף וכמ\"ש אך בצלם יתהלך איש כו' והוא צל דצלם החופף עליו מבחי' ימין העליון כו' וד\"ל. וזהו שא' ואהבת בכל נפשך פי' בכל נפשך כל זה ריבוי הוא דהיינו בבחי' פנימי' ועצמיי' דנפשך מצד עצמו' אלקות שהיא אה\"ר הנ\"ל וד\"ל:\n(ד) <b>אך</b> הנה עדיין יש להבין בענין אה\"ר הנ\"ל דבכל נפשך דאם היא באה מלמע' מהגבלת האור בכלי כו' האיך תבא לידי גילוי בנפשו עכ\"פ מאחר שהיא למע' מבחי' כלי לגמרי שאינה נתפסת כלל בכלי הנפש מטעם הנ\"ל ואנו רואים שאה\"ר זו באה בהתפעלות הנגלות בנפש כידוע. אך הענין הוא משום דיש עוד בחי' אה' שלישית שלמע' גם מבחי' אה\"ר זו הרבה והיא הנק' אהבה רבה בתענוגים שמאירה בכל שבת בכל או\"א כמשי\"ת ומכח אה\"ר בתענוגים הוא שנמשך עיקר ושרש לבחי' אה\"ר הנ\"ל שתבא מן ההעלם לגילוי בנפש וזהו הנק' אה' בכל מאודך שהיא בחי' ההעלם דעצמי' הנפש בבחי' יחידה שבה כמ\"ש בבחי' העצמי' ממש כמו שקשורה ודבוקה למעלה ממש טרם שיבא ממנה אור התפשטות בגילוי למטה כלל וכלל כו' (והוא בחי' מ\"ם דצלם כמ\"ש במ\"א) וביאור הענין הנה אה\"ר דבכל נפשך הנ\"ל הרי אנו רואים שבא' למטה בבחי' גילוי בנפש עכ\"פ והוא מה שאנו רואים התפעלות אה\"ר זו בגילוי בלב דוקא עד שאין כלי הלב מכיל אורה ולא תתיישב בלב כלל כמו כלה שארי ולבבי כו' והוא להיותה למעלה מבחי' הגבלת כלי כנ\"ל ועכ\"ז מורגשת היא בנפש והיא הנק' תענוג ורצון מורגש עכ\"פ רק שהוא בבחי' נקודת הרצון שלמע' מן הטעם והשכל כנ\"ל שלא באה מצד ההתבוננות דסו\"מ כו' אלא רק מצד עצמי' אלקות ע\"כ לא יכילנו כלי המוח והלב כנ\"ל. אמנם הנה בחי' אה\"ר בתענוגים הנ\"ל היא למע' מזה הרבה והוא בחי' התענוג הפשוט הנעלם שבעצמי' הנפש ממש כמ\"ש למע'"],[2300680135,"במקור חוצבה ממש בהתקשרות תענוג עצמי עדיין שלא באה עדיין לכלל התפעלות עונג ורצון במורגש בגוף כלל (כנשמות שנהנין מזיו השכינה בג\"ע) וזהו שמאיר בכל שבת דוקא כמ\"ש על כללות נש\"י מה יפית ומה נעמת אהב' בתענוגים כו' דכמ\"כ ודאי מלמעלה למטה ג\"כ נמשך מבחי' התענוג העצמי הפשוט שבעצמו' א\"ס ב\"ה שז\"ש אה' בתענוגים כו'. וביאור הדברים ידוע שזהו עיקר ההפרש בין עבודה האלקי' שבלב ומוח בתפלת החול שהיא באה' דבכל לבבך ובכל נפשך הנ\"ל שבאה עכ\"פ במורגש בכלי הלב ומוח בהתפעלות רצון ואה' כו' אבל עבודה שבתפלת שבת שהוא בכל נשמות בתענוג העצמי שבה עצמה כמו שהיא מתענגת על ה' במקור חוצבה ממש בעצמי' אלקות רק מצד העצם ולא בהתפעלות איזו רצון ואה' כלל כמ\"ש אז תתענג על ה' דא צלותא דמע\"ש כו' שעל ה' היינו למע' גם מגילוי אור ה' בנפש למטה באה\"ר הנ\"ל שכל אה' ורצון גם בנקודת הרצון אינו אלא מרחוק דוקא אבל בקירוב ודיבוק העצמי אינו בכלל התפעלות רצון ואה' עדיין כמו עד\"מ בן העומד לפני אביו בקירוב ודבוק עצמי שמצד עצמות השעשועים שבאב לבנו כו' שמתענגים זע\"ז בתענוג עצמי ופשוט בלתי מורכב ומורגש בדבר מה גם לא ברצון ואה' כו' מאחר שהוא בבחי' העצמי' ממש וזהו עיקר ענין תפלת השבת שנק' ישראל שיר אל שהנשמה תתענג על ה' בשיר פשוט שנקר' שיר אל מצד אלקות בעצמו וזה ידוע למתענגים על ה' בנשמתו במורגש כמו שהיא בהעלם והיינו בכל שבת דוקא בבחי' שיר א\"ל הנ\"ל (כמו לע\"ל שיהי' הנשמות מתענגים בעצמות התענוג הנעלם שיבוא במורגש דוקא כמו להנחיל אוהבי יש דוקא וכדוגמא זו בכל שבת שעונג הנעלם דוקא בא בהתלבשות במורגש כסעודת השבת שנק' סעודה דע\"י כו' וכלחם פנג וסעודת לויתן דלע\"ל וכמ\"ש במ\"א בענין המן לפי שבכל שבת יש מיום שכולו שבת ומעין זה יש בכל ג\"ע בעליות הנשמות בע\"ש כו') והטעם שבשבת דוקא היינו לפי שאמר וקראת לשבת עונג שנמשך מעונג העליון הפשוט לנש\"י למטה (והוא ג\"כ ענין טעמי תו' כמשי\"ת) וע\"כ מובן שמבחי' אה\"ר בתענוגים הנ\"ל שבשבת שבבחי' עונג העצמי כמ\"ש למע' נמשך בחי' אה\"ר הנ\"ל שתבוא לידי גילוי מן ההעלם והוא בחי' התפעלות נקודת הרצון במס\"נ בהתגלות בנקודת הלב עד שלא יכילנו כנ\"ל אבל בעצמו' העונג הנעלם בנשמה כמ\"ש דבוקה וקשורה בתענוג עצמי עדיין היא למע' מבחי' המשכת אה' בהתפעלות רצון בגילוי כלל כנ\"ל רק שממנה בא כח התפשטות גילוי נקודת רצון זה שבאה\"ר הנ\"ל וד\"ל (ומלמע' למט' כמים הפנים אל הפני' כו' הוא ג\"כ באה\"ר בתענוגים כנ\"ל והוא בחי' רעדכ\"ר שבפנימי' דע\"י כידוע שזה מתגל' במנח' בשב' כמ\"ש וקראת כו') ואמנם הנה לפ\"ע העבודה דחול בב' מדריגות דאה\"ע והאה\"ר הנ\"ל כן יהי' ערך גילוי אור אה\"ר בתענוגים למטה בנשמות בשבת בכאו\"א לפי ערכו להוציא ולהמשיך לבחי' אה\"ר המסותרת לידי גילוי בלב מן ההעלם בגילוי אור ביתר שאת ויתר עז כל ימי החול בק\"ש ותפלה משום דהא בהא תליא דוקא וכמ\"ש"],[2300680150,"אם תעירו ואם תעוררו את האה' כו' וד\"ל. וזה אה\"ע אהבתיך ע\"כ משכתיך חסד פי' לפ\"ע העלא' מ\"ן באה\"ע הנ\"ל שבאה מהתבוננות דעולמות שעי\"ז רוח אייתי רוח ואמשיך רוח לעורר אה\"ע למע' והוא שא' אה\"ע אהבתיך כו' אהבה זו דאה\"ע אהבתיך וכן לפ\"ע אה\"ר הב' הנ\"ל שמעור' אה\"ר העליונ' להיות אה\"ר אהבתנו הוא הגורם להיות משכתיך חסד עליון דהיינו שיהי' גילוי המשכת אור אה\"ר ואה\"ע הללו ביתר שאת ממקור חוצבם שהוא בחי' אה\"ר בתענוגים הנ\"ל שממנו מקור מוצא גילוי העלם דאה\"ר כנ\"ל וז\"ש ע\"כ משכתיך בחבלי עבותת אה\"ר מבחי' חסד עליון משום דהא בהא תלי' כנ\"ל בענין חול ושבת (וכן מאה\"ר דתענוגים דשבת נמשך אה\"ע ואה\"ר בחול מטעם הנ\"ל וד\"ל). וזהו ג\"כ ענין פותח את ידיך ומשביע לכל חי רצון פי' ידיך הן ב' ידות דימין ושמאל והיינו אה\"ר ואה\"ע ע\"י העלאה דכנס\"י פתיחות הידות הללו היינו שיאיר בכל נשמה האלקי' שנק' כל חי מבחי' נקודת הרצון דאה\"ר הנ\"ל במס\"נ מן ההעלם לגילוי כו' ומ\"ש ומשביע לכל כו' היינו שתתיישב בנפש ותשבע מאה\"ר זו ותכילנו במוח ולב בשביעה כמו ישבעו ויתענגו כו' וזהו בשבת מצד הארת אור התענוג הפשוט דבחי' עצמות עונג העליון כמו שהוא למע' כנ\"ל וד\"ל. ומ\"ש ידיך הן יודין ווין כידוע וענין היודין הוא בחי' הצמצום והסתר וכנקודה דיו\"ד בשביל השפע לעולמו' ונשמות ומלאכים ופתיחה דיודי\"ן להיות ווי\"ן בחי' המשכה וגילוי ההעלם דוקא שיבא ביותר מכפי המדה והצמצום דיו\"ד כו' הנה זה בא ע\"י אתדל\"ת מאה\"ר ואה\"ע הנ\"ל שהוא להפוך גם כל הרצון הזר להיות רק רצון אחד לה' לבד כענין מי לי בשמים כו' כנ\"ל עי\"ז נתעורר למע' ג\"כ להיות גילוי ההעלם וצמצום דיודי\"ן (שזהו ענין פתיחת היד דימין הנ\"ל מאה\"ר בתענוגים כו') והוא שמן היודי\"ן נעשה ווי\"ן בבחי' גילוי המשכות למטה ממש להשביע לכל חי רצון כנ\"ל וד\"ל. (אך מלמטה למע' רצוא קודם לשוב שהוא מס\"נ דאה\"ר ואה\"ע הנ\"ל ועי\"ז מלמעלה למטה נמשך בבחי' מטי ולא מטי בבחי' פתיחה דיודי\"ן תחלה ואח\"כ נמשך בווי\"ן כפ\"ע קבלת הנשמות דוקא כו'). ובכ\"ז יובן מ\"ש חכלילי עינים מיין מיינה של תו\"מ וקאי זה על תפלות השבת בתענוג העצמי הנ\"ל שמוציא הסוד בשבת מן ההעלם לגילוי כו' משום שנכנס יין יצא סוד כו':\n(ה) <b>וביאור</b> הענין הנה התורה נק' בשם יין שהיא גימטרי' סוד והוא סוד טעמי המצות שנק' יינה של תורה כו' ונכנס יין יצא סוד הוא ענין הנ\"ל בפותח את ידיך כו' להשביע לכל חי מבחי' רצה\"ע דאה\"ר הנ\"ל שתבא מן ההעלם לגילוי בנקודת הלב והיינו מבחי' ההעלם וסוד דאה\"ר בתענוגים הנ\"ל שהוא בחי' התענוג העצמי שבהעלם למעלה ממש וע\"י בחי' יין זה דתורה דוקא שהוא ג\"כ בבחי' תענוג הנעלם שבתורה שבאה לידי גילוי כמו שטבע היין להוציא סוד הנעלם ע\"כ ע\"י יינה של תורה נגלה ג\"כ סוד והעלם דאה\"ר בתענוגים להוציא לגילוי בחי' אה\"ר דנקודת התפעלות הרצון בלב על כל ימות החול כנ\"ל וד\"ל. וזהו דוקא ע\"י תו\"מ שעושין בפו\"מ כל ימות החול שגנוז בהם פנימי' רצה\"ע ופנימי' התענוג"],[2300680165,"העליון ובשבת יצא סוד ה' שבתו\"מ לגילוי כמו בחי' אה\"ר בתענוגים כו' והענין הוא כידוע במ\"ש וירא את האור כי טוב כי טוב לגנוז האור בכלי ופי' האור היינו אור פנימי' העונג העליון דאה\"ר בתענוגים שמזה יומשך ממילא נקודת הרצון דהאה\"ר הנ\"ל לגנזו לאור זה בתורה דוקא שבה מוסתר וגנוז פנימי' טוב טעם ותענוג העליון הנעלם שנק' טעמי תורה ואמנם כאשר קורא בתורה בדיבור בפה דוקא אזי מעורר למעלה גילוי רצה\"ע שבתורה שרצה\"ע זה שיש בתענוג הנעלם הוא מקור לגילוי אה\"ר ברצון הנ\"ל מאה\"ר בתענוגים שז\"ש פותח את ידיך ומשביע כו' לפי שבחי' פנימי' רצה\"ע שמזכיר בדיבור בתורה הוא שרש להמשכות רצון דאה\"ר הנ\"ל וע\"כ ע\"י לימוד התורה בדיבור שמזכיר את רצון העליון בדיבור דוקא הרי הוא ממשיך ומביא מן ההעלם דאה\"ר בתענוגים להיות גילוי רצה\"ע להשביע לכל חי מרצון זה שהוא אה\"ר הנ\"ל שלמע' מבחי' סו\"מ כנ\"ל וזהו שבשבת א' חכלילי עינים מיינה ש\"ת שיוצא הסוד דאה\"ר לגילוי דהיינו מה שהי' גנוז ונעלם בתורה בכל ימות החול בעסק התורה בדיבור הוא שיוצא לגילוי בשבת שזהו אמיתית ענין פתיחה דיודין להשביע לכח רצון דאה\"ר הנ\"ל וד\"ל. ובזה יובן משארז\"ל שעיקר השאלה ששואלין למע' היא על קביעת עתים לתורה אם קבעת עתים לתורה ולמה אין שואלין על תפלה וכה\"ג אך מטעם הנ\"ל יובן בהיות שהאור העליון דאהבה רבה בתענוגים נגנז בתורה דוקא וע\"י התורה נמשך אה' דכל נפשך ובכל מאודך כו' ע\"כ עיקר השאלה על קביעות עתים לתורה שממילא נכלל בזה ב' אה' הנ\"ל שהו' אמיתית ההתקשרות הנשמ' האלהי' במקור חוצבו בג\"ע והוא שמכריזין בג\"ע אשרי מי שבא לכאן ותלמודו בידו כו' וד\"ל. וזהו פשט הדברים בפ' ק\"ש באמרו ואהבת את הוי' כו' ואח\"כ והיו הדברים האלה אשר אנכי כו' דמשמע פשט הדברים דוהיו הדברים האלה כו' האלה ממש דסמיך לי' שהן ג' אה' דכל לבבך ובכל נפשך ובכל מאודך שיהיו הדברים האלה על לבבך שהן הדברים אשר אנכי מצוך היום ואח\"ז אמר ושננתם לבניך ודברת בם דזה מדבר במצות ת\"ת ולא בג' אה' הנ\"ל ומסיים במה שלא פתח ואין לדברים אלה חיבור מרישא לסיפא אלא צ\"ל דהכל שרש וענין א' הוא מטעם הנ\"ל דאה\"ר הנ\"ל נגנז בתורה עכ\"א והי' הדברים האלה אשר אנכי מצווך שהוא לאה' את ה' בכל נפשך ובכל מאודך על לבבך בלימוד התורה דוקא והוא מ\"ש ושננתם כו' שמדבר במצות ת\"ת כלומר ע\"י עסק התורה דודברת בם יבאו לך האה' הנ\"ל והי' הדברים האלה על לבבך תמיד כמו עסק התורה שהיא מצוה תמידי' גם בלכתך בדרך ובשכבך כו' לפי ששרש התורה הוא מלמע' מן ההשתלשלות דזמן יום ולילה גם למע' מעה\"ד כו' ע\"כ לא יחשיך אורה כלל ותאיר גם בעסקו בעסקיו בלכתו בדרך כמו בשבתו בביתו ע\"כ מצות ת\"ת תמידית דוקא כמו\"כ הוא בחי' אה\"ר הנ\"ל שגם בעסקו בעסקיו ובלכתו בדרך לא תחשך אור אה\"ר זו להיות בבחי' עצמי' כנ\"ל (משא\"כ בחי' אה\"ע הנ\"ל) וע\"כ גנוזה בתורה דוקא משום דהכל אחד ממש (וכנ\"ל בענין ג' קשרין דבחי' סתים דנש\"י מתקשראין"],[2300680180,"באותי' התורה הקדומ' וזהו והיו הדברים האלה אשר אנכי מצוך כו' ודברת בם כו' דהכל א' ממש וד\"ל):\n(ו) <b>והנה</b> מעתה יש להבין מ\"ש חכלילי עינים מיין שזהו ענין אדמימות העינים מהו ענינו להיות ידוע בסיבת אדמימות העינים ע\"פ הטבע בא' מב' דברים שהן א' והוא הפלגת הצער או הפלגת העונג כמו שכאשר יראה האדם באוהבו כנפשו צער גדול יתאדמו עיניו מעוצם הצער בנפשו שלא יוכל שאת לראות או כשיראה שונאו בתכלית וזה בא מהפלגת חום רשפי אש שלהבת שבדמים שבאו במוח ומן המוח יומשך לעינים וכן בגבור' רציחה וכעס במלחמה עד שיאדימו עיניו כו'. ומזה יובן בהיפוכו שהיא הפלגת חום רשפי אש התענוג שבנפש לאוהבו כנפשו ולמי שאליו תכלה נפשו בתשוקה נפלאה ביותר שאז כל החום שבתענוג נמשך בראי' והסתכלות העינים לראות בו בחשק נפלא עד שיאדימו עיניו מרוב התפעלות התענוג ברשפי אש וחום הגובר בו כנ\"ל לקבל השפע אור הארת פניו לבד כמ\"ש עיניך יונים שהן כנסת ישראל שתשוקתם ברשפי אש התענוג לאסתכלא ביקרא דמלכא באור פני מלך חיים כעיני היונים שמסתכלים זע\"ז כו' וכמ\"ש בזוהר ע\"פ הסבי עיניך מנגדי כו' דמוקדין ליה בשלהובי דרחימותא כו' לפי שבחי' העלא' מ\"ן זה דהסתכלות עינים נפלא מאד בבחי' רשפי אש שלהבת התענוג האלקי בבחי' עונג עצמי שבפנימי' ועצמי' הנפש ממש שזהו בחי' אה\"ר בתענוגים הנ\"ל ע\"כ אינו אלא בבחי' ראי' והסתכלות לבד עד שנתאדמו העינים מרוב ההתפעלות כו' וכמו\"כ מלמע' למטה כתיב עיניו כיונים שזה מן המשפיע אל המקבל ג\"כ בבחי' אה\"ר בתענוגים כמ\"ש מה יפית ומה נעמת כו' כמ\"ש במ\"א וד\"ל. וזש\"א חכלילי עינים מיין פי' מהיכן בא סיבת אדמומית העינים בבחי' ההסתכלות בתענוג הנפלא הנ\"ל שאין זה אלא בשבת דוקא כנ\"ל הנה זה בא מיין מיינה ש\"ת דהיינו מי שטרח בע\"ש שזהו כל ימות החול שטרח בעבודה שבלב ומוח באה\"ע ובקריאה בתורה בדיבור ובמעש' המצות בפו\"מ שגנוז בזה כל בחי' עונג העצמי העליון דאה\"ר ואה' בתענוגים שזהו ענין טעמים וסודות התורה הגנוז בנגלה שבה כנ\"ל אזי בשבת דוקא יוצא הסוד הגנוז הזה לידי גילוי שהוא להתענג על הוי' בעונג העצמי דאה' בתענוגים הנ\"ל שהוא גילוי יינה ש\"ת מן ההעלם דהא בהא תלי' כנ\"ל עד שמזה התענוג העולה בהעלאה בליל שבת כמ\"ש אז תתענג כו' בתפילת ליל שבת עי\"ז נמשך ביום שבת מלמע' למטה מהקב\"ה לכנס\"י ג\"כ בבחי' הסתכלות עינים בעונג העצמי (ע\"ד שאמר כשם שבא לראות כו') וכמו עיניו כיונים עין ה' אל יראיו וכה\"ג והיינו במ\"ש וקראת לשבת עונג שנמשך מעונג שבעצמי' המאציל לכנס\"י כמו שא' דא היא סעודתא דעתיקא כו' עד במנחה הוא התגלות בחי' רעוא דכ\"ר כו' וזהו בחי' גילוי הסוד דטעמי תורה שנק' נסתרות לה' כו' ולא יתגלה רק לע\"ל כמ\"ש ישקני כו' ומעין זה מתגלה בכל שבת אחר העלא' התענוג מלמט' למע' מכנס\"י והוא ע\"י שנכנס יינה ש\"ת מימות החול שמזה דוקא יצא הסוד בשבת כנ\"ל וד\"ל. (וזהו חכלילי שיש בו תיבת חיך וב\"פ לי לי כמ\"ש כל חיך הטועם אומר לי לי ויובן זה ע\"פ"],[2300680194,"כל הנ\"ל דמחמ' טעמי תורה נמשך האדמימו' בעינים מרוב התענוג כמי השותה יין הרבה שמאדימים עיניו ונמשך עי\"ז תענוג ערב לנפש בחיך הטועם טעמי תו' שאו' לי לי כמו רזי לי רזי לי כו' והן ב' אה' הנ\"ל דאה\"ר ואה' בתענוגים וכמ\"ש נפשנו חכתה לה' בתענוג וטעם שבחיך וכמ\"ש יעשה למחכה לו כו' כמ\"ש במ\"א וע\"כ כל חיך הטועם בבחי' טעם ותענוג העצמי' בשבת או' לי לי שנכללו בנפשו ב' אה' הנ\"ל וד\"ל):\n(ז) <b>ולבן</b> שינים מחלב. הנה מבואר למע' שהתורה נק' יין וחלב ולאחר שא' חכלילי עינים מיין שזהו אדמימות העינים מיינה ש\"ת כנ\"ל א' ולבן שינים מחלב שהתורה נק' חלב כו'. והענין הוא כידוע בטבע תועלת שיניים שהוא לטחון את המאכל וללעוס אותו היטיב כמ\"ש השיניים טוחנות כו' והוא מה שיש בטבע השיניים הגשמיים לפרר ולחלק את המאכל בלעיסה שלועס בשיניו היטיב הדק ומחמ' שנטחן המאכל בשיניים דק דק התועלת הוא מזה אח\"כ כשבא המאכל אל הקיבה יוכל להתעכל בכי טוב ולהתברר בקיבה שזהו הבישול הטוב להוציא ממנו כל חלקי הטוב וחיות רוחני שבו ללעוס למזון לשובע נפשו שיתפשט בכל האיברים מראש לרגל ליתן כח חזק בכולם בכל אחד ואחד לפי אופן פעולתו והפסולת של המאכל נדחה לחוץ כו' אבל אם לא הי' לועס בשיניי' היטיב הרי המאכל בא בקיבה כמו שהוא בגולמתו ולא היה מכח הקיבה לעכל המאכל ולא הי' למזון להתפשט באיברי הגוף (וכמ\"ש דוק בככי ותשכח בנגרי כו'). והנמשל מזה יובן תחלה במזון ומאכל רוחני דתו' כמ\"ש ותורתך בתוך מעי כו' כידוע שהתורה הנגלית לנו נק' מזון לנשמה אלקי' לחזק כל כוחות שלה מראש לרגל כו' וכמ\"ש כי אמרתך חייתני כו' וכמ\"ש לכו לחמי בלחמי כו' ואמנם אין זה כ\"א שיהי' תחלה בחי' הטחינה בשינים שזהו ענין הגירסא ל' גרש כרמל שהוא לטחון דק דק בדיבור בפה דוקא שזהו בשינים ל\"ב נ\"ח שנק' שיניים הטוחנות למע' וכמו שנראה לעין שכל שמדקדק ומחלק הדב' הלכ' בריבוי החלקי' בדיבו' בפה דוק' אז יבין וישכיל ויחי' לנשמתו להיות תורתו בתוך מעיו להיות תו' אור לחיות נשמתו גם במוחין ומדות עד גם בהילוך בדרכי ה' כל היום בסו\"מ וע\"ט שזהו בחי' רגל של הנשמה כמ\"ש צדיקים ילכו בם כו' וזהו שאמר חיים הם למוצאיהם בפה דוקא והוא התועלת לברר לעה\"ד טו\"ר באמרו זה כשר וזה פסול כו' משא\"כ אם לא טחנו למאכל ולחם דתו' בגירסא אינו בא לעיכול שהוא תכלית הבירור להיות למזון לנשמה ולא יהי' לו לחם דתו' לחיות כלל כמו\"כ למע' לא יהי' מתורתו מזון לשכינה שזהו לבחי' רמ\"ח איברים דמלכא כו' ולא נק' לחמי כלל לפרנס לאביהם כו' וד\"ל. ועד\"ז יובן במעשה המצות כל היום שעז\"א המדקדק במעשיו דהנה יש מ\"ד דמצות א\"צ כוונה ובאמת המעשה בלא כוונה זהו כמאכל לחם בלא טחינה בשינים שהוא כגולמא בעלמא ואינו עולה למע' להיות לבחי' מזון לשכינה כמ\"ש רעייתי פרנסתי כו'. אך המדקדק במעשיו הוא שמדקדק לעשות בכוונה ורעותא דליבא דוקא ומדקדק לפשפש בכל חלקיו לדקי דקות לברר בהם כל בחי' פסולת ורע שלא יתערב שום כוונה זרה במעשיו רק לה' לבדו והוא שנותן לבו ודעתו"],[2300680208,"היטיב על כל דרכיו ומעשיו לפשפש בהם ולדקדק בהם מאד אם הוא כראוי בלי שום תערובת זרה ומה שימצא תערובות יזרוק אזי מעשיו רצויים לה' ועולה למעלה ונק' פרנסתי כו'. וכמו\"כ גם בעיקר מהות ההתפעלות האלקי גם באה\"ר הנ\"ל כאשר יתפעל האדם בעבודה שבלב בתפלה באמת עכ\"ז הוא רק בחי' גולמא בעלמא עדיין בלי ברור כלל וכאשר תעלה למע' יכולה להבלע וליכלל בביטול מציאות למע' עד שלא ישאר ממנה כלום כמו אש שלהבת העולה מן הקש ותבן שעולה ולא נשאר כלום כך יראה כל אדם בהתפעלות אה\"ר הנ\"ל שתיכף ומיד נבלעת ולא נשאר רושם ממנה כלל אך כאשר נותן דעתו ושכלו עלי' האיך היא כו' דהיינו שמדקדק בה עם כל לבו ונקודת אמיתית הרצון בה בלי שום תערובות ופסולת כלל ויפשפש בה הרבה בדיקדוק אחר דקדוק וחיפוש אחר חיפוש לבחון הלב לתוך תוכו עד שזורק כל פסולת ממנו אז ראוי למזון למעלה ולמטה שתעלה ותתכלל למע' באלקים חיים כענין פרנסתי הנ\"ל משא\"כ אם לא טחנו ודקדק בה כלל כנ\"ל שלא נבררה כלל לא תוכל לעלות כמ\"ש מי יעלה כו' ובר לבב כו' וכדוגמת הגירסא בדיבור בפה כנ\"ל וד\"ל. וזהו ולבן שינים מחלב דהנה התורה נק' ג\"כ בשם חלב וידוע שטבע החלב לעשות התפשטות וגידול האיברים כו' וגם טבע החלב ללבן ולזכך וכמו\"כ ענין רוחצות בחלב שהרחיצה בחלב מלבן ומזכך ומהפך למהות גדלות וכה\"ג בענין הגירסא דדיבור בשינים הטוחנות כנ\"ל עי\"ז נעשה ליבון הלכתא שמתלבן ומתברר ההלכות ומתפשטים בבחי' הגדלות יותר וז\"ש ולבן שינים הטוחנות הנ\"ל מבחי' חלב דתו' אחר שהתורה נק' יין דוקא כמ\"ש חכלילי עינים מיין ואח\"כ ולבן שינים מחלב כו'. ויובן זה ג\"כ בעבודת ה' דהנה כל ענין הנ\"ל בהתפעלות דאה\"ר בתפלה אע\"פ שמדקדק בה שתהי' ברורה מכל סיג כנ\"ל בענין המדקדק במעשיו כנ\"ל (וכענין הגירסא בתו' כך הדיבור בתפלה שיוצא ברור מכל סיג ופסולת מהתפעלות האה' שבלב שנבררת בתכלית) אבל אין ההתפעלות הזאת רק בבחי' תולדה לבד שאין בה התפשטות עדיין וכוולד הנולד שאין בו גידול והתפשטות עדיין עד שיונק החלב שמגדלי' אבריו כו' אמנם לאחר לידת האה' צריך להגדיל אותה דהיינו שתתפשט האה' האלקי' שנתפעלה בכל חלקי רמ\"ח איבריו כו' והענין הוא שלא כמו שאנו רואים בכמה בנ\"א שמיד שמתפעלים באה\"ר ודביקות שתתמלא נפשו בזה ונדמה לו שיצא י\"ח העבודה האלקי' באמת ומסתלק אור האה' תומ\"י ולא נולד ממנה שום תולדה בכל פרטי דרכיו ומחשבותי' כל היום כאילו לא הי' לו שום התפעלות מעולם כו' ואע\"פ שקיים מצות אה' אבל זהו רק בבחי' הקטנות לבד אלא שצריך שיומשך להתפעלות האה' שתתפשט גם בכל דרכיו ופרטי מעשיו ומחשבותיו כל היום שיתנהג הכל רק ע\"פ כח ההתפעלות אלקי שהי' לו בתפלה באה\"ר הנ\"ל שיהי' רק לה' לבדו ואין זר אתו כמ\"ש בכל דרכיו דעהו וכמו באברהם שא' התהלך לפני כו' (והיא האה' שהיא שרש לרמ\"ח מ\"ע לעשות המצות כל היום בכוונה ורעותא דליבא ולא כמו מצות אנשים מלומדה"],[2300680221,"ובלי שום כוונה זרה כו') ונמצא שזה כמו המים המגדלים ומצמיחים שמרחיבים ומתפשטים בגידול הפירות ותבואות כך אור התפעלות האה' האלקי' שבתפלה מתפשטת בתוך כל מעשיו וכל עסקי' כל היום בכמה חלקים וכלים מכלים שונים (וכמשל סחיטת המשקה התמצי' (שנק' שענציע) שממזגים בשאר משקים ונעשה טובים) ואמנם זהו דוקא אחר הטחינה בשינים שהוא ענין הדקדוק והבירור בהתפשטות האה' אז אמר ולבן שינים להגדילה ולהוליכה בכל החלקים זהו בא מבחי' חלב שהוא התו' כשנק' חלב וכמו רוחצות בחלב כו' ללבן ולזכך כל מעשיו שיהי' רק לה' לבדו בלי שום עכרורי' ותערובות רע כלל כנ\"ל ונמצא הרי יש כאן ב' דברים ע\"י בחי' החלב. א' הזיכוך והליבון שנק' ליבון הלכתא כנ\"ל. והב' ההתפשטות בבחי' גדלות לאורך ורוחב בריבוי החלקים כו' וכ\"ז אחר שהי' בחי' הבירור ע\"י יינה של תורה שהוא בחי' הטעמים דתורה בחיך הטועם וכמ\"ש למע' וחכך כיין הטוב אח\"כ צריך להיות בחי' גדלות והתפשטות בבחי' רמ\"ח אברים דמלכא (שהן רמ\"ח מ\"ע למע' כמ\"ש בע\"ח דט\"ס דז\"א כלולים מטפ\"ט וג' מיני כלים רת\"ס והן ה\"ח שמגדילים כו') בבחי' חלב דתורה דוקא כנ\"ל וד\"ל:"],[2300680040,"(א) <b>בן</b> פורת יוסף בן פורת עלי עין כו' הנה ידוע בתיבת פורת שהוא אותיות תופר וגם אותיות פותר כי יוסף היה פותר חלומות וכאשר פתר כן היה. ויש להבין מה זה שהיה יוסף פותר חלומות דוקא שכאשר פתר כן היה ומן פתרון החלומות נתעלה וגם יש להבין מה שהשבטים שנאו אותו ביותר וכי לא ידעו מעלתו היתירה אחר שאביו אהבו ועשה לו כתונת פסים ולמה לא חששו לחלומות שלו. ועיקר יש להבין במה שלא הכירו את יוסף במצרים דכתיב והם לא הכירוהו והלא השבטים היו במעלה ומדריגה גבוה ביותר כמ\"ש ששם עלו שבטים שבטי י\"ה כו' ואיך לא הכירו בו שהוא עברי עכ\"פ וסברו שהוא מצרי ואיך יתכן שנשמות גבוהות כאלה שהן בבחי' האצי' (שבבריאה) יטעו כ\"כ ביוסף מאחר שנק' שבטי י\"ה וכל בנין של בנ\"י בתומ\"צ יצא מהם ובפרט יהודה שהוא בחי' המל' למעלה דכתיב בו הפעם אודה את ה' בבחי' ביטול כו' איך לא הכירו ליוסף בחי' צדיק עליון והיה סבור שהוא מצרי כו'. אך הנה בתחלה יש להבין בשרש בחי' יוסף צ\"ע שהיה בחי' מרכבה בבחי' האצי' ממש כמו האבות אברהם יצחק ויעקב ממש ובזה היה יתרון מעלתו על השבטים דגם ששרשם היה ג\"כ באצי' אבל זהו בחי' אצי' שמוסתר בבריאה כו'. ולהבין זה יש להקדים ענין האבות שהיו בחי' מרכבה לחג\"ת דאצי' מהו ענין ובחי' מרכבה כו' להיות ידוע בשרש בחי' אברהם איש החסד שהיה מדריגת עבודתו בבחי' החסד והוא בחי' האהבה והדביקות באלקים חיים בתכלית הביטול במציאות לגמרי מכל וכל מפני עוצם הדביקות וההתקשרות האמיתית מקרב ולב עמוק ביותר וכמו שאמר ומצאת את לבבו נאמן לפניך נאמן בכל כי נסהו בכמה נסיונות ובפרט בעקידת יצחק ועמד בכל כידוע ואמנם עיקר ענין עבודתו היה רק בתגבורת"],[2300680056,"<b>עוצם</b> הדביקות והתקשרות באור א\"ס ב\"ה בתמידות דוקא בלי הפסק אפילו רגע א' כמ\"ש לו התהלך לפני והיה תמים התהלך בהילוך תמידי בדביקות האמיתי לפני ממש ולשון הילוך היינו דוקא בכל דרכיו ומעשיו וגם כל מחשבותיו ודבוריו אינו רק לה' לבדו ולא ההתפעלות באהבה ודביקות בה' לשעה א' או שתים לבד כי אין זה נק' הילוך כלל שענין ההילוך הוא שהולך ועולה למעלה כמו ילכו מחיל כו' וכמו ההולך במעלה ההר שהולך ועולה מעט מעט בכל רגע כמו מי יעלה בהר ה' כו' וכך התפלה שהיא הדביקות נק' סולם שהולך ועולה לידבק נפשו באא\"ס ב\"ה וזהו אי אפשר כ\"א בהפשטות כל העצמיות מכל וכל רק לה' לבדו דהיינו שניזוז ממקומו להפשיט כל הרצונות הגופניות ולא יהיה רצון ותשוקה רק לה' לבדו שאין זה בהתפעלות לפי שעה אלא בהתקשרות עצמיית בתמידות דוקא בלי נפילה והפסק ובתוספת עילוי אחר עילוי דהיינו בעומק ההתקשרות יותר ויותר כמ\"ש בזוהר ע\"פ ואברהם זקן בא בימים יומין דילי' קריבו ליה מדרגא לדרגא כו' לפי שבכל יום הי' עולה במעלת עומק ההתקשרות ודביקות האמיתית יותר מיום שלפניו וכענין הלוך ונסוע הנגבה שאמר בזוהר הנגבה בסט' דדרום שהוא האהבה והדביקות היה הלוך ונסוע מדרגא לדרגא שזהו בעילוי אחר עילוי עד אין שיעור למעלה כעליות הנשמות מג\"ע לג\"ע כו' ונמצא יש כאן ג' דברים בענין ההילוך שאמר על אהבה דאברהם אוהבי שנק' רחימא דמלכא א' שהי' הולך תמיד בכל דרכיו ומעשיו וכל תנועה ותנועה גם במחשבה ודבור היה הכל דבוק למעלה באצי' ממש שנק' הלוך לפני ה' ממש שאין נק' הילוך רק בכל הפרטים במחשבה ודבור ואכילה ושתיה ולבוש וגם במשגל הי' הפשטה מן התאוה הגופנית בתכלית כו'. והב' בענין ההילוך הוא בחי' העליה והסתלקות למעלה מעלה בכל שעה ורגע בעומק אחר עומק כעולה בהר כו' וכמו ילכו מחיל כו' מיום ליום הולך ומתעלה כו' והג' בהפשטת כל עצמותו ובתמידות בלי הפסק כלל שזהו עיקר ההילוך שהולך וניזוז ממקומו בכל רגע ואינו עומד במקום אחד אפי' רגע ממש כמ\"ש ונתתי לך מהלכים בין העומדים האלה שהנשמות נק' מהלכים שמהלך בתמידות ובלא ג' תנאים אלה לא נק' הילוך כידוע וכל ג' תנאים אלה נכלל בלשון מרכבה כמרכבת הסוס לגבי רוכבו שהסוס הולך במרוצה גדולה בלי עיכוב והפסק אפי' רגע ונושא את הרוכב בגובה ההר שלא היה ביכולתו לעלות ועליה זו בתמידות הולך ועולה בכל כחו וכל שמגיע למעלה בגובה יותר יותר צריך להיות כל כחו לעלות כו' והוא רק עוצם בחי' הביטול במציאות מכל עצמותו רק לה' לבדו שנק' מרכבה לגבי שם הוי' דאצי' כביטול הסוס לגבי רוכבו בהילוך בתמידות כנ\"ל וד\"ל (וכמ\"כ גם עכשיו כל נשמות הגבוהות הולכים ועולי' בעילוי אחר עילוי באא\"ס כנשמת משה ואהרן והאבות וכה\"ג כמו שאמר וקדושים בכל יום יהללוך סלה בלי הפסק כלל כו') ונמצא מובן עכ\"פ בשרש בחי' מרכבה למעלה שנק' הילוך כנ\"ל אין בו שום מקצת אחיזה והתקשרות בעולם"],[2300680072,"הפירוד כלל רק שהוא דבוק למעלה בשם הוי' דאצי' בתכלית הביטול במציאות בתמידות דוקא ובעילוי אחר עילוי כו' וכמ\"כ האבות היו בחי' מרכבה למעלה כאברהם שהיה מרכבה לשם הוי' שבמדת החסד הי' דבוק רק למעלה בתכלית הביטול בכל מעשיו ומחשבה ודבור ולא היה לו שום התקשרות ואחיזה בחומריות הגופני כו' והיה הולך ועולה בדביקות והתקשרות כנ\"ל וכמו ויעל אלקי' מעל אברהם הרי בשעה זו שהיה אלקים מדבר עמו היה שורה על נשמת אברהם כרוכב על המרכבה ממש וכאשר כלה לדבר אתו ויעל אלקים מעל נשמת אברהם כו' וכך היה יצחק מרכבה לשם הוי' שבבחי' גבורה שהוא שם אלקים בפחד דיצחק שהיה תמידי בלי הפסק כלל כנ\"ל באהבה ודביקות בהיותו בפחד ה' שיהי' לע\"ל מצד הקירוב וגילוי אור האלקי ביותר כו' וכן ביעקב במדת הרחמים שכלול מאהוי\"ר דיצחק כידוע היינו בביטול המציאות הכלול מאוי\"ר כידוע וד\"ל:\n(ב) <b>והנה</b> מטעם זה שהאבות היו בבחי' מרכבה היו כולם רועי צאן ובקר כמו שאמר ואברהם כבד מאד במקנה כו' ולא היו עוסקים רק במרעה צאן כמו שאמרו לפרעה רועי צאן עבדיך גם אנחנו גם אבותינו (כי מתחלה כשחלק קין והבל בעבודתם בארץ שהיה קין עובד אדמה והבל היה רועה צאן נמשך לאבות חלק זה דהבל רועה צאן דוקא כידוע) וע\"ד הפשוט הטעם הוא כי בכל העסקים זולת רועה צאן יש טרדא רבה מאד כמו גם בעבודת האדמה יש טרדא ודאגה בחרישה וזריעה וקצירה וכה\"ג בעבודת שדות וכרמים וכל עסקים כיוצא בהם אבל רועה צאן אין בעסק זה שום טרדא כלל ולא שום דאגה כלל וכל היום יוכל להיות פנוי מכל מחשבה בלתי לה' לבדו ואין מונע כלל להיות מתקשר ומתדבק בה' כל היום בלי פירוד כלל כו' (ובאמת הטעם הוא לפי שהאבות נק' רועים למעלה שהן זנין ומפרנסין לכל הנשמות וכמו רועה צאן ממש שעיקר עבודתו לרעות צאן במרעה טוב וכמ\"ש דוד ה' רועי לא אחסר כו' להשקותם ולשומרם מחיות כו') והנה גם השבטים היו רועי צאן כמ\"ש רועי צאן אנחנו כו' והוא מטעם שגם הם היו בחי' מרכבה שהוא בחי' הביטול במציאות כסוס לרוכבו כנ\"ל אך בחי' מרכבה שלהם היה למטה במדרגה מן האבות דהאבות הן המרכבה שנק' מרכבה עילאה בבחי' האצי' ממש שהן מדות חג\"ת דאצי' דאיהו וחיוהי חד ממש והוא בבחי' הביטול דשם מ\"ה בעצם שלמעלה הרבה מבחי' ביטול היש לאין כמ\"ש משה ונחנו מה כו' וכך אמר אברהם ואנכי עפר ואפר כו' אבל השבטים היו בחי' מרכבה בעולם הבריאה כמו ד' מחנות כו' וכפני אריה אל הימין כו' שזהו בחי' מל' דאצי' שמלובש בבריאה (והן י\"ב בקר שתחת יש\"ש כו') ואע\"פ שהוא ג\"כ בחי' ביטול במציאות ממש כמחנה מיכאל וגבריאל שאומרים תמיד שירה וכפני אריה כו' או שרפים שאומרים קדוש בתמידות עכ\"ז אין זה רק בחי' ביטול היש לאין בלבד מאחר שהן בבחי' עולם הבריאה שהוא בא מאין ליש ע\"י צמצום דבחי' אלקים כידוע וזהו שאמרו השבטים"],[2300680088,"ליעקב שהיה מרכבה בבחי' האצי' ממש בשם הוי' בבחי' ת\"ת כו' כשם שאין בלבך אלא אחד יחו\"ע דע\"ס דאצי' כך אין בלבנו בבחי' אצי' שבבריאה אלא אחד יחו\"ת למהוי אחד באחד כמו הוי' אחד ושמו אחד (וכמו שאמר כגוונא דאינון מתייחדין לעילא באצי' אוף הכי איהי בחי' מל' אתייחדת לתתא בכורסיא דבריאה כו') והנה יוסף לא היה רועה צאן מנעוריו כמ\"ש והוא נער את בני בלהה כו' ולא היה רועה עם אחיו בצאן וגם כשנמכר למצרים לעבד לפוטיפר היה איש טרוד גדול בעבודת הבית ועבודת השדה וכל אשר לפוטיפר הכל הי' עושה בטרדא ועבודה רבה בכל שכלו ודעתו בעמקות העסק בפרנסת הבית והיה איש מצליח מאד שהצליח ה' בכל מעשיו וכמ\"ש ויבא יוסף הביתה לעשות מלאכתו ות\"א בכתבי חושבני' שזה היה טרדא גדולה ועצומה ביותר וכ\"ש וק\"ו כשנעשה אח\"כ מלך על מצרים כמ\"ש על פיך ישק כו' רק הכסא כו' שמבלעדו לא ירים איש כו' והיה משגיח בחכמתו על כל הארץ בעומק המחשבה וטרדא גדולה שלא היה שום דבר נעשה בלעדו כו' ובפרט כשהשביר בר לכל עם הארץ שהיה עסקו עם כל העולם שבאו למצרים לשבר אוכל כו' וידוע (שבת יא, א) שחללה של רשות דמלוכה אין לה שיעור כלל כמ\"ש ולב מלכים אין חקר כו' וא\"כ האיך היה יוסף בחי' מרכבה בבחי' ביטול במציאות בעצם בבחי' האצי' ממש כמו האבות (כמשי\"ת) מאחר שהיה טרוד גדול כ\"כ בעומק המחשבה בעבודה רבה במלאכתו בבית ובשדה ובפרט כשהי' מלך ומושל על כל מצרים כנ\"ל דהרי מטעם זה היו האבות רועי צאן דוקא ולא עסקו בפרנסות אחרות הטורדים והמונעים הדביקות האמיתי ואיך יתכן לומר שלגבי יוסף לא הי' טרדא הגדולה כזאת שום מונע ובלבול כלל לבחי' הדביקות האמיתי שלו למעלה באצי' כו' וזהו פלא גדול לכאורה וד\"ל:\n(ג) <b>אך</b> הענין יובן בהקדים תחלה בשרש ענין החלומות ששרשם גבוה מאד נעלה בבחי' עיגולי' ומקיפי' דבחי' התוהו (כמ\"ש במ\"א ע\"פ בשוב ה' כו' היינו כחולמים באריכות) שבחלום יש ב' הפכים א' שיחלום שהוא בעילוי גדול ומיד יחלום שהוא בשפלות עצומה דבר והפוכו כאחד וכמו חיים ומות כאחד וכה\"ג בגילוי אלקות בנש\"י בגלות שנק' שינה הן בב' הפכיים מס\"נ בק\"ש ומיד עוסק בכל לבו במו\"מ ואין זה דבר והפוכו כלל כמו בחלום לפי שכל אחד ענין אמיתי בפ\"ע רק מה שבאו שניהם כאחד זהו מבחי' החלומות שמחבר ב' הפכים כו' וזהו הוראה על בחי' התוהו שהן באים בב' הפכים חסד לבדו ענין אמיתי בפ\"ע ודין לבדו ענין אמיתי בפ\"ע ובבחי' העיגולי' דתוהו הם באים הכל כאחד בלי התחלקות כלל כו' וכמו בעת השינה שמסתלקים כל כחות השכל ומדות בעצם הנפש בבחי' יחידה בעילוי אחר עילוי כו' ולא נשאר רק בחי' כח הדמיון שבמחשבה ואמנם הגם שבחי' הדמיון דחלומות הוא למטה מאד אבל שרשו הוא במקיף העליון דיחידה שעלו שם כל השכליים ורצונות ומקור כל הרצונות שכליים בעילוי מופלג בהתכללות"],[2300680104,"כא' דוקא כו' ומשם דוקא יומשך ויתלבש בכח הדמיון הרי כח החלום שבדמיון הוא ביחידה דשם הכל כא' באים בלי התחלקות רצון ושכל כאו\"א בפ\"ע כלל כמו העיגול שאין בו התחלקות כלל (וכמו התחלקות הרצון ושכל שבכמה שנים שנכלל הכל בעצם הנפש בהולדו או במותו כו') וכך כל מה שהי' כל רצון ושכל ענין אמיתי בפ\"ע נכללו כא' ביחידה שבנפש דבר והפוכו כא' ע\"כ יהיה בדמיון בחלום ג\"כ דבר והפוכו כא' לפי שכח הדמיון בחלום שרשו ביחידה ממש בשינה כו' והדוגמא מזה יובן ג\"כ בבחי' החלומות למעלה באדם העליון דאצי' (כידוע בענין דורמיטא כו' וכמו ותרדמה נפל על אברם כו') כמו בגלות שנק' שינה כמ\"ש עורה למה תישן ה' כו' שזהו בחי' עליות המדות וחכמה ורצון הכל למעלה בבחי' מקיפי' ועיגולי' דתוהו ששם אין בחי' התחלקות קוין דחג\"ת כלל (וכמ\"ש דבגלותא קודב\"ה אסתלק לעילא לעילא כו') שזהו עילוי יותר מופלג מגילוי האור דח\"ע ורצה\"ע בבהמ\"ק כו' וזהו בחי' החלומות למטה שהן בדמיון דבר והפוכו כא' בהיותו בבחי' שינה בגלות אבל שרשן הוא בעצמות המקיפים העליונים (כמו בחי' יחידה באדם למטה כנ\"ל) רק שמשם נמשך ומתלבש בדמיונות החלום (וע\"כ הי' כל מראה הנבואה בחלום דוקא כמ\"ש בחלום אדבר בו כו') ועל התלבשות זו בלבוש זר בדמיון דחלומות בזמן הגלות נאמר אלביש שמים קדרות כו' (כמ\"ש במ\"א באריכות) ולע\"ל יתעלו כל בחי' החלומות דזמן הגלות למעלה בשרשם במקיפים העליונים דבחי' העיגולים דתוהו ויופשטו מלבוש קדרות שלהם ויעלו בעילוי גדול במקיפים דתוהו וכמ\"ש ולא יכנף עוד כו' לפי שיהי' ה' אחד ושמו אחד שלא יסתיר הצמצום דשם אלקי' (כנ\"ל שם) ונמצא מובן עכ\"פ בשרש החלומות שהוא נעלה מאד רק שירדו למטה בלבוש הדמיון דחלום ואמנם אין תקונם רק ע\"י יוסף צ\"ע שנק' פותר חלומות דבחי' התוהו שהרי נתעלה רק ע\"י החלומות שכאשר פתר כן היה לפי שכל החלומות הולכים אחר הפה דתיקון שמתקן בפה לכל ההפכים שנמצאו בחלומות אמנם זהו דוקא ע\"י יוסף שהיה בבחי' שרש ומקור דתיקון דאצי' והוא הי' בחי' מלך הח' הדר כו' שהוא למעלה הרבה גם מז\"מ דתוהו ע\"כ יש ביכולתו לתקן לבחי' התוהו ומאחר שהוא עיקר ומקור לבחי' התיקון לתקן לבחי' התוהו (דהיינו שגם מה דבחי' התיקון דשם מ\"ה מתקן לתוהו בא מכח העליון דמלך הח' מקור התיקון) א\"כ הרי הוא גבוה מבחי' התוהו והתיקון כו' וזהו שהי' יוסף דוקא פותר חלומות לפי שהחלומות שבזמן הגלות שרשם בעיגולים ומקיפים דתוהו שיכול להיות שם ב' הפכים כו' וענין פתרון החלומות הוא שהולכים אחר הפה דיוסף דוקא להיותו שרש ומקור דבחי' התיקון שהוא מלך הח' הדר שלהיותו גבוה הרבה מבחי' התוהו והתיקון ע\"כ היה יכול לתקן החלומות ששרשם במקיפים דתוהו לפתור אותם לנכון דהיינו שע\"י הפתרון היה מעלה אותם ומבררם בחבור וסדר טוב להיות כל אחד על מקומו ענין אמת ולא יהיה ב' הפכים כלל כמו צירופי אותיות שהמה מבולבלים"],[2300680120,"ביותר יכול החכם הגדול ששכלו למעלה משכל הגנוז בצירופים הללו לעשות סדר טוב ונכון בשינוי אופני הצירופים שיהיו מסודרים באופן שיגלה תכלית הכוונה הטובה שבהם כו' וד\"ל:\n(ד) <b>וזהו</b> ענין פתרון החלומות שהולכים אחר הפה שהוא היודע לתקן ולעשות צירופים חדשים בכל ענין החלום לחבר כל ההפכים שבחלום שיהיה כל אחד על מקומו עד שכמו שיפתור אותו בפה כן יהיה אם לטוב או לרע להיות ששרש הפה דפותר הוא במקור התיקון שלמעלה משרש החלומות ע\"כ יכול בכחו לפתור החלום באופן שירצה לטוב ורע כו' וזהו שהי' יוסף פותר חלומות לשר המשקים ולשר האופים וכאשר פתר כן היה לזה לטוב ולזה לרע כו' מפני שכל החלומות הולכין אחר הפה של הפותר שהוא בחי' יוסף דוקא להיותו למעלה מבחי' התוהו והתיקון כו' ע\"כ יכול להעלות לאותיות דחלום ולהביאם למעלה לעשות בהם חיבור וקשר ליחד כל ההפכים באופן שיהיה מוכשר ונכון ע\"פ קו המדה דוקא שמודד ושוקל שיהיה הכל במדה נכונה כפי הצריך לענין הבירור והתיקון דשם מ\"ה שמברר לב\"ן דתוהו ע\"ד דוגמא ממה שאנו רואים בבחי' התיקון דשם מ\"ה בתו' שלנו שנתן במדה ושיעור בכל המצות כמו תפילין בד' בתים ול\"ב חוטי ציצית כו' וכן בסו\"מ דל\"ת בדקדוקי' שונים באיסור והיתר טמא וטהור כשר ופסול חייב זכאי כו' אע\"פ שזהו הכל ענין ואופן הבירור דשם מ\"ה דחכמה שמברר לב\"ן דנוגה כו' אבל זהו גופא למה אופן הבירור כך וכך ולא באופן אחר לגמרי בודאי בהכרח לומר שכבר הוברר החכמה הזאת דשם מ\"ה דתורה בבחי' החכמה הקדומה שיהיה אופן החכמה דתורה בבירור כך ולא כך במידה ושיעור כמו מי מדד בשעלו מים כו' וכן ענין איה סופר איה שוקל כו' כמו שוקל במאזנים בכח החכמה העצמיות איך יהיה גילוי אופן השכל בדבר מה לתקנו אם כך או כך עד שהוברר בכח החכמה שיהיה מציאת השכל לתקן הדבר באופן כך וכך דוקא שזהו הנק' חכמה ושכל ברור מכבר שכבר הוברר ונשקל בכח ומקור החכמה שאין להוסיף ולגרוע עליו כלל כך חכמה דתורה ברורה מכח החכמה דעצמות והוא שנק' מתקלא וקו המדה כמ\"ש כל אמרת אלוה צרופה אל תוסף כו' (וכמ\"כ בענין המדידה במע\"ב בשמים וארץ וכל אשר בהם בחלקי דצח\"מ וכל העולמות העליונים הרוחנים כמלאכים דבי\"ע בדקדוק אופן ציורם כמו שש כנפים לאחד והחיות בציורם כמו קרסולי ושוקי החיות עד ציור אופן כל הברואים למטה בחלק החי למיניהם בהמה בד' רגלים ועוף בב' רגלים וציור אדם וציור הארץ וכן אופן מדידת כל הציור כו' הכל היה בכח החכמה שקדמה לחכמה דמע\"ב שכולם בחכמה עשית וכן מי מדד בשעלו מים כו' ע\"ד הנ\"ל בחכמה שבתורה באופן התיקון שבחכמה אתברירו שיש לכל זה מקור מיוחד שנברר מכבר כו' וד\"ל). וכך יובן גם כאן בענין פתרון חלומות דאיך שיהיה אופן התיקון בצירופים זרים דלבוש שק דחלומות שנפל מבחי' התוהו כנ\"ל זהו מכבר הוברר במקור החכמה בבחי' קו המדה שנק' מקור התיקון דשם מ\"ה וזהו בחי' מלך הח' הדר כנ\"ל שהוא בחי' יוסף"],[2300680136,"צ\"ע שהיה יודע איך לתקן הצירופים הללו (שהוא בחי' החלומות בשינה דגלות השכינה כו' וד\"ל). וזהו בן פורת יוסף אותיות תופר ואותיות פותר דהכל א' דהנה מבואר למעלה דפותר החלומות היינו שמחבר ומקשר כל ההפכים שנמצאו שיהיה בסדר נכון שישכנו יחדיו ע\"פ מדה נכונה ממאמר קו המדה (כמו בחי' מתקלא הנ\"ל בחלומות ומדידת העולמות ונבראים שנבנו בקו המדה כנ\"ל) וזהו הנק' ג\"כ תופר כמו התופר בחוט לבגד שנחתך לכמה חתיכות קטנות ובחוט התפירה מחברם יחד באופן מתוקן ללבוש כפי המדה הצריכה דוקא כו' וכך הוא ממש ענין החבור בפתרון החלומות שמיחד את הנפרד כנ\"ל וד\"ל ומה שנק' בן פורת כו' שהוא אותיות פותר הענין הוא דעיקר ענין הפתרון בחלומות הוא שמעלה אותם הצירופים למעלה משרשם הרבה ששם דוקא יכול לתקנם ולחברם כנ\"ל. אך להיות שממנו דוקא יבא שרש בחי' התיקון שלמטה שהוא בא בבחינת ריבוי ההתחלקות האורות בכלים מכלים שונים (מצד ריבוי ההתכללות כידוע) ע\"כ נק' פורת לשון פרה ורבה כמו ופרינו בארץ דהיינו שמפרה ומרבה את האורות בכלים רבים לאין שיעור כמו ענין פו\"ר שמוליד לאין שיעור כו' כך בחי' יוסף שהוא צ\"ע כמו שהוא בשרשו למעלה ממש במקור התיקון נק' פותר חלומות או תופר ומה שבא מזה דוקא לאופן התיקון דשם מ\"ה דחכמה למטה לברר לבחי' ב\"ן דתוהו בריבוא רבבות התחלקות לאין שיעור נק' פורת שמפליא להרבות האו\"כ עד אין קץ כו' וד\"ל. וזהו הטעם לקריאת שמו יוסף כמ\"ש בן פורת יוסף לפי שלשון יוסף ביוד ענין להבא שתמיד יוסף האור והשפע בהוספה רבה וריבוי גדול שזהו מה שהוא תמיד מוסיף השפע בריבוי התחלקות או\"כ עד אין קץ כו' (וכמו יוסף ה' עליכם אלף פעמים כו' וכן יוסף ה' עליכם ועל בניכם כו' שזהו בחי' צ\"ע דאור זרוע בתמידות לצ\"ע בכל דור בנש\"י להוסיף ולהגדיל האור בריבוי התחלקות לאין קץ כו' וד\"ל). וזהו ג\"כ הטעם שהי' יוסף יפה תואר ויפה מראה כי ידוע בענין יפה תואר ויפה מראה שזהו ציור התמונה בכלים ואברים במזיגה נכונה מאד לא יוסיף ולא יגרע מכפי הצריך לענין יופי התואר נק' יפה תואר וטוב המזיגה וההתכללות בגוונין ומראות דלבן ואדום וירוק שעירובם מתחברים יחד באופן נאה מאד לפי הצריך לתכלית יופי המראה זהו נק' יפה מראה במזיגה יפה בגוונין ולמעלה היינו בחינת התיקון שבא במזיגה יפה ומדה נכונה בין באורות שנק' גוונין ומראות חג\"ת ופרטיהם שנק' יפה מראה וכן בכלים שנק' תואר שגם בהם יש מדה ומזיגה יפה שנק' יפה תואר כו' (וכמו בתו\"מ שנק' או\"כ שבאים ע\"פ שם מ\"ה דתיקון הכל במדה ומזיגה יפה נק' כנ\"י יפ\"ת וכן ישראל אשר בך אתפאר ובחי' המשפיע דתו\"מ לכנ\"י שהוא בחי' יוסף צ\"ע נק' יפ\"ת ויפ\"מ והוא מצד שרשו במקור דתיקון שנק' מלך הח' כו' כנ\"ל שממנו נמצא שרש התיקון למטה להיות אופן המדידה הנכונה באו\"כ במזיגה יפה בתואר ובמראה הכל לפי החכ' הקדומה שבמאמר קו המדה כו' ע\"כ נק' יפ\"מ וד\"ל). ובכל הנ\"ל יובן שרש בחי' יוסף ומעלתו הנבדל בערך על השבטים גם על האבות (שהרי"],[2300680151,"יעקב השתחוה על ראש המטה שחלק כבוד למלכות דיוסף שהוא מלך הח' מקור התיקון דיעקב כו') שמצד שרשו במקור דתיקון ותוהו כנ\"ל. ע\"כ לא היה יוסף רועה צאן כלל כאבות שנק' רועים שרועים ומפרנסים לנש\"י שנק' צאן שהוא בחי' התיקון כידוע בחג\"ת דאבות כו' וכש\"כ השבטים שהן בבחי' עולם הבריאה כו' כנ\"ל כי יוסף היה למעלה מבחי' התיקון והוא מלך הח' רק שממנו נמצא שרש לבחי' התיקון וע\"כ היה פותר חלומות דתוהו כנ\"ל וזהו שהי' טרוד גדול בצירופים זרים בכתבי חושבני' כנ\"ל בטרדא רבה ועצומה מאד בעסק העבודה בבית ושדה וגם בהיותו מלך ומושל ומשביר לכל הארץ ולא הפסיק לו דביקתו האמיתית כמו שהוא למעלה ממש שלא היה כזה באבות שהיו מרכבה בבחי' האצי' ממש כנ\"ל מטעם כל הנ\"ל וד\"ל:\n(ה) <b>והנה</b> להבין ולהשכיל מכל הנ\"ל בבחי' יוסף שהיה מרכבה למעלה והיה טרוד גדול בעסקים גדולים ופרטים רבים ולא היו מבלבלים דביקתו למעלה כלל מטעם הנ\"ל שהיה שרשו בשרש התיקון דמלך הח' ע\"כ היה פותר חלומות כו'. הנה יובן כ\"ז בתוס' ביאור למעלה מעלה ג\"כ והוא בבחי' מהו\"ע אור א\"ס ב\"ה ממש דגם שאין לו גוף ואין לו דמות הגוף כו' כי לא אדם הוא כו' וכמ\"ש כי לא ראיתם כל תמונה כו' עכ\"ז הרי בצלם אלקים עשה את האדם ודברה תורה כו' לזאת ודאי יש בדוגמא דלמטה בחי' יוסף צ\"ע הנ\"ל גם למעלה מעלה כמ\"ש כי צדיק ה' כו' והוא שאמר אור זרוע לצדיק שהוא צ\"ע ממש דהיינו בחי' סוכ\"ע הכללי שלמעלה מכל ההשתלשלות דקו\"ח כו' כידוע דעצמות אוא\"ס ממש שלפני הצמצום הראשון שנק' מקו\"פ וחלל ריקן כו' היה פשוט בתכלית הפשיטות ומובדל בערך לגמרי מהיות גם בחי' מקור למקור לכל ההשתלשלות דאבי\"ע ואף גם כי כל האור והשפע הנמשך להיות מקור להשתלשלות דע\"ס או\"כ אינו בא רק ע\"י בחי' אותיות דעצמות המאציל ששרשם באותיות דטה\"ע דגליף גליפו כו' כמו ע\"י אותיות דשם ע\"ב נמשך מקור להאציל לאור החכ' וכמ\"כ יש אותיות דשם אהי' להאציל לאור הכתר שהוא הרצון וכה\"ג לכל האורות דאצי' וגם למע' מן האצילות בראשית המשכת הקו\"ח כו' שנק' א\"ק כו' עכ\"ז הרי מהות ועצמות המאציל הוא מרומם ומובדל למעלה מעלה גם מבחי' אותיות כי בחי' האותיות אינו רק בחי' גילוי ההעלם מהעצמו' בבחי' פרט כמו אותיות גילוי הרצון ואותיות גילוי השכל כו' דכלא ממש חשיב כו' וד\"ל. אך הנה עכ\"ז אנו רואים שיש בחי' ירידה והמשכה והתלבשות מעצמות א\"ס ב\"ה בהשתלשלות העולמות בבחי' כללות עכ\"פ ע\"ד שהוא נתפס ומלובש בזה ממש כו'. והוא הנק' בחינת מחשבה א' הכללית שאנו אומרים שבמחשבה א' הוא צופה ומביט עד סוף כל הדורות בסקירה א' דענין צופה ומביט זהו בחינת אותיות המחשבה דוקא כמו שאדם צופה ומביט במחשבתו על כללית מעשה הבנין מראשו לסופו שנסקר אצלו באותיות המחשבה בסקירה א'. כך כללות כל הדורות העליוני' ותחתונים מראשית הקו\"ח עד סופו בכל שית אלפי שנין ואלף הז' כו'"],[2300680166,"נסקר הכל באותיות מח' חכמתו ית' בסקירה א' ממש שזהו בהכרח שנתפס במחשבה זו הכללית כי הרי ממנו הכל נמצאו ואין לך דבר חוץ מעצמו ית' כמ\"ש כי ממך הכל כו' ועמך מקור כל החיים העליונים והתחתונים רק שנמשך ממנו אחר הצמצום הראשון שנק' מקו\"פ וחלל כו' שנתעלם תחלה אור העצמות ונשאר רק רושם הארה בעלמא דקו\"ח כו' שאל\"כ היה הכל בבחי' א\"ס ממש כידוע. וא\"כ לפ\"ז מוכרח לומר דמה שצופה ומביט לכללות הכל בסקירה אחת זהו כמו עד\"מ באדם למטה שבידיעת עצמו שצופה במחשבה על כל עצמות שלו מראשו לרגלו נסקר אצלו בסקירה אחת בבת אחת מבלי קדימה לאחד על זולתו שלא בסדר והדרגה מראשו לרגלו או מתחלת רצונו לסוף מעשה אלא הכל כאחד והוא מה שיש בכח הנפש להרגיש א\"ע הרגשה כללית מכללות חיות הנפש בגוף מראש לרגל בסקירה אחת כו'. וכך יובן למעלה מעלה שבידיעת עצמו ית' יודע ומביט כללות כל ההשתלשלות דאבי\"ע מריש כל דרגין שלפני האצי' עד סוף הכל כולו נסקר בסקירה אחת ממש מבלי קדימה מראש לסוף כלל אלא ראש וסוף כאחד (וזהו ברוך שאמר במחשבה אחת (בבחי' מקיף כללי כמח' עיגולי' שתופסת בכללי' בסקירה אחת) והיה העולם בכללו') (וכמו בכל ר\"ה שמתחדש חידוש כללי ממקור תחלת הרצון שבמחשבה הא' כו' אומר זה היום תחלת מעשיך שכולל הכל זכרון ליום ראשון שהוא בחי' מחשבה הכללית הנ\"ל וע\"כ אומר כל היצור לא נכחד כו' מי לא נפקד כו' שכולם עולים במחשבה הכללית וז\"ש אתה זוכר כו' ופוקד כל יצורי קדם שעלו במחשבה הקדומה ואין פרט נבדל מן הכלל מאחר שממנו יצא בגילוי והתחלקות לבד כו'). אך הנה לפי זה בהכרח לומר שהוא ית' נתפס במח' כללית זאת אחר שזהו כמו ענין ידיעת עצמו באדם שנתפס בהרגשה זו הכללית כו' ובאמת הרי אמר אנת הוא עילאה כו' סדכ\"ס למתב\"כ דמשמע אפי' מח' הכללית אינה תופס מקום בעצמות כלל כי כלא חשיב ממש ואע\"ג דתפיס בכ\"ע למדתב\"כ וכמאמר הוא מקומו של עולם ואין העולם מקומו כלל אפי' מח' הכללית הנ\"ל והשכל מחייב כך מאחר שגם מחשבה זו בגדר שפע באה בדרך כלל עכ\"פ שהוא כללות ההשתלשלות שיש לו ראש וסוף עכ\"פ והוא עצמו ית' מובדל ומרומם לבדו כו' למעלה מבחי' ראש וסוף שאין לו תחלה ואין לו תכלה כו' כידוע וא\"כ מה שמתצמצם המחשבה כללית להיות צופה ומביט לכל הדורות כו' ודאי שאינו נתפס בזה כלל וכלל שלא כמשל בידיעת עצמו הנ\"ל לפי שאין ערך כלל בין ידיעה שיודע לכל ההשתלשלות לידיעת עצמו ממש שהוא בבחי' א\"ס ממש ומה שנמשך מאתו הכל אינו רק ע\"י צמצום אור העצמות לגמרי כנ\"ל וד\"ל:\n(ו) <b>והנה</b> ראיה ברורה לזה הוא ממה שמצינו במ\"ש מי כהוי' אלקינו המגביהי לשבת המשפילי לראות בשמים ובארץ כו' וכן אמר משמים הביט ה' ראה את כל בני האדם ממכון שבתו השגיח על כל יושבי הארץ היוצר יחד לבם המבין אל כל מעשיהם שהרי יש כאן שני הפכים בנושא אחד ממש דאם מגביהי לשבת למעלה מעלה בבחי'"]]});
